(window.DEEP=window.DEEP||{})['comp']={"T":{"comp-01":"الأدب المقارن: يعني إيه؟","comp-02":"ليه ندرس الأدب المقارن؟ والأدب العالمي","comp-03":"الأدب المقارن الصغير والكبير","comp-04":"المصطلحات اللي هتحتاجها في الكورس","comp-05":"نشأة الأدب المقارن: ليه القرن التسعتاشر؟","comp-06":"الرواد الأوائل: من جوته لبوسنيت وميلتزل","comp-07":"المدرسة الفرنسية والوضعية","comp-08":"ركائز المدرسة الفرنسية: التأثير والمصدر والاستقبال","comp-09":"المدرسة الأمريكية: الثورة على الوضعية","comp-10":"التناص: من التأثير لحوار النصوص","comp-11":"الترجمة والمترجم في الأدب المقارن","comp-12":"المدرسة الصينية ونظرية التغاير","comp-13":"النسوية: يعني إيه؟ ومن فين جت الفكرة؟","comp-14":"الموجة الأولى: من التنوير لحق التصويت","comp-15":"الموجة التانية: الشخصي سياسي","comp-16":"الموجة التالتة: التقاطع والاختلاف","comp-17":"الموجة الرابعة: الإنترنت والشارع","comp-18":"سيمون دي بوفوار و«الجنس التاني»","comp-19":"قراءة نسوية للرواية: الحكاية والبنية","comp-20":"العلاقات والسلطة: قراءة أعمق","comp-21":"قاموس الكورس: المصطلحات في مكانها","comp-22":"المراجعة: إزاي تبني إجابة قوية"},"P":[{"i":"comp-01","s":1,"h":"مقدمة","t":"learn","x":"أهلا بيك في أول درس في الأدب المقارن. الكورس ده بيبدأ من الصفر. مش محتاج تكون قريت قبل كده عن النقد ولا عن تاريخ الأدب."},{"i":"comp-01","s":2,"h":"مقدمة","t":"learn","x":"في كل درس أدب إحنا بنقارن من غير ما نسميها مقارنة: قصيدة بقصيدة، ورواية برواية، وشاعر بشاعر. فإيه الجديد في مادة اسمها «أدب مقارن»؟"},{"i":"comp-01","s":4,"h":"1) التعريف","t":"learn","x":"أشهر تعريف عملي للمجال جه من Henry Remak سنة 1961. الأدب المقارن هو دراسة الأدب خارج حدود بلد واحد، ودراسة علاقته بمجالات المعرفة التانية: الفنون، والفلسفة، والعلوم الاجتماعية، والعلوم، والدين."},{"i":"comp-01","s":5,"h":"1) التعريف","t":"learn","x":"وباختصار: مقارنة أدب بأدب تاني، ومقارنة الأدب بمجالات تانية من التعبير الإنساني."},{"i":"comp-01","s":6,"h":"1) التعريف","t":"learn","x":"قسم اللغة الإنجليزية بيدرس أدب لغة واحدة: الإنجليزي وتاريخه ومصطلحاته. الأدب المقارن بيدرس العلاقة بين أدبين أو أكتر، أو بين الأدب ومجال تاني."},{"i":"comp-01","s":7,"h":"1) التعريف","t":"learn","x":"مثال: بحث عن أثر «ألف ليلة وليلة» في الرواية الأوروبية. البحث ده مكانه هنا، مش في قسم اللغة الإنجليزية لوحده."},{"i":"comp-01","s":8,"h":"1) التعريف","t":"learn","x":"كلمة «مقارن» هنا مش معناها إننا بنختار نصين ونقول مين أحسن. معناها إننا بنعدي حدود: حدود اللغة، وحدود البلد، وحدود التخصص نفسه."},{"i":"comp-01","s":9,"h":"1) التعريف","t":"learn","x":"لما تقارن رواية مصرية برواية إنجليزية، عديت حدود اللغة والبلد. ولما تدرس إزاي الترجمة غيرت الرواية، عديت كمان حدود التخصص ورحت للترجمة."},{"i":"comp-01","s":11,"h":"2) تلات أمثلة","t":"learn","x":"مثال 1: قصيدة عربية وقصيدة إنجليزية عن نفس الموضوع، زي الفخر أو الحنين للوطن. مثال 2: رواية اتحولت لفيلم. مثال 3: رواية مترجمة للغة تانية."},{"i":"comp-01","s":12,"h":"2) تلات أمثلة","t":"learn","x":"في التلاتة السؤال واحد: إيه اللي حصل لما النص عدى من ثقافة لثقافة؟ إيه اللي اتنقل، وإيه اللي اتغير، وإيه اللي القارئ الجديد فهمه؟"},{"i":"comp-01","s":13,"h":"2) تلات أمثلة","t":"learn","x":"الأدب المقارن بيسأل عن العلاقة، مش عن الحكم. مش بيسأل: مين الأول ومين الأحسن؟ بيسأل: إزاي النص اتدور، واتقرأ، واتفهم في مكان تاني؟"},{"i":"comp-01","s":15,"h":"3) مجالات المجال","t":"learn","x":"التبادل بين الثقافات : إزاي الأدب بيستخدم للتفاهم بين الثقافات. وكمان إزاي الأدب بيقاوم الصور النمطية عن الثقافات التانية."},{"i":"comp-01","s":16,"h":"3) مجالات المجال","t":"learn","x":"الأدب العابر للحدود : أدب بيتخطى الحدود القومية. زي كتابات المهاجرين، أو الكتاب اللي بينتموا لأكتر من ثقافة."},{"i":"comp-01","s":17,"h":"3) مجالات المجال","t":"learn","x":"دراسات الترجمة : صعوبات ترجمة الأدب ومكافآتها. الأدب العالمي : الأدب اللي بيدور خارج بلده الأصلي، وإزاي بيتقرأ في سياق عالمي."},{"i":"comp-01","s":18,"h":"3) مجالات المجال","t":"learn","x":"وفيه مجال خامس: علاقة الأدب بالتخصصات التانية. الأدب مع التاريخ، والفلسفة، وعلم الاجتماع، واللغة."},{"i":"comp-01","s":19,"h":"3) مجالات المجال","t":"learn","x":"المجال بيدرس أنواع كتير: الرواية، والشعر، والمسرح، والفيلم. مش لازم النصين يكونوا من نفس النوع. مقارنة رواية بفيلم شغل مقارن معتبر."},{"i":"comp-01","s":21,"h":"4) إيه اللي مش من المجال","t":"learn","x":"مش حكم على الجودة: «شكسبير أحسن من المتنبي» رأي، مش بحث مقارن. مش مقارنة نصين بنفس اللغة ومن نفس البلد من غير أي سؤال عن الحدود: ده نقد عادي."},{"i":"comp-01","s":22,"h":"4) إيه اللي مش من المجال","t":"learn","x":"ومش قايمة «أفضل مية كتاب في العالم». القوايم مفيدة للقراءة، بس مش بحث."},{"i":"comp-01","s":24,"h":"5) خريطة الكورس","t":"learn","x":"الكورس ده 6 وحدات: 1) أساسيات الأدب المقارن. 2) المدرسة الفرنسية. 3) المدرسة الأمريكية والترجمة. 4) النسوية وموجاتها. 5) سيمون دي بوفوار وكتاب الجنس الآخر. 6) التطبيق على رواية ألف شمس رائعة."},{"i":"comp-01","s":25,"h":"5) خريطة الكورس","t":"learn","x":"وطريقة الشغل: كل درس كروت صغيرة، كل كارت فكرة واحدة بمثال، وبعد كل فكرة سؤال. وفي آخر كل درس أسئلة كتابة، وإجابتها النموذجية بتظهر بعد ما تكتب إجابتك إنت."},{"i":"comp-01","s":26,"h":"5) خريطة الكورس","t":"mc","x":"إيه الأدق في وصف الأدب المقارن؟ ؟ دراسة الأدب خارج حدود بلد واحد وعلاقته بمجالات المعرفة التانية / مقارنة نصين واختيار الأفضل بينهم / ترجمة النصوص الأدبية للعربية / دراسة أدب بلد واحد بعمق . تعريف Remak: دراسة الأدب خارج حدود بلد واحد، وعلاقته بمجالات المعرفة التانية."},{"i":"comp-01","s":27,"h":"5) خريطة الكورس","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ الأدب المقارن بيسأل عن العلاقة بين النصوص، مش عن مين أحسن. / الأدب المقارن بيدرس بس النصوص اللي من نفس النوع الأدبي. / التشابه بين نصين لوحده يثبت إن فيه تأثير. / الأدب العالمي منهج، والأدب المقارن ظاهرة. . السؤال عن العلاقة والانتقال بين الثقافات."},{"i":"comp-01","s":28,"h":"5) خريطة الكورس","t":"mc","x":"أي واحد من دول مش من شغل الأدب المقارن؟ ؟ مقارنة رواية بفيلمها / قصيدة عربية وقصيدة إنجليزية عن الحنين / رواية وترجمتها للغة تانية / ترتيب أفضل عشر روايات في العالم . الترتيب رأي، مش بحث."},{"i":"comp-01","s":29,"h":"5) خريطة الكورس","t":"mc","x":"مين Henry Remak؟ ؟ باحث قدم تعريف مشهور للأدب المقارن سنة 1961 / شاعر إنجليزي من القرن التسعتاشر / مؤسس المدرسة الفرنسية / مترجم روايات روسية . تعريفه من أشهر تعريفات المجال."},{"i":"comp-01","s":30,"h":"5) خريطة الكورس","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ أنهي جملة من دول صحيحة؟ / الأدب المقارن بيدرس بس النصوص اللي من نفس النوع الأدبي. / بالعكس: الأدب العالمي ظاهرة، والأدب المقارن منهج. / المقارن الكبير بيدخل مجالات برة الأدب زي الفلسفة والفنون. . النوع مش شرط، الشرط هو تعدي الحدود."},{"i":"comp-01","s":31,"h":"5) خريطة الكورس","t":"mc","x":"إيه الفرق الأساسي بين قسم اللغة الإنجليزية والأدب المقارن؟ ؟ الأول بيدرس أدب لغة واحدة، والتاني بيدرس العلاقة بين أدبين أو أكتر / الأول بيقرا، والتاني بيحفظ / الأول للطلبة، والتاني للدكاترة / مفيش فرق خالص . الأول أدب قومي، والتاني علاقات بين الآداب."},{"i":"comp-01","s":32,"h":"5) خريطة الكورس","t":"recall","x":"عرف الأدب المقارن في سطرين بكلامك. . الأدب المقارن دراسة الأدب خارج حدود بلد واحد، ودراسة علاقته بمجالات المعرفة التانية. وباختصار: مقارنة أدب بأدب تاني، ومقارنة الأدب بمجالات تانية من التعبير الإنساني."},{"i":"comp-01","s":33,"h":"5) خريطة الكورس","t":"recall","x":"اذكر تلات مجالات بيدرسها الأدب المقارن. . التبادل بين الثقافات، والأدب العابر للحدود، ودراسات الترجمة، والأدب العالمي، وعلاقة الأدب بتخصصات زي التاريخ والفلسفة."},{"i":"comp-01","s":34,"h":"5) خريطة الكورس","t":"write","x":"قارن بين دراسة قصيدة عربية وقصيدة إنجليزية عن نفس الموضوع، ودراسة رواية مترجمة: إيه السؤال اللي بيسأله الباحث في كل حالة، وإيه اللي بيتغير؟ (5 ل 7 جمل) . في الحالة الأولى الباحث بيسأل عن التشابه والاختلاف في الطريقة اللي كل ثقافة بتعالج بيها الموضوع، وعن الأسباب الثقافية والتاريخية للاختلاف. في الحالة التانية الباحث بيسأل عن الترجمة نفسها: إيه اللي اتحول، وإيه اللي ضاع، وإزاي القارئ الجديد فهم النص. اللي بيتغير هو موضوع البحث: مرة على النصوص نفسها، ومرة على الوسيط اللي بينقل النص. والاتنين بيتفقوا إن السؤال عن العلاقة والانتقال، مش عن الحكم."},{"i":"comp-01","s":35,"h":"5) خريطة الكورس","t":"write","x":"قارن بين تعريف الأدب المقارن ك«مقارنة نصين» وتعريفه ك«دراسة العلاقات بين الثقافات»: أيهما أدق، وليه؟ (5 ل 7 جمل) . التعريف الأول ضيق، لأنه بيحول المادة لحرفة مقارنة نصين، ومش بيقول ليه بنقارن ولا إيه اللي بندور عليه. التعريف التاني أدق، لأنه بيحدد الموضوع: إزاي الأدب بيدور بين الثقافات، وإزاي بيتقرأ ويتفهم في سياق جديد. التعريف الأول ممكن يبقى جزء من التاني، لكنه مش بديل عنه."},{"i":"comp-02","s":1,"h":"مقدمة","t":"learn","x":"في الدرس اللي فات عرفنا إن الأدب المقارن دراسة الأدب خارج حدود بلد واحد، وعلاقته بمجالات المعرفة التانية. النهاردة سؤالين: ليه أصلا ندرس المجال ده؟ وإيه حكاية «الأدب العالمي» اللي بنسمعها كل شوية؟"},{"i":"comp-02","s":3,"h":"1) ليه ندرس الأدب المقارن؟","t":"learn","x":"أول سبب بسيط: حرية الاختيار. في مجال زي ده، الطالب بيقدر يكون برنامج دراسة يناسب اهتمامه."},{"i":"comp-02","s":4,"h":"1) ليه ندرس الأدب المقارن؟","t":"learn","x":"لو مهتم بالعلاقات بين الآداب، أو بآداب مش بتدرس مع بعض عادة، أو بالأدب المترجم، أو بالنظرية، المجال بيدي مساحة لكل ده."},{"i":"comp-02","s":5,"h":"1) ليه ندرس الأدب المقارن؟","t":"learn","x":"تاني سبب: المقارنة بتخليك تفهم اللي عندك أحسن. لما تشوف ثقافة تانية بتعمل نفس الحاجة بطريقة مختلفة، بتفهم ثقافتك إنت، وبتشوفها من برة."},{"i":"comp-02","s":6,"h":"1) ليه ندرس الأدب المقارن؟","t":"learn","x":"مثال: حد بيتكلم لهجته ومش واخد باله منها، لحد ما يسمع لهجة تانية. ساعتها بيسمع نفسه."},{"i":"comp-02","s":7,"h":"1) ليه ندرس الأدب المقارن؟","t":"learn","x":"تالت سبب: أدوات بدل الأحكام السريعة. المجال بيعلمك تسأل: إيه اللي اتنقل؟ إزاي اتنقل؟ مين نقله؟ وليه اتحول؟"},{"i":"comp-02","s":8,"h":"1) ليه ندرس الأدب المقارن؟","t":"mc","x":"إيه أهم فايدة منهجية لدراسة الأدب المقارن؟ ؟ إنه بيديك أدوات وأسئلة محتاجة دليل، بدل الأحكام السريعة / إنه بيخليك تحفظ أسماء الكتاب / إنه بيلغي الحاجة لدراسة اللغة / إنه بيثبت إن أدبك أحسن من غيره . المجال بيديك أسئلة عن الانتقال والتحول، وإجابتها محتاجة دليل."},{"i":"comp-02","s":9,"h":"1) ليه ندرس الأدب المقارن؟","t":"learn","x":"ودي أسئلة محتاجة دليل من النصوص والتاريخ، مش مجرد إحساس."},{"i":"comp-02","s":11,"h":"2) الأدب العالمي: التعريف","t":"learn","x":"لكلمة «أدب عالمي» تعريفين مشهورين. الأول: مجموع الآداب القومية كلها في العالم."},{"i":"comp-02","s":12,"h":"2) الأدب العالمي: التعريف","t":"learn","x":"التاني: الأدب اللي بيدور خارج ثقافته الأصلية، سواء بالترجمة أو باللغة الأصلية. التعريف التاني هو اللي بيستخدمه الباحثين أكتر، لأنه بيسأل عن الحركة، مش عن الجمع."},{"i":"comp-02","s":13,"h":"2) الأدب العالمي: التعريف","t":"learn","x":"David Damrosch سنة 2003 حدد شرطين للعمل عشان يدخل الأدب العالمي: 1) يتقرأ كأدب. 2) يعدي حدوده اللغوية والثقافية، ويوصل لقراء في مكان تاني."},{"i":"comp-02","s":14,"h":"2) الأدب العالمي: التعريف","t":"mc","x":"حسب Damrosch، إيه الشرطين اللي بيخلوا العمل أدب عالمي؟ ؟ إنه يتقرأ كأدب، وإنه يعدي حدوده اللغوية والثقافية / إنه يبقى أكثر مبيعا في بلده / إنه يتكتب بالإنجليزية / إنه يبقى فيلم . الشرطين: يتقرأ كأدب، ويعدي حدوده اللغوية والثقافية."},{"i":"comp-02","s":15,"h":"2) الأدب العالمي: التعريف","t":"learn","x":"يعني العمل مش أدب عالمي لمجرد إنه مشهور في بلده."},{"i":"comp-02","s":16,"h":"2) الأدب العالمي: التعريف","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ المقارن الكبير بيدخل مجالات برة الأدب زي الفلسفة والفنون. / العمل يبقى أدب عالمي لمجرد إنه مشهور في بلده. / بالعكس: الأدب العالمي ظاهرة، والأدب المقارن منهج. / ده تاريخ أدب، لأنك بتدرس أدب واحد. . لازم يعدي حدوده اللغوية والثقافية ويوصل لقراء برة."},{"i":"comp-02","s":17,"h":"2) الأدب العالمي: التعريف","t":"learn","x":"رواية مصرية اتترجمت واتقرأت في أمريكا: أدب عالمي. رواية مش اتترجمت ومحدش قراها برة بلدها: أدب قومي، بالمعنى التاني."},{"i":"comp-02","s":18,"h":"2) الأدب العالمي: التعريف","t":"learn","x":"مثال من الواقع: كتير من الأعمال العربية بقت أدب عالمي بعد الترجمة، مش قبلها."},{"i":"comp-02","s":20,"h":"3) جوته والمصطلح","t":"learn","x":"المصطلح الألماني Weltliteratur مرتبط ب Goethe. هو استخدمه في حواراته مع Eckermann في يناير 1827."},{"i":"comp-02","s":21,"h":"3) جوته والمصطلح","t":"learn","x":"المصطلح نفسه كان موجود قبله بفترة، لكن جوته هو اللي خلاه ينتشر ويبقى معروف."},{"i":"comp-02","s":22,"h":"3) جوته والمصطلح","t":"learn","x":"جملة جوته المشهورة في الحوار ده: «الأدب القومي بقى مصطلح شبه فاضي؛ عصر الأدب العالمي قرب، وكل واحد لازم يساعد إنه يجي أسرع.» المعنى: بدل ما كل أمة تقفل على أدبها، بقى فيه سوق عالمي للأفكار الأدبية."},{"i":"comp-02","s":23,"h":"3) جوته والمصطلح","t":"mc","x":"إيه معنى جملة جوته عن الأدب العالمي؟ ؟ الأدب بقى سوق تبادل بين الأمم، مش كل أمة قافلة على أدبها / الأدب الإنجليزي هو الأهم في العالم / لازم كل الناس تكتب بالألماني / الأدب القومي انتهى خلاص ومبقاش موجود . الفكرة شبكة تبادل بين الأمم، مش تفوق أمة على أمة."},{"i":"comp-02","s":24,"h":"3) جوته والمصطلح","t":"learn","x":"جوته مكنش بينظر من بعيد: كان بيقرأ الصيني والفارسي والصربي والفرنسي واليوناني."},{"i":"comp-02","s":25,"h":"3) جوته والمصطلح","t":"learn","x":"فكرته كانت شبكة تبادل بين الأمم، مش قايمة كتب «أحسن الأعمال»."},{"i":"comp-02","s":27,"h":"4) الجدل حول الأدب العالمي","t":"learn","x":"فيه نقد مهم للفكرة. في الماضي، «الأدب العالمي» كان غالبا معناه أعمال غربية في المقام الأول، والباقي بيدخل على هامش الصورة."},{"i":"comp-02","s":28,"h":"4) الجدل حول الأدب العالمي","t":"learn","x":"النهاردة الصورة اتغيرت شوية، والأعمال من آسيا وأفريقيا وأمريكا اللاتينية بقت جزء من الحكاية."},{"i":"comp-02","s":29,"h":"4) الجدل حول الأدب العالمي","t":"learn","x":"وفيه سؤال قوة مش سهل: مين بيترجم؟ مين بينشر؟ مين بيقرأ؟ مش كل الآداب ليها نفس الفرصة في الوصول للعالمية."},{"i":"comp-02","s":30,"h":"4) الجدل حول الأدب العالمي","t":"mc","x":"إيه سؤال القوة اللي بيتوجه للأدب العالمي؟ ؟ مين بيترجم ومين بينشر ومين بيقرأ، ومين مش واصل / مين أسرع قارئ في العالم / كام صفحة في كل رواية / مين أغنى كاتب . الفرص مش متساوية، والسؤال عن الترجمة والنشر والقراءة."},{"i":"comp-02","s":31,"h":"4) الجدل حول الأدب العالمي","t":"learn","x":"دارسين كتير بيسألوا السؤال ده، زي Franco Moretti وPascale Casanova."},{"i":"comp-02","s":32,"h":"4) الجدل حول الأدب العالمي","t":"learn","x":"النتيجة: الأدب العالمي مش قايمة محايدة، ده سوق فيه قوة واختيار."},{"i":"comp-02","s":34,"h":"5) الفرق بين الأدب العالمي والأدب المقارن","t":"learn","x":"خد بالك من الفرق: الأدب العالمي: موضوع أو ظاهرة. نصوص بتدور بين الثقافات. الأدب المقارن: منهج. طريقة تدرس بيها العلاقات بين النصوص والثقافات."},{"i":"comp-02","s":35,"h":"5) الفرق بين الأدب العالمي والأدب المقارن","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ الأدب العالمي منهج، والأدب المقارن ظاهرة. / لازم يعدي حدوده اللغوية والثقافية ويوصل لقراء برة. / بالعكس: الأسطورة بتقول إنها طبيعة ثابتة، وبوفوار طالبت بإلغائها. / المقارن الكبير بيدخل مجالات برة الأدب زي الفلسفة والفنون. . بالعكس: الأدب العالمي ظاهرة، والأدب المقارن منهج."},{"i":"comp-02","s":36,"h":"5) الفرق بين الأدب العالمي والأدب المقارن","t":"learn","x":"مثال: تقرا نجيب محفوظ مترجم في أمريكا = بتشارك في الأدب العالمي. تدرس إزاي الترجمة غيرت النص = بتعمل أدب مقارن."},{"i":"comp-02","s":37,"h":"5) الفرق بين الأدب العالمي والأدب المقارن","t":"recall","x":"اذكر سببين لدراسة الأدب المقارن. . إنه بيدي حرية تكوين برنامج حسب اهتمامك، وإنه بيخليك تفهم ثقافتك أحسن لما تشوفها من برة، وكمان بيديك أدوات وأسئلة محتاجة دليل بدل الأحكام السريعة."},{"i":"comp-02","s":38,"h":"5) الفرق بين الأدب العالمي والأدب المقارن","t":"recall","x":"إيه شرطي Damrosch عشان العمل يدخل الأدب العالمي؟ . إنه يتقرأ كأدب، وإنه يعدي حدوده اللغوية والثقافية ويوصل لقراء في مكان تاني."},{"i":"comp-02","s":39,"h":"5) الفرق بين الأدب العالمي والأدب المقارن","t":"write","x":"قارن بين فهم «الأدب العالمي» كمجموع الآداب القومية، وفهمه كأدب بيدور خارج ثقافته: إيه اللي كل فهم بيضيفه، وأيهما أنفع للبحث؟ (5 ل 7 جمل) . الفهم الأول بيجمع كل حاجة، فبيبقى واسع جدا لكنه مش بيفرق بين عمل مشهور في بلده وعمل بيقراه العالم. الفهم التاني بيركز على الحركة: الترجمة والانتشار والقراءة في ثقافة تانية، فبيخلي البحث ممكن، لأنه بيحدد موضوع. الفهم التاني أنفع للبحث، لأنه بيسأل أسئلة قابلة للفحص: مين ترجم؟ إزاي اتقرأ؟ إيه اللي اتغير؟"},{"i":"comp-02","s":40,"h":"5) الفرق بين الأدب العالمي والأدب المقارن","t":"write","x":"قارن بين جوته وهو بيتكلم عن الأدب العالمي في 1827، وناقد بيتكلم عن قوة الترجمة والنشر النهاردة: إيه اللي اتغير في السؤال؟ (5 ل 7 جمل) . جوته كان بيحلم بشبكة تبادل بين الأمم، والتركيز كان على الثقافة والقراءة. النهاردة السؤال بقى عن القوة: مين عنده فرصة يترجم وينشر ويوصل، ومين لأ. يعني الحلم فضل نفسه، لكن السؤال زاد عليه بعد العدالة والفرص، وده اللي بيخلي النقد الحديث للأدب العالمي مختلف."},{"i":"comp-03","s":1,"h":"مقدمة","t":"learn","x":"في الدرس اللي فات عرفنا ليه بندرس المجال، وإيه حكاية الأدب العالمي. النهاردة هنشوف إن الأدب المقارن مش نوع واحد من الشغل، فيه نوعين: صغير وكبير."},{"i":"comp-03","s":3,"h":"1) المقارن الصغير","t":"learn","x":"المقارن الصغير ( micro ) بيفضل جوه الأدب. بيقارن نص أدبي بنص أدبي، أو أدب محلي بأدب محلي."},{"i":"comp-03","s":4,"h":"1) المقارن الصغير","t":"mc","x":"المقارن الصغير (micro) بيفضل جوه إيه؟ ؟ جوه الأدب: نص بنص، أو أدب محلي بأدب محلي / جوه الفلسفة بس / جوه التاريخ بس / جوه علم النفس بس . الصغير بيقارن نص أدبي بنص أدبي، أو أدب محلي بأدب محلي."},{"i":"comp-03","s":5,"h":"1) المقارن الصغير","t":"learn","x":"مثال: قصيدتين عربيتين من عصرين مختلفين. مثال: روايتين من بلدين، بيتكلموا عن نفس الموضوع."},{"i":"comp-03","s":6,"h":"1) المقارن الصغير","t":"learn","x":"مثال تاني: قصيدة عربية وقصيدة إنجليزية عن نفس الموضوع. لسه صغير، لأنك بتقارن نص بنص، حتى لو اللغة مختلفة."},{"i":"comp-03","s":7,"h":"1) المقارن الصغير","t":"learn","x":"ميزته: دقيق ومضبوط، وبيخليك تقدر تثبت كلامك بالنص. عيبه: ممكن يبقى ضيق، ويفضل يدور حوالين التفاصيل من غير ما يشوف الصورة الكبيرة."},{"i":"comp-03","s":9,"h":"2) المقارن الكبير","t":"learn","x":"المقارن الكبير ( macro ) بيخرج برة الأدب. بيدخل مجالات تانية: الفلسفة، والتاريخ، والفنون، والعلوم، والدين."},{"i":"comp-03","s":10,"h":"2) المقارن الكبير","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ «الأنوثة الأبدية» فكرة بتؤكد إن الأنوثة تكوين اجتماعي. / أنهي جملة من دول غلط؟ / لو بتدرس تطور الشعر الإنجليزي لوحده، ده أدب مقارن. / المقارن الكبير بيدخل مجالات برة الأدب زي الفلسفة والفنون. . الكبير بيدخل مجالات تانية، وده تعريفه."},{"i":"comp-03","s":11,"h":"2) المقارن الكبير","t":"learn","x":"مثال: رواية وفلسفة الوجودية. مثال: قصيدة ولوحة من نفس الفترة. مثال: أدب وعلم نفس."},{"i":"comp-03","s":12,"h":"2) المقارن الكبير","t":"learn","x":"المقارن الكبير مش لازم يبقى فلسفة. ممكن أدب وتاريخ، أو أدب وقانون، أو أدب وطب. المهم إن المجال التاني بيسأل سؤال يفتح النص، مش إنه يزوده."},{"i":"comp-03","s":13,"h":"2) المقارن الكبير","t":"learn","x":"ميزته: أسئلة أوسع، وبيوصلك لمعنى النص في سياقه. عيبه: ممكن يبقى كلام عام لو مش متضبط بالدليل."},{"i":"comp-03","s":14,"h":"2) المقارن الكبير","t":"mc","x":"إيه عيب المقارن الكبير؟ ؟ إنه ممكن يبقى كلام عام لو مش متضبط بالدليل / إنه بيمنعك تقرا النص / إنه بيخليك تقارن نصين بس / إنه بيلغي الفلسفة . الخطر إنه يبقى كلام عام من غير دليل."},{"i":"comp-03","s":16,"h":"3) العلاقة بتاريخ الأدب والنقد","t":"learn","x":"خد بالك من الفرق بين تلات حاجات قريبة من بعض. تاريخ الأدب بيدرس تطور أدب واحد عبر الزمن."},{"i":"comp-03","s":17,"h":"3) العلاقة بتاريخ الأدب والنقد","t":"learn","x":"الأدب المقارن بيدرس العلاقات بين الآداب. مش كل تاريخ أدب مقارن: لو بتدرس تطور الشعر الإنجليزي لوحده، ده تاريخ أدب، مش مقارنة."},{"i":"comp-03","s":18,"h":"3) العلاقة بتاريخ الأدب والنقد","t":"mc","x":"إيه الفرق بين تاريخ الأدب والأدب المقارن؟ ؟ تاريخ الأدب بيدرس تطور أدب واحد، والمقارن بيدرس العلاقات بين الآداب / تاريخ الأدب أسهل من المقارن / المقارن بيدرس أدب واحد بس / مفيش فرق . تاريخ الأدب لتطور أدب واحد، والمقارن للعلاقات بين الآداب."},{"i":"comp-03","s":19,"h":"3) العلاقة بتاريخ الأدب والنقد","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ أنهي جملة من دول صحيحة؟ / «الأنوثة الأبدية» عند بوفوار هي فكرة إن فيه طبيعة أنثوية ثابتة بتتبرر بيها أدوار محددة. / لو بتدرس تطور الشعر الإنجليزي لوحده، ده أدب مقارن. / «الناقل» في المدرسة الفرنسية هو الوسيط اللي بينقل النص، زي الترجمة أو المجلة. . ده تاريخ أدب، لأنك بتدرس أدب واحد."},{"i":"comp-03","s":20,"h":"3) العلاقة بتاريخ الأدب والنقد","t":"learn","x":"النقد بيفسر نص ويحكم عليه. الأدب المقارن بيقارن علاقات. والاتنين بيكملوا بعض: المقارنة من غير تفسير بتبقى وصف، والتفسير من غير مقارنة بيبقى رأي في نص واحد."},{"i":"comp-03","s":21,"h":"3) العلاقة بتاريخ الأدب والنقد","t":"learn","x":"مثال يوضح الفرق: دراسة رواية واحدة وتحليل شخصياتها = نقد. دراسة نفس الرواية وترجمتها، أو ردود فعل قراء ثقافة تانية عليها = أدب مقارن."},{"i":"comp-03","s":23,"h":"4) إزاي تختار النوع","t":"learn","x":"السؤال هو اللي بيحدد النوع، مش مزاجك. لو سؤالك عن نصين وعلاقتهم ببعض: ابدأ صغير."},{"i":"comp-03","s":24,"h":"4) إزاي تختار النوع","t":"learn","x":"لو سؤالك عن نص وسياق فكري أو فني واسع: وسع للكبير، بس حافظ على الدليل."},{"i":"comp-03","s":25,"h":"4) إزاي تختار النوع","t":"learn","x":"قاعدة عملية: ابدأ صغير ووسع. مثال: تقارن قصيدتين عن الحنين، وتلاقي اختلاف في الصور. بعدها تسأل: إزاي فكرة الحنين نفسها اتغيرت في الرومانتيكية؟ هنا بقيت كبير."},{"i":"comp-03","s":26,"h":"4) إزاي تختار النوع","t":"mc","x":"إيه القاعدة العملية اللي بنصح بيها؟ ؟ ابدأ صغير ووسع / ابدأ كبير وصغر / اختار النوع حسب طول النص / استخدم النوعين في نفس الوقت دايما . ابدأ صغير ووسع، عشان تحافظ على الدليل."},{"i":"comp-03","s":28,"h":"5) خلاصة","t":"learn","x":"إزاي تعرف إنك محتاج كبير؟ لو سؤالك عن معنى النص في سياقه الثقافي، أو عن علاقته بفكرة أو فن تاني، فإنت محتاج توسع. ولو سؤالك عن نصين وعلاقتهم ببعض، ابدأ صغير."},{"i":"comp-03","s":29,"h":"5) خلاصة","t":"learn","x":"النوعين مش متعارضين، دول درجتين في نفس السلم. الخطر الحقيقي: إن الصغير يبقى وصف من غير سؤال، والكبير يبقى كلام عام من غير دليل."},{"i":"comp-03","s":30,"h":"5) خلاصة","t":"recall","x":"إيه الفرق بين المقارن الصغير والمقارن الكبير؟ . الصغير بيقارن نص أدبي بنص أدبي أو أدب محلي بأدب محلي، وده دقيق لكن ممكن يبقى ضيق. الكبير بيدخل مجالات برة الأدب زي الفلسفة والفنون، وأسئلته أوسع لكن ممكن يبقى كلام عام لو مش متضبط بالدليل."},{"i":"comp-03","s":31,"h":"5) خلاصة","t":"recall","x":"امتى دراسة أدب واحد تبقى تاريخ أدب مش أدب مقارن؟ . لما تدرس تطور أدب واحد عبر الزمن من غير سؤال عن العلاقة بينه وبين أدب تاني أو مجال تاني."},{"i":"comp-03","s":32,"h":"5) خلاصة","t":"write","x":"قارن بين دراسة قصيدتين عن الحنين في عصرين مختلفين، ودراسة الحنين في القصيدة والرومانتيكية كحركة فكرية: إيه اللي بيكسبه الباحث في كل حالة، وإيه اللي بيخسره؟ (5 ل 7 جمل) . في الحالة الأولى الباحث بيكسب دقة: يقدر يثبت الاختلاف في الصور واللغة من النص نفسه، لكنه ممكن يخسر الصورة الكبيرة، ويفضل يدور حوالين التفاصيل. في الحالة التانية بيكسب سياق أوسع: إزاي فكرة الحنين نفسها اتغيرت مع الرومانتيكية، لكنه بيخسر الدقة لو مبنيش الكلام على دليل من النصوص. أنفع حل: يبدأ صغير بالنصين، وبعدها يوسع للسياق، ويرجع للنص تاني عشان يتأكد إن الكلام الكبير ليه سند."},{"i":"comp-03","s":33,"h":"5) خلاصة","t":"write","x":"قارن بين تاريخ الأدب والنقد من ناحية، والأدب المقارن من ناحية تانية: إيه السؤال اللي بيسأله كل واحد؟ (5 ل 7 جمل) . تاريخ الأدب بيسأل: إزاي أدب واحد اتطور عبر الزمن، وإيه مراحله. النقد بيسأل: إيه معنى النص ده، وإزاي نقيمه. الأدب المقارن بيسأل: إيه العلاقة بين أدبين أو أكتر، أو بين الأدب ومجال تاني. التلاتة مش بدائل لبعض: المقارنة بتحتاج تاريخ وتفسير عشان تبقى ليها معنى، والتاريخ والتفسير بيكسبوا من المقارنة سياق أوسع."},{"i":"comp-04","s":1,"h":"مقدمة","t":"learn","x":"المصطلحات في المجال ده أدوات، مش كلام للزينة. كل مصطلح هنشرحه بكلام بسيط، وبعدها بمثال من الأدب."},{"i":"comp-04","s":2,"h":"مقدمة","t":"learn","x":"هنقسمهم تلات مجموعات: مصطلحات العلاقة بين النصوص، ومصطلحات الموضوع والشكل، ومصطلحات المجال نفسه."},{"i":"comp-04","s":4,"h":"1) العلاقة بين النصوص","t":"learn","x":"Influence يعني التأثير. عمل أو كاتب بيأثر في عمل أو كاتب تاني، وبيغير فيه حاجة."},{"i":"comp-04","s":5,"h":"1) العلاقة بين النصوص","t":"learn","x":"التأثير مش مجرد تشابه. لازم دليل إن النص التاني وصل للأول: ترجمة، أو قراءة، أو وسيط نقله."},{"i":"comp-04","s":6,"h":"1) العلاقة بين النصوص","t":"learn","x":"Reception يعني الاستقبال. إزاي قراء ثقافة معينة استقبلوا النص، وقيموه، وفهموه."},{"i":"comp-04","s":7,"h":"1) العلاقة بين النصوص","t":"mc","x":"إيه معنى «الاستقبال» (reception)؟ ؟ إزاي قراء ثقافة معينة قرأوا النص وقيموه وفهموه / إزاي الكاتب كتب النص / عدد صفحات النص / ترجمة النص حرفيا . الاستقبال هو قراءة ثقافة معينة للنص وتقييمها له."},{"i":"comp-04","s":8,"h":"1) العلاقة بين النصوص","t":"learn","x":"مثال: رواية اتقرأت في مصر بطريقة، وفي فرنسا بطريقة تانية، وكل قراءة قالت حاجة عن ثقافتها هي."},{"i":"comp-04","s":9,"h":"1) العلاقة بين النصوص","t":"learn","x":"Source يعني المصدر. النص أو الحكاية اللي الكاتب أخد منها مادته."},{"i":"comp-04","s":10,"h":"1) العلاقة بين النصوص","t":"learn","x":"مثال: شاعر أخد حكاية من أسطورة قديمة، وحولها لقصيدة جديدة."},{"i":"comp-04","s":11,"h":"1) العلاقة بين النصوص","t":"learn","x":"Mediator يعني الوسيط. اللي نقل النص من ثقافة لثقافة: مترجم، أو مجلة، أو رحالة، أو مدرس."},{"i":"comp-04","s":12,"h":"1) العلاقة بين النصوص","t":"mc","x":"إيه الوسيط (mediator)؟ ؟ اللي نقل النص من ثقافة لثقافة: مترجم أو مجلة أو رحالة / القارئ اللي بيقرا النص / الناقد اللي بيهاجم النص / الكاتب اللي كتب النص . الوسيط هو اللي نقل النص بين الثقافات."},{"i":"comp-04","s":13,"h":"1) العلاقة بين النصوص","t":"learn","x":"Intertextuality يعني التناص. العلاقة بين النصوص: اقتباس، أو إشارة، أو محاكاة، أو رد على نص تاني."},{"i":"comp-04","s":14,"h":"1) العلاقة بين النصوص","t":"learn","x":"الفرق المهم: التأثير محتاج دليل تاريخي إن النص وصل. التناص بيسأل عن العلاقة اللي باينة في النص نفسه، حتى لو مفيش دليل إن الكاتب قرا التاني."},{"i":"comp-04","s":15,"h":"1) العلاقة بين النصوص","t":"mc","x":"إيه الفرق بين التأثير والتناص؟ ؟ التأثير محتاج دليل تاريخي إن النص وصل، والتناص بيسأل عن العلاقة اللي باينة في النص / التأثير أسهل من التناص / التناص لازم دليل تاريخي، والتأثير لأ / مفيش فرق بينهم . التأثير محتاج دليل وصول، والتناص بيسأل عن العلاقة داخل النص."},{"i":"comp-04","s":16,"h":"1) العلاقة بين النصوص","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ التشابه بين نصين لوحده يثبت إن فيه تأثير. / البنيوية ساعدت على دراسة التناص لأنها أدت أدوات لتحديد أنماط مشتركة بين التقاليد الأدبية. / الكانون بيتغير مع الوقت، وفيه نقاش على اللي بيستبعده. / «الأنوثة الأبدية» عند بوفوار هي فكرة إن فيه طبيعة أنثوية ثابتة بتتبرر بيها أدوار محددة. . التأثير محتاج دليل إن النص التاني وصل للأول."},{"i":"comp-04","s":18,"h":"2) الموضوع والشكل","t":"learn","x":"Theme يعني الموضوع. الفكرة العامة اللي النص بيتكلم عنها: الحنين، الموت، الحب، العدل."},{"i":"comp-04","s":19,"h":"2) الموضوع والشكل","t":"learn","x":"Motif يعني الموتيف. عنصر بيتكرر في النص أو في أعمال كاتب: صورة، أو كلمة، أو مكان."},{"i":"comp-04","s":20,"h":"2) الموضوع والشكل","t":"learn","x":"مثال: البحر في قصيدة بيتكرر أربع مرات، وكل مرة بمعنى مختلف. ده موتيف، مش موضوع."},{"i":"comp-04","s":21,"h":"2) الموضوع والشكل","t":"learn","x":"Myth يعني الأسطورة. حكاية قديمة عن آلهة أو أبطال، وبتتكرر في الأدب بأشكال جديدة."},{"i":"comp-04","s":22,"h":"2) الموضوع والشكل","t":"learn","x":"مثال: أسطورة أوديب في مسرحية حديثة، أو أسطورة سيزيف في مقال فلسفي."},{"i":"comp-04","s":23,"h":"2) الموضوع والشكل","t":"mc","x":"إيه الفرق بين الموضوع (theme) والموتيف (motif)؟ ؟ الموضوع فكرة عامة، والموتيف عنصر بيتكرر / الموتيف فكرة عامة، والموضوع عنصر بيتكرر / الاتنين نفس الحاجة / الموضوع للشعر بس، والموتيف للرواية بس . الموضوع فكرة عامة، والموتيف عنصر متكرر."},{"i":"comp-04","s":24,"h":"2) الموضوع والشكل","t":"learn","x":"Genre يعني النوع الأدبي. تصنيف النصوص: شعر، رواية، مسرح، قصة قصيرة، مقال."},{"i":"comp-04","s":26,"h":"3) مصطلحات المجال","t":"learn","x":"Canon يعني الكانون. الأعمال اللي المجتمع الأدبي بيعتبرها أساسية، واللي بيتدرس ويتراجع أكتر."},{"i":"comp-04","s":27,"h":"3) مصطلحات المجال","t":"learn","x":"الكانون مش قايمة مقدسة: بيتغير مع الوقت، وفيه نقاش إنه كان بيستبعد كتاب ونساء وثقافات كتير."},{"i":"comp-04","s":28,"h":"3) مصطلحات المجال","t":"learn","x":"Periodisation يعني التقسيم الزمني. تقسيم تاريخ الأدب لفترات: النهضة، الرومانتيكية، الحداثة."},{"i":"comp-04","s":29,"h":"3) مصطلحات المجال","t":"learn","x":"التقسيم ده أداة للدراسة، مش حقيقة طبيعية: التواريخ بتختلف من بلد لبلد، وفيه كتاب بيكتبوا برة الفترة بتاعتهم."},{"i":"comp-04","s":30,"h":"3) مصطلحات المجال","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ الكانون قايمة ثابتة مقدسة ماتتغيرش. / «الناقل» في المدرسة الفرنسية هو الوسيط اللي بينقل النص، زي الترجمة أو المجلة. / التأثير محتاج دليل إن النص التاني وصل للأول. / «الأنوثة الأبدية» عند بوفوار هي فكرة إن فيه طبيعة أنثوية ثابتة بتتبرر بيها أدوار محددة. . الكانون بيتغير مع الوقت، وفيه نقاش على اللي بيستبعده."},{"i":"comp-04","s":32,"h":"4) إزاي تستخدمهم","t":"learn","x":"مثال تطبيقي بيجمع تلات مصطلحات. قصيدة عربية فيها إشارة لأسطورة يونانية: هنا عندك myth ، و intertextuality ، وسؤال عن reception : القارئ العربي فهم الأسطورة إزاي؟"},{"i":"comp-04","s":33,"h":"4) إزاي تستخدمهم","t":"learn","x":"نصيحة أخيرة: استخدم المصطلح بدقة، وماتخلطش بين التأثير والتناص. الخلط بينهم بيخلي البحث كله مبني على دليل ضعيف."},{"i":"comp-04","s":34,"h":"4) إزاي تستخدمهم","t":"recall","x":"عرف التأثير والتناص والفرق بينهم. . التأثير هو إن عمل أو كاتب يغير في عمل أو كاتب تاني، ومحتاج دليل إن النص وصل. التناص هو العلاقة بين النصوص، اقتباس أو إشارة أو محاكاة، وبيتشاف في النص نفسه من غير دليل تاريخي."},{"i":"comp-04","s":35,"h":"4) إزاي تستخدمهم","t":"recall","x":"اذكر تلات مصطلحات من مصطلحات الموضوع والشكل، ومعنى كل واحد. . الموضوع (theme) فكرة عامة زي الحنين أو الموت. الموتيف (motif) عنصر بيتكرر زي صورة أو كلمة. الأسطورة (myth) حكاية قديمة بتتكرر في الأدب. والنوع (genre) تصنيف النص: شعر أو رواية أو مسرح."},{"i":"comp-04","s":36,"h":"4) إزاي تستخدمهم","t":"write","x":"قارن بين دراسة نصين متشابهين باعتبار «التأثير»، ودراستهم باعتبار «التناص»: إيه اللي بيحتاجه الباحث في كل حالة، وإيه اللي بيتغير في النتيجة؟ (5 ل 7 جمل) . دراسة التأثير محتاجة دليل تاريخي إن النص التاني وصل للأول: ترجمة، أو قراءة موثقة، أو وسيط زي مجلة أو رحالة. دراسة التناص مش محتاجة الدليل ده، لأنها بتقرا العلاقة اللي باينة في النص: إشارة، اقتباس، محاكاة. النتيجة بتختلف: التأثير بيقولك إيه اللي اتنقل وإزاي، والتناص بيقولك النص الجديد بيعيد كتابة إيه وليه. والاتنين ممكن يتكملوا: التناص بيفتح السؤال، والتأثير بيديك الدليل التاريخي عليه."},{"i":"comp-04","s":37,"h":"4) إزاي تستخدمهم","t":"write","x":"قارن بين «الكانون» و«التقسيم الزمني» كأداتين للدراسة: إيه اللي كل واحدة بتعمله، وإيه خطر الاعتماد على واحدة منهم لوحدها؟ (5 ل 7 جمل) . الكانون بيرتب الأعمال اللي المجتمع الأدبي بيعتبرها أساسية، فبيديك خريطة للقراءة والدراسة. التقسيم الزمني بيرتب الأدب لفترات، فبيديك إطار تفهم بيه التطور. خطر الاعتماد على الكانون لوحده إنه بيستبعد كتاب ونساء وثقافات كتير، فبتاخد صورة ناقصة. وخطر التقسيم الزمني لوحده إنه بيقفل الكتاب اللي بيكتبوا برة فترة بلدهم. الاتنين أدوات، ومحتاجين مراجعة ووعي باللي بيستبعدوه."},{"i":"comp-05","s":1,"h":"مقدمة","t":"learn","x":"في الدروس اللي فاتت عرفنا يعني إيه أدب مقارن، وأنواعه، ومصطلحاته. النهاردة سؤال تاريخي: ليه المجال ده ظهر في القرن التسعتاشر، ومش قبل كده ولا بعده؟"},{"i":"comp-05","s":3,"h":"1) المقارنة قديمة، لكن العلم جديد","t":"learn","x":"المقارنة بين الآداب مش حاجة جديدة. من القرن التمنتاشر فيه كتاب بيقارنوا آداب الأمم، لكن مفيش مادة بتتدرس، ولا كراسي، ولا مجلات، ولا منهج متفق عليه."},{"i":"comp-05","s":4,"h":"1) المقارنة قديمة، لكن العلم جديد","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ المقارنة بين الآداب بدأت مع ظهور المادة الدراسية في القرن التسعتاشر. / المادة والكراسي ظهرت في آخر القرن، في السبعينات والتسعينات. / الأفكار قديمة، لكن الحركة المنظمة اتشكلت في آخر القرن التسعتاشر. / «الناقل» في المدرسة الفرنسية هو الوسيط اللي بينقل النص، زي الترجمة أو المجلة. . المقارنة موجودة قبل كده، اللي ظهر في القرن التسعتاشر هو المادة والمنهج."},{"i":"comp-05","s":5,"h":"1) المقارنة قديمة، لكن العلم جديد","t":"learn","x":"المصطلح نفسه ظهر في بداية القرن التسعتاشر. سنة 1816 نشر Noël وLaplace كتاب اسمه «Cours de littérature comparée»، وبعدهم Villemain استخدم المصطلح في محاضراته 1828 و1829، وAmpère كمل الطريق."},{"i":"comp-05","s":6,"h":"1) المقارنة قديمة، لكن العلم جديد","t":"mc","x":"إيه أول استخدام موثق لمصطلح «littérature comparée»؟ ؟ كتاب Cours de littérature comparée ل Noël وLaplace سنة 1816 / مقال Sainte-Beuve سنة 1868 / مجلة Meltzl سنة 1877 / مؤتمر Chapel Hill سنة 1958 . المصطلح موثق في 1816 مع Noël وLaplace."},{"i":"comp-05","s":7,"h":"1) المقارنة قديمة، لكن العلم جديد","t":"learn","x":"تصحيح لازم تعرفه، لأنه بيتكرر في كتب كتير. فيه مراجع بتقول إن Sainte-Beuve هو اللي صاغ المصطلح سنة 1868. ده مش دقيق: Sainte-Beuve استخدم تعبير «histoire littéraire comparée»، والمصطلح كان مستخدم قبله بعشرات السنين."},{"i":"comp-05","s":8,"h":"1) المقارنة قديمة، لكن العلم جديد","t":"learn","x":"وخد بالك من حاجة: كلمة «مقارن» كانت موضة في القرن التسعتاشر. الناس كانت بتقارن النحو، والجغرافيا، والتشريح، والأنظمة السياسية. فكان طبيعي حد يقول: وليه لأ الأدب كمان؟"},{"i":"comp-05","s":9,"h":"1) المقارنة قديمة، لكن العلم جديد","t":"learn","x":"وأول استخدام للمصطلح بالإنجليزي كان في رسالة، مش في كتاب. Matthew Arnold كتب «comparative literatures» في رسالة لاخته سنة 1848، والرسالة ما اتنشرتش غير سنة 1895."},{"i":"comp-05","s":10,"h":"1) المقارنة قديمة، لكن العلم جديد","t":"learn","x":"وليه أوروبا بالتحديد؟ لأن القارة متقسمة لغات وثقافات كتير، وفي نفس الوقت فيها أرضية مشتركة قديمة. القرب والاختلاف مع بعض بيخلقوا سؤال المقارنة."},{"i":"comp-05","s":12,"h":"2) ليه القرن التسعتاشر؟","t":"learn","x":"أول عامل: القومية. كل أمة في أوروبا بتبني أدبها القومي وهوية ثقافية، وساعتها بيبقى السؤال طبيعي: إيه علاقة أدبنا بأدب الجيران؟"},{"i":"comp-05","s":13,"h":"2) ليه القرن التسعتاشر؟","t":"learn","x":"تاني عامل: الاستعمار والاحتكاك بين الثقافات. التوسع الأوروبي جاب نصوص وثقافات جديدة، وترجمات، واهتمام بالشرق، فبقى فيه مادة للمقارنة مش موجودة قبل كده."},{"i":"comp-05","s":14,"h":"2) ليه القرن التسعتاشر؟","t":"learn","x":"تالت عامل: المنهج المقارن في العلوم. القرن التسعتاشر شاف علم تشريح مقارن، وفقه لغة مقارن، وعلوم بتقارن الأنواع والأنظمة."},{"i":"comp-05","s":15,"h":"2) ليه القرن التسعتاشر؟","t":"mc","x":"إيه العامل اللي مش من عوامل ظهور المجال في القرن التسعتاشر؟ ؟ اختراع الإنترنت ووسائل التواصل / صعود القومية في أوروبا / التوسع الاستعماري والاحتكاك بالثقافات / نجاح المنهج المقارن في العلوم . الإنترنت جه في القرن العشرين، ومش من عوامل ظهور المجال."},{"i":"comp-05","s":16,"h":"2) ليه القرن التسعتاشر؟","t":"learn","x":"الأدب أخد الفكرة: لو العلم بيقارن، ليه الأدب لأ؟"},{"i":"comp-05","s":17,"h":"2) ليه القرن التسعتاشر؟","t":"learn","x":"رابع عامل: الطباعة والترجمة. النصوص بقت بتتطبع وتترجم وتنتشر أسرع، فبقى فيه حركة نصوص حقيقية تستاهل الدراسة."},{"i":"comp-05","s":19,"h":"3) من الفكرة للمادة","t":"learn","x":"المجال بقى مادة دراسية في آخر القرن، مش في أوله. السبعينات والتسعينات شافوا كراسي ومجلات ومناهج. أول كرسي معروف كان في نابولي سنة 1871، وفي فرنسا اتأسس كرسي ليون سنة 1897 مع Joseph Texte."},{"i":"comp-05","s":20,"h":"3) من الفكرة للمادة","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ الأفكار قديمة، لكن الحركة المنظمة اتشكلت في آخر القرن التسعتاشر. / المقارنة موجودة قبل كده، اللي ظهر في القرن التسعتاشر هو المادة والمنهج. / قوة المدرسة الفرنسية إنها عملت المجال مهنة بمعايير وأرشيف ومجلة. / المجال بقى مادة جامعية كاملة في أول القرن التسعتاشر. . المادة والكراسي ظهرت في آخر القرن، في السبعينات والتسعينات."},{"i":"comp-05","s":21,"h":"3) من الفكرة للمادة","t":"learn","x":"والمجلات هي اللي ثبتت المجال. أول مجلة كانت Acta Comparationis Litterarum Universarum سنة 1877 مع Hugo von Meltzl، وبعدها Zeitschrift für vergleichende Litteraturgeschichte سنة 1887 مع Max Koch، وبعدها Revue de littérature comparée سنة 1921."},{"i":"comp-05","s":22,"h":"3) من الفكرة للمادة","t":"mc","x":"إيه أول مجلة في المجال؟ ؟ Acta Comparationis Litterarum Universarum سنة 1877 / Revue de littérature comparée سنة 1921 / مجلة أدبية ألمانية سنة 1930 / Zeitschrift für vergleichende Litteraturgeschichte سنة 1987 . أول مجلة كانت Acta Comparationis سنة 1877."},{"i":"comp-05","s":23,"h":"3) من الفكرة للمادة","t":"learn","x":"وكمان الفهرست: Louis Paul Betz نشر Bibliographie de littérature comparée سنة 1900، فبقى للمجال أرشيفه."},{"i":"comp-05","s":25,"h":"4) خلاصة","t":"learn","x":"النشأة مش لحظة واحدة، دي سلسلة: مصطلح في 1816، أفكار في وسط القرن، كراسي ومجلات في آخره، ومؤسسة دولية في 1954."},{"i":"comp-05","s":26,"h":"4) خلاصة","t":"mc","x":"ليه بنقول إن النشأة سلسلة مش لحظة؟ ؟ لأن المصطلح 1816، والأفكار وسط القرن، والكراسي والمجلات في آخره، والمؤسسة الدولية 1954 / لأن المجال ظهر كامل في يوم واحد / لأن المجال انتهى سنة 1900 / لأن كل الكتب اتفقت على تاريخ واحد . كل مرحلة زادت حاجة: مصطلح، أفكار، مؤسسات، ثم مؤسسة دولية."},{"i":"comp-05","s":27,"h":"4) خلاصة","t":"learn","x":"ولاحظ: المجال اتولد في أوروبا، وده هيفضل يبان في أسئلته وحدوده، وهنشوف ده في الدرس الجاي."},{"i":"comp-05","s":28,"h":"4) خلاصة","t":"recall","x":"اذكر تلات عوامل ساعدت على ظهور الأدب المقارن في القرن التسعتاشر. . صعود القومية وبناء الأدب القومي، والتوسع الاستعماري والاحتكاك بين الثقافات، ونجاح المنهج المقارن في العلوم، وكمان الطباعة والترجمة اللي زودت حركة النصوص."},{"i":"comp-05","s":29,"h":"4) خلاصة","t":"recall","x":"إيه التصحيح اللي لازم تعرفه عن Sainte-Beuve؟ . فيه مراجع بتقول إنه صاغ مصطلح «littérature comparée» سنة 1868، وده مش دقيق. هو استخدم «histoire littéraire comparée»، والمصطلح موثق قبله من 1816 مع Noël وLaplace."},{"i":"comp-05","s":30,"h":"4) خلاصة","t":"write","x":"قارن بين المقارنة بين الآداب في القرن التمنتاشر، وظهور الأدب المقارن كمادة في آخر القرن التسعتاشر: إيه اللي اتغير، وليه التغيير ده مهم؟ (5 ل 7 جمل) . في القرن التمنتاشر كانت المقارنة موجودة كفكرة وكتابة: كتاب بيقارنوا آداب الأمم من غير منهج متفق عليه ولا مؤسسة. في آخر القرن التسعتاشر اتغير حاجتين: اتعملت كراسي ومجلات، واتبنى منهج بيسأل أسئلة محددة وبيطلب دليل. التغيير مهم لأن المجال بقى مادة بتتدرس وبتتقيم، ومش مجرد رأي كاتب. وكمان التغيير ده هو اللي خلى النقد والمراجعة ممكنين، لأن بقى فيه معايير واضحة."},{"i":"comp-05","s":31,"h":"4) خلاصة","t":"write","x":"قارن بين تفسير ظهور المجال بسبب القومية، وتفسيره بسبب الاستعمار: إيه اللي كل تفسير بيوضحه، وإيه اللي بيسيبه برة الصورة؟ (5 ل 7 جمل) . تفسير القومية بيوضح ليه الأدب القومي بقى موضوع دراسة، وليه المقارنة بقت سؤال هوية: كل أمة عايزة تعرف موقعها. بس التفسير ده بيسيب برة الصورة النصوص اللي جت من خارج أوروبا، والترجمة، والاحتكاك اللي فرضته الحركة الاستعمارية. تفسير الاستعمار بيوضح المصدر التاني للمادة: نصوص وثقافات دخلت أوروبا، وترجمات واهتمام بالشرق. بس هو كمان ممكن يقلل من دور القومية في تنظيم الدراسة. أدق تفسير بيجمع الاتنين، لأن المجال محتاج مادة (الاستعمار) ودافع (القومية)."},{"i":"comp-06","s":1,"h":"مقدمة","t":"learn","x":"النهاردة هنقابل الناس اللي صنعوا المجال. مش راجل واحد ولا بلد واحد: الفكرة جت من ألمانيا، وأول كتاب من أيرلندا، وأول مجلة من ترانسيلفانيا، والكراسي من فرنسا وإيطاليا."},{"i":"comp-06","s":3,"h":"1) جوته: الفكرة قبل العلم","t":"learn","x":"جوته طرح الفكرة، لكنه ما بناش مادة. Weltliteratur عنده كانت رؤية: سوق عالمي للأدب، وقراءة متبادلة بين الأمم."},{"i":"comp-06","s":4,"h":"1) جوته: الفكرة قبل العلم","t":"mc","x":"إيه اللي أداه جوته للمجال؟ ؟ الفكرة: Weltliteratur وشبكة تبادل بين الأمم / أول كتاب منهج / أول مجلة / أول كرسي جامعي . جوته أدى الفكرة، مش المؤسسة."},{"i":"comp-06","s":5,"h":"1) جوته: الفكرة قبل العلم","t":"learn","x":"الفكرة دي مهمة لأنها غيرت السؤال: من «إيه اللي عندنا» ل«إيه اللي بيتنقل بيننا». لكن الفكرة لوحدها مش منهج، ومش مادة بتتدرس."},{"i":"comp-06","s":6,"h":"1) جوته: الفكرة قبل العلم","t":"learn","x":"وحاجة تستاهل وقفة: بوسنيت اشتغل بالتدريس في كالكوتا في الهند. يعني أول كتاب في المجال اتكتب من موقع إمبراطوري، مش من أوروبا بس. ودارسين كتير بيروا إن ده جزء من قصة المجال، مش حاشية."},{"i":"comp-06","s":8,"h":"2) رواد المنهج","t":"learn","x":"أول كتاب كامل في المجال كان من باحث أيرلندي: Hutcheson Macaulay Posnett . كتابه «Comparative Literature» صدر سنة 1886، وحاول يدي المجال أساس علمي، مستخدم أفكار التطور الاجتماعي اللي كانت سايدة وقتها."},{"i":"comp-06","s":9,"h":"2) رواد المنهج","t":"mc","x":"مين كتب أول كتاب كامل في المجال؟ ؟ Hutcheson Macaulay Posnett سنة 1886 / Goethe سنة 1827 / Van Tieghem سنة 1931 / Wellek سنة 1953 . بوسنيت كتب Comparative Literature سنة 1886."},{"i":"comp-06","s":10,"h":"2) رواد المنهج","t":"learn","x":"وأول مجلة كانت من ترانسيلفانيا، مع Hugo von Meltzl. Acta Comparationis Litterarum Universarum صدرت سنة 1877 في كلوج، وكانت بتتنشر بأكتر من لغة، وده كان جديد: منصة للمقارنة بين آداب لغات مختلفة."},{"i":"comp-06","s":11,"h":"2) رواد المنهج","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ قوة المدرسة الفرنسية إنها عملت المجال مهنة بمعايير وأرشيف ومجلة. / المساهمة كانت من ألمانيا وأيرلندا وترانسيلفانيا وروسيا وبريطانيا وإيطاليا وفرنسا. / أول مجلة في المجال كانت بتتنشر بلغة واحدة بس. / الناقل في النموذج ممكن يكون ترجمة أو مجلة أو رحالة. . مجلة Meltzl كانت بتتنشر بأكتر من لغة."},{"i":"comp-06","s":12,"h":"2) رواد المنهج","t":"mc","x":"إيه اللي ميز مجلة Meltzl؟ ؟ إنها كانت متعددة اللغات ومنصة لمقارنة آداب لغات مختلفة / إنها كانت بالإنجليزية بس / إنها كانت مجلة شعر بس / إنها اتأسست سنة 1954 . التعدد اللغوي هو اللي ميزها."},{"i":"comp-06","s":13,"h":"2) رواد المنهج","t":"learn","x":"بعدها بعشر سنين، Max Koch عمل مجلة ألمانية: Zeitschrift für vergleichende Litteraturgeschichte سنة 1887."},{"i":"comp-06","s":14,"h":"2) رواد المنهج","t":"learn","x":"وفي روسيا، Alexander Veselovsky اشتغل على الشعر المقارن. اهتم بالحكايات الشعبية والأساطير وانتقالها بين الشعوب، وربط المقارنة بالتاريخ."},{"i":"comp-06","s":15,"h":"2) رواد المنهج","t":"learn","x":"وفي بريطانيا، George Saintsbury وGilbert Murray ساهموا في النقد المقارن بين الآداب القومية."},{"i":"comp-06","s":16,"h":"2) رواد المنهج","t":"learn","x":"وفي إيطاليا، Vittorio Rossi وBenedetto Croce اشتغلوا على الأدب الرومانسي المقارن. Croce بعد كده هاجم الوضعية، وهنشوف ده في الدرس الجاي."},{"i":"comp-06","s":17,"h":"2) رواد المنهج","t":"learn","x":"وميلتزل كان ليه برنامج واضح: مقاومة الانغلاق القومي. كان شايف إن الأدب لازم يتقارن بأكتر من لغة، وشايف إن القومية الضيقة بتضيع الصورة. عشان كده مجلته كانت متعددة اللغات."},{"i":"comp-06","s":19,"h":"3) المؤسسة","t":"learn","x":"الرواد محتاجين مؤسسة عشان الفكرة تعيش. أول كرسي معروف كان في نابولي سنة 1871. وفي فرنسا، كرسي ليون اتأسس سنة 1897 مع Joseph Texte."},{"i":"comp-06","s":20,"h":"3) المؤسسة","t":"learn","x":"وبعدها كرسي السوربون سنة 1910 مع Fernand Baldensperger، اللي بقى أب المدرسة الفرنسية عمليا."},{"i":"comp-06","s":21,"h":"3) المؤسسة","t":"learn","x":"وسنة 1921، Baldensperger وPaul Hazard أسسوا Revue de littérature comparée، اللي لسه بتصدر."},{"i":"comp-06","s":22,"h":"3) المؤسسة","t":"mc","x":"مين اللي أسس Revue de littérature comparée سنة 1921؟ ؟ Baldensperger وPaul Hazard / Goethe وEckermann / Posnett وMeltzl / Wellek وRemak . بالدنسبرجر وهازار أسسوا المجلة سنة 1921."},{"i":"comp-06","s":23,"h":"3) المؤسسة","t":"learn","x":"وسنة 1954 اتأسست الجمعية الدولية للأدب المقارن (ICLA) في أكسفورد، وأول مؤتمر كبير ليها في فينيسيا 1955، وتاني مؤتمر في Chapel Hill سنة 1958."},{"i":"comp-06","s":25,"h":"4) خلاصة","t":"learn","x":"المجال مش صناعة فرنسية لوحدها: ألمانيا أدت الفكرة، وأيرلندا أول كتاب، وترانسيلفانيا أول مجلة، وفرنسا وإيطاليا الكراسي."},{"i":"comp-06","s":26,"h":"4) خلاصة","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ مجلة Meltzl كانت بتتنشر بأكتر من لغة. / قوة المدرسة الفرنسية إنها عملت المجال مهنة بمعايير وأرشيف ومجلة. / المجال اتأسس في فرنسا بس، وباقي الدول ما ساهمتش. / ليلى وافقت تتجوز رشيد بعد ما اتقالها إن طارق مات، وهي كانت حامل. . المساهمة كانت من ألمانيا وأيرلندا وترانسيلفانيا وروسيا وبريطانيا وإيطاليا وفرنسا."},{"i":"comp-06","s":27,"h":"4) خلاصة","t":"learn","x":"وكل واحد أدى حاجة مختلفة: جوته الفكرة، بوسنيت المحاولة العلمية، ميلتزل المنصة، تيكست وبالدنسبرجر المؤسسة."},{"i":"comp-06","s":28,"h":"4) خلاصة","t":"recall","x":"اذكر تلات رواد، وحاجة واحدة أداها كل واحد للمجال. . جوته أدى فكرة Weltliteratur، وبوسنيت كتب أول كتاب منهج سنة 1886، وميلتزل عمل أول مجلة سنة 1877، وتيكست وبالدنسبرجر بنوا الكراسي والمؤسسة في فرنسا."},{"i":"comp-06","s":29,"h":"4) خلاصة","t":"recall","x":"إيه الفرق بين الفكرة والمؤسسة في تاريخ المجال؟ . الفكرة هي السؤال والرؤية، زي Weltliteratur عند جوته. المؤسسة هي الكراسي والمجلات والجمعيات اللي بتخلي الفكرة مادة بتتدرس وتتعلم، زي كرسي ليون 1897 ومجلة 1921 وجمعية ICLA 1954."},{"i":"comp-06","s":30,"h":"4) خلاصة","t":"write","x":"قارن بين مساهمة جوته ومساهمة بوسنيت في تأسيس المجال: إيه اللي كل واحد أداه، وليه الاتنين محتاجين لبعض؟ (5 ل 7 جمل) . جوته أدى الفكرة: إن الأدب بقى سوق تبادل بين الأمم، والسؤال بقى عن اللي بيتنقل. بوسنيت أدى المحاولة العلمية: كتاب كامل بيحاول يدي المجال أساس ومنهج. الاتنين محتاجين لبعض لأن الفكرة من غير منهج بتفضل رؤية شخصية، والمنهج من غير فكرة بيبقى تجميع معلومات. تاريخ المجال بيوضح إن الاتنين مكملين: الأول فتح السؤال، والتاني حاول يجاوب عليه بطريقة منظمة."},{"i":"comp-06","s":31,"h":"4) خلاصة","t":"write","x":"قارن بين المجلة والكرسي الجامعي كأداتين لبناء مجال علمي: إيه اللي كل واحدة بتعمله، وليه المجال محتاج الاتنين؟ (5 ل 7 جمل) . المجلة بتخلي البحث يتنشر ويتناقش، فبتبني حوار بين باحثين من بلاد مختلفة، زي مجلة Meltzl متعددة اللغات. الكرسي بيدي للمجال مكان في المؤسسات العلمية، وطالب بيتعلم، ووظيفة بتجذب باحثين، زي كرسي ليون 1897. المجال محتاج الاتنين: من غير مجلة البحث بيفضل معزول، ومن غير كرسي المجال بيفضل هواية مش مهنة. الاتنين مع بعض بيعملوا اللي بنسميه تخصص."},{"i":"comp-07","s":1,"h":"مقدمة","t":"learn","x":"في الدرس اللي فات قابلنا الرواد. النهاردة أول نظرية كاملة للمجال: المدرسة الفرنسية. عشان تفهمها، لازم تفهم الفلسفة اللي بنيت عليها: الوضعية."},{"i":"comp-07","s":3,"h":"1) الوضعية","t":"learn","x":"الوضعية ( positivism ) بدأت مع الفيلسوف الفرنسي Auguste Comte . الفكرة: المعرفة الحقيقية بتيجي من الحقائق والظواهر وعلاقاتها الخارجية، مش من البحث عن «جوهر» مخفي ورا الظواهر."},{"i":"comp-07","s":4,"h":"1) الوضعية","t":"mc","x":"المدرسة الفرنسية بنيت على فلسفة إيه؟ ؟ الوضعية عند Auguste Comte / الوجودية / البنيوية / التحليل النفسي . المدرسة الفرنسية بنيت على الوضعية."},{"i":"comp-07","s":5,"h":"1) الوضعية","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ قوة المدرسة الفرنسية إنها عملت المجال مهنة بمعايير وأرشيف ومجلة. / العنف في الرواية بيأثر على إحساس الشخصية بنفسها، مش على جسدها بس. / الوضعية بتدور على «جوهر» مخفي ورا الظواهر. / البنيوية ساعدت على دراسة التناص لأنها أدت أدوات لتحديد أنماط مشتركة بين التقاليد الأدبية. . الوضعية بترفض البحث عن الجوهر، وبتشتغل على الحقائق وعلاقاتها."},{"i":"comp-07","s":6,"h":"1) الوضعية","t":"learn","x":"وعشان كده الوضعية بتحب المقارنة. بتقارن مجتمعات وثقافات عشان تفهم قواعد التطور. والمقارنة دي بقت أداة أساسية."},{"i":"comp-07","s":7,"h":"1) الوضعية","t":"learn","x":"ومع الوضعية جه العلمية (scientism). الفكرة إن الأدب يتدرس بطرق العلوم الطبيعية: ملاحظة، تصنيف، دليل، قانون."},{"i":"comp-07","s":8,"h":"1) الوضعية","t":"learn","x":"وليه الفكرة دي كانت جاذبة؟ لأنها وعدت بموضوعية: بحث مبني على وثائق ودليل، مش ذوق شخصي."},{"i":"comp-07","s":10,"h":"2) خصائص المدرسة الفرنسية","t":"learn","x":"من الوضعية طلعت خمس خصائص للمدرسة الفرنسية. 1) تركيز على البيانات التجريبية والسياق التاريخي. 2) تفسير سببي: إيه اللي سبب إيه."},{"i":"comp-07","s":11,"h":"2) خصائص المدرسة الفرنسية","t":"learn","x":"وتكملة الخصائص: 3) دراسة التأثير: إزاي أدب أثر في أدب تاني. 4) منهج موضوعي «علمي»: وثائق، أرشيف، فهارس. 5) التأكيد على عالمية الأدب: الأدب بيتخطى الحدود القومية."},{"i":"comp-07","s":12,"h":"2) خصائص المدرسة الفرنسية","t":"mc","x":"إيه الخصيصة اللي مش من خصائص المدرسة الفرنسية؟ ؟ إنها بتدرس النص كفن مستقل عن أي سياق / تركيز على البيانات والسياق التاريخي / تفسير سببي للعلاقات / دراسة التأثير بين الآداب . المدرسة الفرنسية غيرت السياق، وميلت لأسلوب علمي، مش لدراسة النص كفن مستقل."},{"i":"comp-07","s":13,"h":"2) خصائص المدرسة الفرنسية","t":"learn","x":"النتيجة إن المدرسة الفرنسية بقت مدرسة «علاقات دولية» للأدب: مين قرا مين، وإيه اللي اتنقل، وإمتى."},{"i":"comp-07","s":15,"h":"3) الأسماء والمؤسسات","t":"learn","x":"أهم أسماء المدرسة: Fernand Baldensperger، وPaul Hazard، وPaul van Tieghem، وJean-Marie Carré، وMarius-François Guyard. بالدنسبرجر خد كرسي السوربون سنة 1910، وهازار شاركه في تأسيس المجلة."},{"i":"comp-07","s":16,"h":"3) الأسماء والمؤسسات","t":"learn","x":"وفان تيجيم عمل حاجة مهمة سنة 1931: كتاب «La littérature comparée». قسم المجال لتلاتة: الأدب القومي، والأدب المقارن، والأدب العام. التقسيم ده أدى للمجال حدوده."},{"i":"comp-07","s":17,"h":"3) الأسماء والمؤسسات","t":"mc","x":"إيه اللي عمله فان تيجيم سنة 1931؟ ؟ قسم المجال لتلاتة: أدب قومي، وأدب مقارن، وأدب عام / أسس مجلة Revue de littérature comparée / كتب أول كتاب في المجال سنة 1886 / هاجم المدرسة الفرنسية . فان تيجيم قسم المجال لتلاتة في كتابه 1931."},{"i":"comp-07","s":18,"h":"3) الأسماء والمؤسسات","t":"learn","x":"والمجلة، Revue de littérature comparée سنة 1921، كانت منصة المدرسة: فيها نشر النظريات والدراسات."},{"i":"comp-07","s":20,"h":"4) قوة وضعف","t":"learn","x":"القوة الحقيقية: المدرسة دي عملت المجال مهنة. أرشيف، وفهارس، ومعايير، ومجلة، وكراسي. من غيرها كان المجال هيفضل هواية."},{"i":"comp-07","s":21,"h":"4) قوة وضعف","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ أنهي جملة من دول غلط؟ / قوة المدرسة الفرنسية إنها عملت المجال مهنة بمعايير وأرشيف ومجلة. / «الأنوثة الأبدية» فكرة بتؤكد إن الأنوثة تكوين اجتماعي. / أنهي جملة من دول غلط؟ . الأرشيف والفهارس والمعايير خلت المجال مهنة."},{"i":"comp-07","s":22,"h":"4) قوة وضعف","t":"learn","x":"والضعف بيبدأ من نفس المصدر: الوضعية. لو كل حاجة لازم تتفسر بسبب، البحث بيضيق، وبيبقى حصر «مين أخد من مين»، وده بيسيب النص نفسه برة الصورة."},{"i":"comp-07","s":23,"h":"4) قوة وضعف","t":"mc","x":"إيه أضعف نقطة في المدرسة الفرنسية؟ ؟ إنها بتحول البحث لحصر تأثيرات وتسيب النص نفسه برة الصورة / إنها بتهمل الوثائق / إنها بترفض المقارنة / إنها مش بتدي أهمية للمؤسسات . الخطر إن البحث يبقى حصر تأثيرات، والنص يغيب."},{"i":"comp-07","s":24,"h":"4) قوة وضعف","t":"learn","x":"وفيه ضعف تاني: المركزية الأوروبية. المجال اتبنى وأوروبا في مركز الصورة، والباقي بيدخل على الهامش."},{"i":"comp-07","s":26,"h":"5) طريقة العمل والنقد المبكر","t":"learn","x":"الوضعية ما أثرتش على النقد بس، أثرت على الأدب نفسه. الطبيعانية (Naturalism) في آخر القرن التسعتاشر كانت بتعامل الإنسان كظاهرة تتدرس، وده نفس روح الوضعية."},{"i":"comp-07","s":27,"h":"5) طريقة العمل والنقد المبكر","t":"learn","x":"والمدرسة الفرنسية بقت ليها طريقة عمل واضحة. تختار كاتبين، وتدور على وثائق: رسائل، مقدمات، مكتبات، ترجمات. بعدها تثبت الاتصال، وتصنف نوع التأثير ودرجته ومدته."},{"i":"comp-07","s":28,"h":"5) طريقة العمل والنقد المبكر","t":"learn","x":"وفيه نقد مبكر جاي من برة الوضعية. Croce والحدس الجمالي، وBergson، واتجاهات زى الرمزية، كلهم رفضوا الفكرة إن الأدب يتفسر بقوانين علمية. وده اللي فتح الباب للمدرسة الأمريكية بعد كده."},{"i":"comp-07","s":30,"h":"6) خلاصة","t":"learn","x":"المدرسة الفرنسية: وضعية + تأثير + وثائق + مؤسسة. قوية في الدليل، وضعيفة لما تنسى إن النص فن، مش وثيقة."},{"i":"comp-07","s":31,"h":"6) خلاصة","t":"recall","x":"اشرح الوضعية في سطرين، وإزاي أثرت في المدرسة الفرنسية. . الوضعية فلسفة بتقول إن المعرفة بتيجي من الحقائق والظواهر وعلاقاتها، مش من البحث عن جوهر مخفي. أثرت في المدرسة الفرنسية فخليتها تركز على البيانات والسياق والتفسير السببي ودراسة التأثير، بدل دراسة النص كفن."},{"i":"comp-07","s":32,"h":"6) خلاصة","t":"recall","x":"اذكر تلات أسماء من المدرسة الفرنسية، وحاجة واحدة عملها كل واحد. . بالدنسبرجر خد كرسي السوربون 1910، وهازار شارك في تأسيس Revue de littérature comparée 1921، وفان تيجيم كتب La littérature comparée 1931 وقسم المجال لتلاتة."},{"i":"comp-07","s":33,"h":"6) خلاصة","t":"write","x":"قارن بين قوة المدرسة الفرنسية وضعفها: إيه اللي كسبه المجال منها، وإيه اللي خسره؟ (5 ل 7 جمل) . المدرسة الفرنسية كسبت للمجال مهنيته: كراسي ومجلات وفهارس ومعايير، وبقت الدراسة مبنية على وثائق ودليل، مش ذوق. كمان حددت موضوع واضح: العلاقات بين الآداب والتأثير. اللي خسره المجال إن البحث اتضيق: التركيز على حصر التأثيرات خلى النص نفسه يغيب، والقيمة الفنية بقت حاشية. وكمان المركزية الأوروبية خلت آداب كتير برة الصورة. يعني المدرسة أدت للمجال أساس قوي، بس أساس محتاج توسيع."},{"i":"comp-07","s":34,"h":"6) خلاصة","t":"write","x":"قارن بين دراسة التأثير ودراسة النص نفسه: إيه اللي كل واحدة بتقدر تقوله، وإيه اللي بتسيبه؟ (5 ل 7 جمل) . دراسة التأثير بتقدر تقولك إيه اللي اتنقل، ومن مين، وإمتى، وإزاي، وده محتاج وثائق ودليل. بس ممكن تسيب سؤال أهم: النص الجديد عمل إيه باللي خده، وليه. دراسة النص نفسه بتركز على البناء والمعنى والجمال، وبتقدر تقولك إزاي النص بيشتغل. بس ممكن تسيب السياق والعلاقات. أنفع بحث بيجمع الاتنين: يبدأ من النص ويسأل عن علاقاته، ويرجع للنص عشان يفهم إيه اللي عمله بالعلاقة دي."},{"i":"comp-08","s":1,"h":"مقدمة","t":"learn","x":"في الدرس اللي فات عرفنا فلسفة المدرسة الفرنسية. النهاردة هنشوف أدواتها بالتفصيل. المدرسة بتبدأ من نموذج بسيط: نص بيبعت، ونص بيستقبل، وحاجة بتوصل بينهم."},{"i":"comp-08","s":3,"h":"1) نموذج التواصل","t":"learn","x":"فان تيجيم استخدم نموذج تواصل من تلات أجزاء: émetteur و récepteur و transmetteur . المصدر هو اللي بيبعت، والمستقبل هو اللي بياخد، والناقل هو الوسيط اللي بينقل: ترجمة، أو مجلة، أو رحالة، أو مدرس."},{"i":"comp-08","s":4,"h":"1) نموذج التواصل","t":"mc","x":"إيه الأجزاء التلاتة في نموذج فان تيجيم؟ ؟ المصدر، والمستقبل، والناقل / الكاتب، والقارئ، والناقد / النص، والترجمة، والنشر / الشعر، والرواية، والمسرح . النموذج تلاتة: émetteur وrécepteur وtransmetteur."},{"i":"comp-08","s":5,"h":"1) نموذج التواصل","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ التناص محتاج إن القارئ يكون قريت النص القديم عشان يفهم النص الجديد. / الناقل في النموذج ممكن يكون ترجمة أو مجلة أو رحالة. / الترجمة بتنقل النص بشكل مطابق للأصل دايما. / كل اللي في الموجة الرابعة مرتاحين لكلمة «نسوية». . الناقل هو الوسيط اللي بينقل النص بين الثقافات."},{"i":"comp-08","s":6,"h":"1) نموذج التواصل","t":"learn","x":"النموذج ده هو اللي بيخلي المدرسة الفرنسية تقدر ترسم «خط سير» للنص: من فين، لفين، وبإيه."},{"i":"comp-08","s":8,"h":"2) دراسة التأثير","t":"learn","x":"المدرسة صنفت التأثير لستة أنواع. 1) تأثير الشخصية والروح. 2) تأثير التقنية والأسلوب. 3) تأثير الشخصيات الفنية. 4) تأثير الموضوع. 5) تأثير الإطار والبيئة. 6) تأثير الاتجاه الفكري."},{"i":"comp-08","s":9,"h":"2) دراسة التأثير","t":"learn","x":"مثال على الشخصيات الفنية: دون جوان. بدأ في الحكاية الإسبانية كصورة متمردة، وبعدها ظهر في أعمال كتير: مسرحية موليير، وقصيدة بايرون، وملحمة بوشكين، وأوبرا موتسارت."},{"i":"comp-08","s":10,"h":"2) دراسة التأثير","t":"mc","x":"دون جوان مثال على أي نوع من أنواع التأثير؟ ؟ تأثير الشخصيات الفنية / تأثير التقنية / تأثير الإطار / تأثير الاتجاه الفكري . دون جوان شخصية فنية انتقلت بين أعمال كتير."},{"i":"comp-08","s":11,"h":"2) دراسة التأثير","t":"learn","x":"ومثال على الموضوع: فاوست. الحكاية كانت موجودة قبل جوته، وظهرت عند مارلو، وبعدها في أعمال جوته وفاجنر وجونو."},{"i":"comp-08","s":12,"h":"2) دراسة التأثير","t":"learn","x":"وللتأثير خمسة أنماط حسب اتجاهه. خطي: واحد لواحد. إشعاعي: واحد لكذا واحد. بؤري: كذا واحد لواحد. متقاطع: الطرفين بيتبادلوا الأدوار. دائري: بيرجع لنقطة البداية."},{"i":"comp-08","s":13,"h":"2) دراسة التأثير","t":"mc","x":"إيه نمط التأثير اللي بيبدأ من واحد وينتهي لكذا واحد؟ ؟ الإشعاعي / الخطي / البؤري / الدائري . الإشعاعي واحد لكذا واحد."},{"i":"comp-08","s":14,"h":"2) دراسة التأثير","t":"learn","x":"مثال على المتقاطع: بايرون أثر في بوشكين مباشرة، وبوشكين أثر في ليرمونتوف، فبايرون وصل للثاني بشكل غير مباشر."},{"i":"comp-08","s":15,"h":"2) دراسة التأثير","t":"learn","x":"ومثال على الدائري: صور من الشعر الصيني ومن الزن البوذي وصلت لليابان، وعملت هايكو، والهايكو أثر في الشعراء التصويريين في إنجلترا وأمريكا، وبعدها التصويرية رجعت للصين وأثرت في الشعر الحر."},{"i":"comp-08","s":17,"h":"3) دراسة المصدر","t":"learn","x":"دراسة المصدر بتسأل السؤال بالعكس. بدل ما تبدأ من المصدر، بتبدأ من المستقبل: النص ده أخد من فين؟ وإيه الدليل؟"},{"i":"comp-08","s":18,"h":"3) دراسة المصدر","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ دراسة المصدر بتبدأ من المستقبل وترجع تدور على الأصل. / التناص محتاج إن القارئ يكون قريت النص القديم عشان يفهم النص الجديد. / الموجة التالتة اتفق كل أصحابها على تعريف واحد لمعنى «الست». / الترجمة بتنقل النص بشكل مطابق للأصل دايما. . دراسة المصدر بتسأل: النص ده أخد من فين؟"},{"i":"comp-08","s":19,"h":"3) دراسة المصدر","t":"learn","x":"وفان تيجيم قسم وسائط التأثير لتلاتة. الانطباع: تجربة مباشرة أو سفر. التعبير الشفهي: حكايات وأساطير وأغاني. التعبير المكتوب: نصوص وترجمات."},{"i":"comp-08","s":20,"h":"3) دراسة المصدر","t":"learn","x":"وكمان قسم المصدر لنوعين. مصدر معزول: النص أخد من عمل واحد. ومصدر جماعي: أخد من أكتر من عمل، وده أصعب لأنه محتاج بيانات أكتر."},{"i":"comp-08","s":22,"h":"4) الاستقبال","t":"learn","x":"والجزء التالت: الاستقبال. مين قرا النص؟ الوسط الأدبي والناشرين ردوا إزاي؟ وإيه اللي اتنشر عنه؟"},{"i":"comp-08","s":23,"h":"4) الاستقبال","t":"learn","x":"وكمان درجة التأثير ومدته: تأثير سطحي ولا عميق؟ قصير ولا طويل؟"},{"i":"comp-08","s":24,"h":"4) الاستقبال","t":"learn","x":"مثال بيتكرر في الدراسات المقارنة: مونتين في الصين. وصل للأدب الصيني عبر «Essays» الإنجليزية وكاتب ياباني، فاتعرف هناك واتقبل، وعمل شكل مقالي خاص."},{"i":"comp-08","s":26,"h":"5) خلاصة","t":"learn","x":"قوة النموذج: بيخليك تسأل أسئلة قابلة للفحص. مين؟ إمتى؟ بإيه؟ وإيه الدليل؟ وده اللي حول المقارنة من ذوق لدليل."},{"i":"comp-08","s":27,"h":"5) خلاصة","t":"learn","x":"وحدوده: بيفترض اتجاه واحد. بيبص للنص المستقبل كأنه بياخد بس، وبيقلل من إبداعه، وبيحول الترجمة لقناة سلبية. وده اللي المدرسة الأمريكية هتهاجمه بعد كده."},{"i":"comp-08","s":28,"h":"5) خلاصة","t":"mc","x":"إيه أضعف نقطة في نموذج المدرسة الفرنسية؟ ؟ إنه بيفترض اتجاه واحد ويقلل من إبداع النص المستقبل / إنه بيهمل الوثائق / إنه بيرفض دراسة الترجمة / إنه بيدرس النص لوحده . النموذج بيفترض اتجاه واحد، وده اللي المدرسة الأمريكية هتهاجمه."},{"i":"comp-08","s":29,"h":"5) خلاصة","t":"recall","x":"اشرح نموذج فان تيجيم في سطرين. . النموذج تلات أجزاء: المصدر اللي بيبعت، والمستقبل اللي بياخد، والناقل اللي بينقل بينهم زي الترجمة أو المجلة أو الرحالة. النموذج بيرسم خط سير النص من فين لفين وبإيه."},{"i":"comp-08","s":30,"h":"5) خلاصة","t":"recall","x":"إيه الفرق بين المصدر المعزول والمصدر الجماعي؟ . المصدر المعزول معناه إن النص أخد من عمل واحد، والمصدر الجماعي معناه إنه أخد من أكتر من عمل. الجماعي أصعب لأنه محتاج بيانات أكتر وتتبع أدق."},{"i":"comp-08","s":31,"h":"5) خلاصة","t":"write","x":"قارن بين دراسة التأثير ودراسة المصدر: إيه اللي بيبدأ منه الباحث في كل حالة، وإيه اللي بيتغير في السؤال؟ (5 ل 7 جمل) . دراسة التأثير بتبدأ من المصدر: عندك كاتب أو عمل معروف، وبتدور على أثره في كاتب أو أدب تاني. دراسة المصدر بتبدأ من المستقبل: عندك نص، وبتدور على أصله أو أصله المحتمل. السؤال بيتغير من «إيه اللي عمله ده في ده؟» ل«ده أخد من فين؟». الاتنين محتاجين دليل وثائقي، لكن المصدر أصعب لأنه بيدور على حاجة مش معروفة، والتأثير أسهل لأن نقطة البداية واضحة."},{"i":"comp-08","s":32,"h":"5) خلاصة","t":"write","x":"قارن بين النمط الخطي والنمط الدائري للتأثير: إيه اللي كل نمط بيقدر يوضحه، وإيه اللي بيسيبه؟ (5 ل 7 جمل) . النمط الخطي بيوضح تأثير مباشر من واحد لواحد، زي تأثير ديكنز في لاو شيه، وده سهل الإثبات لأنه خط واحد. النمط الدائري بيوضح حركة أعقد: النص بيروح ويرجع، وبيتغير في كل محطة، زي الصور الصينية اللي وصلت لليابان وعملت هايكو، وأثرت في التصويرية، ورجعت للصين. الخطي بيقدر يثبت الاتصال، لكنه بيسيب التحولات اللي بتحصل في الطريق. الدائري بيوضح التحولات، لكنه أصعب في الإثبات لأنه محتاج وثائق من كل محطة."},{"i":"comp-09","s":1,"h":"مقدمة","t":"learn","x":"المدرسة الفرنسية بنت أول نظرية كاملة للمجال. النهاردة هنشوف الاعتراض اللي جه من أمريكا، واللي غير شكل الأدب المقارن. المدرسة الأمريكية مش بلد، هي اتجاه. الاسم جه من مجموعة باحثين في أمريكا اعترضوا على منهج الفرنسيين في الخمسينات."},{"i":"comp-09","s":3,"h":"1) ليه الاعتراض جه في الوقت ده؟","t":"learn","x":"من آخر القرن التسعتاشر، الوضعية بدأت تفقد مكانها. ظهرت اتجاهات ضد التجريب: فلسفة برجسون، وحدس كروتشه في الجمال، والرمزية والفرويدية في الأدب."},{"i":"comp-09","s":4,"h":"1) ليه الاعتراض جه في الوقت ده؟","t":"mc","x":"إيه اللي خلى الاعتراض على الوضعية يظهر في آخر القرن التسعتاشر؟ ؟ اتجاهات ضد التجريب، زي فلسفة برجسون وحدس كروتشه والرمزية / لأن المدرسة الفرنسية سابت المجال ومحدش اشتغل فيه / لأن الحكومات منعت دراسة الأدب في أوروبا / لأن كل النصوص القديمة اتترجمت خلاص . الوضعية كانت بتبص للأدب كظاهرة تتقاس، والاتجاهات الجديدة قالت إن دي طريقة غلط."},{"i":"comp-09","s":5,"h":"1) ليه الاعتراض جه في الوقت ده؟","t":"learn","x":"الاتجاه ده قال حاجة بسيطة: الأدب مش ظاهرة طبيعية نقيسها في معمل. الأدب قيمة جمالية، والقيمة مش بتتقاس بالحاجات المادية."},{"i":"comp-09","s":7,"h":"2) مؤتمر شابل هيل 1958","t":"learn","x":"المؤتمر التاني للرابطة الدولية للأدب المقارن (ICLA) اتعمل سنة 1958 في شابل هيل، نورث كارولينا. فيه الباحثين الأمريكيين، وعلى رأسهم رينيه ويلك، حطوا الاعتراض الكبير على منهج المدرسة الفرنسية."},{"i":"comp-09","s":8,"h":"2) مؤتمر شابل هيل 1958","t":"learn","x":"ليه المؤتمر ده مهم؟ لأنه أول مرة الخلاف ما فضلش كلام في المجلات، بقى مواجهة معلنة قدام المجال كله."},{"i":"comp-09","s":9,"h":"2) مؤتمر شابل هيل 1958","t":"mc","x":"فين اتقال الاعتراض الأمريكي الكبير بشكل معلن؟ ؟ في المؤتمر التاني للرابطة الدولية سنة 1958 في شابل هيل / في أول مؤتمر للرابطة سنة 1954 في أكسفورد / في كتاب اتطبع في باريس سنة 1931 / في مجلة ألمانية سنة 1887 . شابل هيل 1958 هو المؤتمر اللي ويلك ورفاقه حطوا فيه اعتراضهم قدام المجال."},{"i":"comp-09","s":11,"h":"3) ويلك: أزمة الأدب المقارن","t":"learn","x":"رينيه ويلك (1903-1995) كان من أشهر نقاد الأدب في أمريكا. في مقاله «أزمة الأدب المقارن» قال إن المجال واقف على حافة خطر. سبب الخطر عنده: الباحثين حبسوا حدود المجال بمفهوم ميكانيكي للأصل والتأثير، ودافعهم كان وطني وأكتر من اللازم."},{"i":"comp-09","s":12,"h":"3) ويلك: أزمة الأدب المقارن","t":"learn","x":"وعبارته اللي بقت مشهورة: المدرسة الفرنسية حولت الأدب المقارن ل international trade في الأدب. يعني بتبص للاستيراد والتصدير: ده جه من هنا، وطلع هناك. مش للعمل الأدبي نفسه."},{"i":"comp-09","s":13,"h":"3) ويلك: أزمة الأدب المقارن","t":"learn","x":"وطلب حاجة واضحة: البحث لازم يهتم بقيمة العمل الأدبي نفسه. من غير كده، الدراسة تفضل حتت متفرقة عن الأصل والتأثير، ومش هتوصل لتقييم عمل واحد كامل."},{"i":"comp-09","s":14,"h":"3) ويلك: أزمة الأدب المقارن","t":"mc","x":"إيه اللي ويلك قصده بعبارة «التجارة الدولية» في الأدب؟ ؟ إن الفرنسيين بيدرسوا انتقال النصوص بين البلاد بدل ما يدرسوا العمل نفسه / إن الأدب بيتكتب للتصدير للخارج بس / إن الترجمة التجارية هي اللي بتحدد قيمة الأدب / إن المجال لازم يبقى فيه بيع وشرا للكتب . العبارة نقد: التركيز على من فين لفين بدل قيمة العمل الأدبي."},{"i":"comp-09","s":15,"h":"3) ويلك: أزمة الأدب المقارن","t":"learn","x":"وكمان ويلك قال إن الفصل بين الأدب المقارن والأدب العام فصل مصطنع، لأن الاتنين بيدرسوا نفس الحاجة: الأدب."},{"i":"comp-09","s":17,"h":"4) ريماك: تاريخ ولا نقد؟","t":"learn","x":"هنري ريماك لخص الخلاف في جملة واحدة. قال المواجهة دي هي مواجهة بين «تاريخ الأدب» و«نقد الأدب»."},{"i":"comp-09","s":18,"h":"4) ريماك: تاريخ ولا نقد؟","t":"learn","x":"ريماك وصف الفرنسيين بدقة: بيفضلوا الأسئلة اللي بتتحل بدليل واقعي، وغالبا وثائق شخصية. وهو شايف إن الأدب المقارن لازم يربط الأدب مش بمجال واحد، لكن بالفنون والفكر كمان."},{"i":"comp-09","s":19,"h":"4) ريماك: تاريخ ولا نقد؟","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ «الأنوثة الأبدية» فكرة بتؤكد إن الأنوثة تكوين اجتماعي. / الموجة التالتة اتفق كل أصحابها على تعريف واحد لمعنى «الست». / ريماك شايف إن أساس الدراسة هو العمل الأدبي نفسه، مش الوثائق حواليه. / أنهي جملة من دول غلط؟ . دي نقطته الأساسية في مواجهة الاعتماد على الوثائق."},{"i":"comp-09","s":20,"h":"4) ريماك: تاريخ ولا نقد؟","t":"learn","x":"وأضاف: أساس أي دراسة معقولة هو العمل الأدبي نفسه. كل بحث لازم يبدأ من فهم كامل للعمل، والمقارنة بعد كده بتساعد على تذوق القيمة الجمالية."},{"i":"comp-09","s":22,"h":"5) خمس اعتراضات","t":"learn","x":"الاعتراضات اتلخصت في خمس نقط. 1) التركيز الزيادة على دراسة التأثير في اتجاه واحد. 2) إهمال تحليل النص نفسه. 3) الحتمية والتبسيط. 4) ضيق النطاق: أوروبا بس. 5) الجمود النظري."},{"i":"comp-09","s":23,"h":"5) خمس اعتراضات","t":"mc","x":"ريماك لخص الخلاف بين المدرستين بأنه مواجهة بين إيه؟ ؟ تاريخ الأدب ونقد الأدب / الشعر والنثر / الأدب القديم والأدب الحديث / الترجمة والتأليف . دي صياغته الشهيرة للخلاف: تاريخ مقابل نقد."},{"i":"comp-09","s":24,"h":"5) خمس اعتراضات","t":"learn","x":"خد بالك من نقطة 3: الفرنسيين كانوا بيفسروا كل حاجة بسبب. الأمريكيين قالوا لأ: فيه إبداع فردي، ومصادفة، وظروف تاريخية مش متوقعة."},{"i":"comp-09","s":25,"h":"5) خمس اعتراضات","t":"learn","x":"ونقطة 4: النطاق كان أوروبي في الأساس، فده استبعد أدب كتير من العالم ومن أصوات مهمشة."},{"i":"comp-09","s":26,"h":"5) خمس اعتراضات","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ أنهي جملة من دول غلط؟ / كل اللي في الموجة الرابعة مرتاحين لكلمة «نسوية». / «الأنوثة الأبدية» فكرة بتؤكد إن الأنوثة تكوين اجتماعي. / من اعتراضات المدرسة الأمريكية إن نطاق المدرسة الفرنسية كان أوروبي في الأساس. . دي النقطة الرابعة من الاعتراضات الخمسة."},{"i":"comp-09","s":28,"h":"6) النتيجة","t":"learn","x":"النتيجة إن المجال اتوسع. من دراسة تأثير بين أدبين قوميين، لدراسة علاقات أوسع: تناص، وتحليل نص، وأدب من كل العالم، ونظريات جديدة."},{"i":"comp-09","s":29,"h":"6) النتيجة","t":"learn","x":"الدرس الجاي هنشوف أهم أداة جابت التوسع ده: التناص."},{"i":"comp-09","s":30,"h":"6) النتيجة","t":"recall","x":"ليه المدرسة الأمريكية اعترضت على منهج المدرسة الفرنسية؟ اذكر تلات أسباب. . لأن الفرنسيين ركزوا على التأثير في اتجاه واحد وربطوه بسبب ونتيجة، وأهملوا تحليل النص وقيمته الجمالية، وكان نطاقهم أوروبي في الأساس. والتلاتة دول جزء من خمس اعتراضات اتقالت في مؤتمر شابل هيل 1958."},{"i":"comp-09","s":31,"h":"6) النتيجة","t":"recall","x":"إيه اللي ويلك طلبه بدل دراسة التأثير؟ . إن البحث يهتم بقيمة العمل الأدبي نفسه، وإن الحدود المصطنعة بين الأدب المقارن والأدب العام تتشال، لأن الاتنين بيدرسوا الأدب."},{"i":"comp-09","s":32,"h":"6) النتيجة","t":"write","x":"اكتب فقرة قصيرة تقارن فيها بين المدرسة الفرنسية والمدرسة الأمريكية في هدف الدراسة. . الفرنسية بتسأل: النص ده جه من فين، وإيه الدليل؟ فهدفها يرسم خط سير للتأثير والمصدر. الأمريكية بتسأل: النص ده قيمته إيه، وإزاي بيتحاور مع نصوص تانية؟ فهدفها تحليل العمل وقيمته الجمالية وعلاقته بغيره من النصوص والثقافات."},{"i":"comp-10","s":1,"h":"مقدمة","t":"learn","x":"الدرس اللي فات شفنا الأمريكيين اعترضوا على دراسة التأثير. النهاردة هنشوف البديل اللي حطوه: التناص. التناص، أو intertextuality ، هو الفكرة اللي بقت أهم أداة في المجال بعد الخلاف."},{"i":"comp-10","s":3,"h":"1) يعني إيه تناص؟","t":"learn","x":"الفكرة بسيطة: النص مش بيقف لوحده. كل نص بيرد على نصوص تانية، وياخد منها، ويغير فيها، ويلعب معاها. يعني فيه حوار بين النصوص."},{"i":"comp-10","s":4,"h":"1) يعني إيه تناص؟","t":"learn","x":"وإيه الفرق عن التأثير؟ التأثير بيدور على أثر جه من نص لنص، في اتجاه واحد. التناص بيدور على الحوار: النصين بيتكلموا مع بعض، وممكن ميكونش فيه أصل واحد واضح."},{"i":"comp-10","s":6,"h":"2) النقد الجديد","t":"learn","x":"أول عامل ساعد على التحول: النقد الجديد. New Criticism قال: اقرأ النص نفسه، بنيته وشكله ولغته. مش تاريخه ولا ظروف كاتبه."},{"i":"comp-10","s":7,"h":"2) النقد الجديد","t":"mc","x":"إيه الفرق الأساسي بين التأثير والتناص؟ ؟ التأثير بيدور على أثر في اتجاه واحد، والتناص على حوار بين النصوص / التأثير بيخص الشعر بس، والتناص بيخص الرواية بس / التأثير بيستخدم وثائق، والتناص بيستخدم ترجمات بس / مفيش فرق، الاتنين نفس الحاجة باسمين . الفرق في الاتجاه: خط واحد عند التأثير، وحوار مفتوح عند التناص."},{"i":"comp-10","s":8,"h":"2) النقد الجديد","t":"learn","x":"ده نقل التركيز من بره النص لجواه، وده بالظبط اللي الأمريكيين كانوا عايزينه."},{"i":"comp-10","s":10,"h":"3) البنيوية","t":"learn","x":"البنيوية قالت إن النصوص بتحكمها بنى وقواعد تحت السطح. ده إدى الباحثين أدوات يحددوا بيها أنماط ومتكررات وصور أصلية مشتركة بين تقاليد أدبية مختلفة."},{"i":"comp-10","s":12,"h":"4) ما بعد البنيوية","t":"learn","x":"ما بعد البنيوية شككت في ثبات المعنى. قالت: المعنى متعدد، والقارئ بيدخل في صنعه. فالعلاقة بين النصوص بقت مفتوحة ومتغيرة، مش مقفولة على تفسير واحد."},{"i":"comp-10","s":13,"h":"4) ما بعد البنيوية","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ الموجة التالتة اتفق كل أصحابها على تعريف واحد لمعنى «الست». / الموجة الأولى كانت نضيفة تماما من أي مواقف عنصرية. / التناص محتاج إن القارئ يكون قريت النص القديم عشان يفهم النص الجديد. / البنيوية ساعدت على دراسة التناص لأنها أدت أدوات لتحديد أنماط مشتركة بين التقاليد الأدبية. . الأنماط والمتكررات هي مادة التناص الأولى."},{"i":"comp-10","s":15,"h":"5) من التأثير للتناص","t":"learn","x":"النتيجة إن الصورة اتغيرت. بدل خط واحد: مصدر، وبعده مستقبل، بقى فيه حوار معقد، وفيه أكتر من صوت بيصنع المعنى."},{"i":"comp-10","s":16,"h":"5) من التأثير للتناص","t":"mc","x":"إيه اللي ما بعد البنيوية ضافته لفكرة التناص؟ ؟ إن المعنى متعدد والقارئ بيدخل في صنعه، فالعلاقة بين النصوص مفتوحة / إن النص لازم يتفسر تفسير واحد نهائي / إن التناص مالهوش لازمة في الدراسة / إن القارئ مالوش دور خالص . تعدد المعنى ودور القارئ هما الإضافة الأساسية."},{"i":"comp-10","s":17,"h":"5) من التأثير للتناص","t":"learn","x":"وكمان التناص حرر الدراسة من حدود الأدب القومي: تقدر تربط نص عربي بنص لاتيني من غير ما تدور على خط تأثير مباشر بينهم."},{"i":"comp-10","s":19,"h":"6) أمثلة التناص","t":"learn","x":"التناص بيظهر في حاجات ملموسة في النص. إحالات ومراجع لنصوص تانية. محاكاة ساخرة وتكييفات لنوع أدبي. موضوعات ودوافع مشتركة بين ثقافات. أثر الأحداث التاريخية والسياق الثقافي."},{"i":"comp-10","s":20,"h":"6) أمثلة التناص","t":"learn","x":"مثال: رواية بتعيد حكاية قديمة بلسان جديد. مش شرط تكون قريت الحكاية القديمة، لكن النص بيلعب معاها، والقارئ اللي يعرفها بيقرأ طبقة زيادة."},{"i":"comp-10","s":21,"h":"6) أمثلة التناص","t":"mc","x":"أنهي واحد من دول مثال على التناص زي ما الدرس شرحه؟ ؟ رواية بتعيد حكاية قديمة بلسان جديد وتلعب معاها / رواية مكتوبة بلغة واحدة ومفيش فيها إحالات / قصيدة بتوصف منظر طبيعي من غير أي إشارة لنص تاني / مقال بيلخص كتاب ملخص جاف . إعادة حكاية قديمة بلسان جديد هي التناص في أبسط صوره."},{"i":"comp-10","s":23,"h":"7) العالمية والتخصصات","t":"learn","x":"الأمريكيين كمان دوروا على أنماط مشتركة تعبر الحدود الوطنية. موضوعات وتجارب إنسانية عامة بتتكرر في آداب من بلاد مختلفة، وده اللي سموه النزعة الإنسانية العامة."},{"i":"comp-10","s":24,"h":"7) العالمية والتخصصات","t":"learn","x":"وفتحوا المجال على تخصصات تانية. التاريخ، والفلسفة، والأنثروبولوجيا، والدراسات الثقافية. التخصصات دي بتدي تفسير أعمق للنص وسياقه."},{"i":"comp-10","s":25,"h":"7) العالمية والتخصصات","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ أنهي جملة من دول صحيحة؟ / التأثير محتاج دليل إن النص التاني وصل للأول. / من خصائص المدرسة الأمريكية إنها فتحت المجال على تخصصات زي الفلسفة والأنثروبولوجيا. / التناص محتاج إن القارئ يكون قريت النص القديم عشان يفهم النص الجديد. . القارئ اللي يعرف النص القديم بيقرأ طبقة زيادة، لكن النص بيشتغل من غير كده كمان."},{"i":"comp-10","s":27,"h":"8) الأسماء والظروف","t":"learn","x":"من الأسماء المهمة في المدرسة الأمريكية: ويلك، وريماك، وهاري ليفين، وإريك أويرباخ. أويرباخ كتب كتابه الشهير «المحاكاة» وهو بعيد عن بلده، وده مثال على باحث اشتغل في ظروف صعبة وبرضه غير المجال."},{"i":"comp-10","s":28,"h":"8) الأسماء والظروف","t":"learn","x":"والظرف بعد الحرب العالمية التانية أدى لرغبة في التعاون الدولي والتفاهم بين الشعوب، والروح دي ساعدت المجال في أمريكا."},{"i":"comp-10","s":29,"h":"8) الأسماء والظروف","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ أنهي جملة من دول غلط؟ / الموجة التالتة اتفق كل أصحابها على تعريف واحد لمعنى «الست». / من خصائص المدرسة الأمريكية إنها فتحت المجال على تخصصات زي الفلسفة والأنثروبولوجيا. / «الأنوثة الأبدية» فكرة بتؤكد إن الأنوثة تكوين اجتماعي. . التعددية بين التخصصات من علاماتها الأساسية."},{"i":"comp-10","s":31,"h":"9) خلاصة","t":"learn","x":"نقدر نلخص المدرسة الأمريكية في سطرين. نقلت المجال من دراسة تاريخية للتأثير لدراسة أدبية للتناص والقيمة. والنتيجة إن المجال بقى أوسع وأكتر تنوعا، والمدرستين بقوا موجودين مع بعض."},{"i":"comp-10","s":32,"h":"9) خلاصة","t":"learn","x":"الدرس الجاي هنتكلم عن حاجة بتخلي التناص ممكن أصلا: الترجمة."},{"i":"comp-10","s":33,"h":"9) خلاصة","t":"recall","x":"اشرح الفرق بين دراسة التأثير ودراسة التناص. . دراسة التأثير بتدور على أثر جه من نص لنص في اتجاه واحد، وبتحتاج دليل على الأصل. دراسة التناص بتشوف العلاقة كحوار بين النصوص، ممكن يكون متعدد الاتجاهات، ومش شرط يكون فيه أصل واحد واضح."},{"i":"comp-10","s":34,"h":"9) خلاصة","t":"recall","x":"إيه دور النقد الجديد والبنيوية وما بعد البنيوية في التحول للتناص؟ . النقد الجديد ركز على النص نفسه، والبنيوية أدت أدوات لتحديد أنماط مشتركة، وما بعد البنيوية فتحت المعنى على تعدد القراءات ودور القارئ."},{"i":"comp-10","s":35,"h":"9) خلاصة","t":"write","x":"خد نصين تعرفهم من ثقافتين مختلفين، واشرح إزاي ممكن يكون بينهم تناص مش تأثير مباشر. . مثال: ممكن تلاقي نفس فكرة «الرحلة اللي بتغير الإنسان» في حكاية شعبية عربية وفي رواية لاتينية، من غير دليل إن واحدة وصلت للتانية. الاتنين بيعيدوا بناء نمط إنساني قديم، والقراءة المقارنة بتقارن إزاي كل نص شكل النمط ده بلغته وثقافته."},{"i":"comp-11","s":1,"h":"مقدمة","t":"learn","x":"من غير ترجمة مفيش أدب مقارن. جملة كبيرة، بس هي الحقيقة اللي الدرس ده هيشرحها. إزاي تقارن نص مكتوب بلغة إنت مش عارفها؟ لازم حد ينقله لك. واللي بينقل مش مجرد وسيلة، هو صانع قرار."},{"i":"comp-11","s":3,"h":"1) المترجم مش قاموس","t":"learn","x":"وظيفة الترجمة إنها تعبر عن معنى العمل الأصلي بلغة تانية. وعشان كده المترجم محتاج أكتر من مهارة لغوية: محتاج يعرف الخلفية الاجتماعية والثقافية لحياة الكاتب، ونفسيته في الكتابة، وتجاربه."},{"i":"comp-11","s":4,"h":"1) المترجم مش قاموس","t":"learn","x":"والمترجم كمان وسيط، وده بيغير كل حاجة. الاختيارات والحذف والتعديل في النص الأصلي مش بريئة: بتعبر عن ذوق المترجم، وعن قراره هو."},{"i":"comp-11","s":5,"h":"1) المترجم مش قاموس","t":"mc","x":"ليه المترجم مش مجرد وسيلة نقل محايدة؟ ؟ لأن اختياراته وحذفه بيغيروا النص وبتعبر عن ذوقه وقراره / لأنه بيكتب النص الأصلي من الأول / لأنه بيشتغل من غير ما يعرف اللغة / لأنه بيترجم للكاتب مش للقارئ . الوسيط بياخد قرارات، والقرارات دي بتظهر في النص المترجم."},{"i":"comp-11","s":7,"h":"2) الترجمة بتغير النص","t":"learn","x":"في الترجمة، أسلوب العمل ولغته ونوعه ومحتواه ممكن يتعاد كتابتهم. المترجم بيقترض قواعد وتعبيرات وتشبيهات من لغته هو، عشان النص يتوافق مع ثقافته."},{"i":"comp-11","s":8,"h":"2) الترجمة بتغير النص","t":"learn","x":"النتيجة إن العمل بيتعاد تركيبه عشان يناسب التقليد الأدبي الجديد. وهنا بالظبط بيحصل التأثير: النص بيوصل بشكل جديد، ومش بشكل مطابق للأصل."},{"i":"comp-11","s":10,"h":"3) الترجمة غير المباشرة","t":"learn","x":"فيه ظاهرة منتشرة: الترجمة من نسخة مترجمة، مش من الأصل. يعني relay translation : العمل يتترجم للغة، وبعدين يتترجم من النسخة دي للغة تالتة."},{"i":"comp-11","s":11,"h":"3) الترجمة غير المباشرة","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ الترجمة بتنقل النص بشكل مطابق للأصل دايما. / مقدمة المترجم وحواشيه ممكن تكون مصدر مهم لدراسة انتشار العمل وتأثيره. / «الناقل» في المدرسة الفرنسية هو الوسيط اللي بينقل النص، زي الترجمة أو المجلة. / التأثير محتاج دليل إن النص التاني وصل للأول. . الترجمة بتعيد تركيب النص عشان يناسب التقليد الجديد، فالنص بيوصل بشكل مختلف."},{"i":"comp-11","s":12,"h":"3) الترجمة غير المباشرة","t":"learn","x":"مثال من الصين الحديثة. كتير من الأعمال الإنجليزية والفرنسية والروسية وصلت للقارئ الصيني عن طريق اليابانية. وبعض الأعمال الإيطالية والإسبانية وصلت عن طريق الإنجليزية."},{"i":"comp-11","s":14,"h":"4) مقارنة النسخ","t":"learn","x":"لما تقارن نسخ مختلفة من نفس العمل، بتلاقي حاجة مهمة. بتشوف تغير الانطباع اللي سابه العمل الأجنبي وهو بينتشر: مع الوقت، ومع تغير الاهتمامات، ومع تطور اللغة."},{"i":"comp-11","s":15,"h":"4) مقارنة النسخ","t":"learn","x":"والمقدمة والحواشي مش مجرد كلام زيادة. فيها مواد ثمينة عن التغير والانتشار والوسائط والتأثير، وقت ما كاتب أجنبي يتنقل لبلد جديد."},{"i":"comp-11","s":16,"h":"4) مقارنة النسخ","t":"mc","x":"يعني إيه ترجمة غير مباشرة؟ ؟ إن العمل يتترجم من نسخة مترجمة، مش من النص الأصلي / إن العمل يتترجم مرتين لنفس اللغة / إن المترجم يترجم بدون أجر / إن الترجمة تكون نص قصير . الوسيط هنا ترجمة سابقة، مش الأصل."},{"i":"comp-11","s":18,"h":"5) ليه الترجمة أساس المجال","t":"learn","x":"دراسة علاقة عمل بعمل، وأدب بأدب، وتقليد أدبي بتقليد تاني، هي محتوى الأدب المقارن الأساسي. وكل ده مش ممكن يحصل من غير ترجمة في الأول."},{"i":"comp-11","s":19,"h":"5) ليه الترجمة أساس المجال","t":"mc","x":"ليه الترجمة أساس في الأدب المقارن؟ ؟ لأن دراسة العلاقات بين الآداب مش ممكنة من غير نقل النصوص بين اللغات / لأن الترجمة أسهل من التأليف / لأن كل الأدباء بيتكلموا نفس اللغة / لأن الترجمة بتلغي الاختلاف بين الثقافات . العلاقة بين آداب مختلفة بتفترض إن النصوص بتوصل، والوصول بيحصل بالترجمة."},{"i":"comp-11","s":20,"h":"5) ليه الترجمة أساس المجال","t":"learn","x":"وعشان كده تاريخ الترجمة ونظرياتها ومهاراتها جزء من تكوين الباحث. من غيرها، فهم تاريخ التواصل الأدبي بين الأمم يبقى ناقص."},{"i":"comp-11","s":22,"h":"6) الوسيط الأول","t":"learn","x":"لو رجعنا للمدرسة الفرنسية، هنلاقي الترجمة هي الوسيط الأول في نموذجها. فان تيجيم سمى الوسيط «الناقل»، والترجمة أوضح صورة للناقل: هي اللي بتخلي النص يعبر الحدود أصلا."},{"i":"comp-11","s":23,"h":"6) الوسيط الأول","t":"learn","x":"والفرق بين المدرستين هنا مش في أهمية الترجمة، لكن في السؤال: الفرنسية بتسأل عن خط النقل، والأمريكية بتسأل عن الحوار اللي النقل ده بيفتحه."},{"i":"comp-11","s":25,"h":"7) خلاصة","t":"learn","x":"خد معاك تلات جمل. المترجم وسيط بياخد قرارات، وقراراته بتظهر في النص. الترجمة بتعيد تركيب العمل ليناسب ثقافة جديدة، ومن هنا بيحصل التأثير. مقارنة النسخ والمقدمات بتكشف تاريخ الانتشار والتغير."},{"i":"comp-11","s":26,"h":"7) خلاصة","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ أنهي جملة من دول غلط؟ / مقدمة المترجم وحواشيه ممكن تكون مصدر مهم لدراسة انتشار العمل وتأثيره. / أنهي جملة من دول غلط؟ / «الأنوثة الأبدية» فكرة بتؤكد إن الأنوثة تكوين اجتماعي. . المقدمة بتكشف قرارات المترجم ومعلومات عن النقل والانتشار."},{"i":"comp-11","s":27,"h":"7) خلاصة","t":"learn","x":"الدرس الجاي: مدرسة تالتة دخلت النقاش، ومركزها فكرة التغاير بين الحضارات."},{"i":"comp-11","s":28,"h":"7) خلاصة","t":"mc","x":"إيه الفرق بين المدرستين في تعاملهما مع الترجمة؟ ؟ الفرنسية بتسأل عن خط النقل، والأمريكية عن الحوار اللي النقل بيفتحه / الفرنسية شايفة الترجمة مش مهمة، والأمريكية شايفاها مهمة / الفرنسية بتترجم بنفسها، والأمريكية بتقرأ بلغات أصلية بس / مفيش فرق، الاتنين بيسألوا نفس السؤال . الترجمة مهمة عند الاتنين، والفرق في السؤال اللي بيتسأل عنها."},{"i":"comp-11","s":29,"h":"7) خلاصة","t":"recall","x":"إيه اللي المترجم محتاج يعرفه غير اللغة؟ . الخلفية الاجتماعية والثقافية لحياة الكاتب، ونفسيته في الكتابة، وتجاربه. وده اللي بيخليه يفهم معنى العمل مش بس كلماته."},{"i":"comp-11","s":30,"h":"7) خلاصة","t":"recall","x":"إزاي مقارنة نسخ مختلفة من نفس العمل تفيد الباحث؟ . بتكشف تغير الانطباع اللي سابه العمل مع الوقت وتغير الاهتمامات وتطور اللغة، والمقدمات والحواشي بتضيف مواد عن النقل والانتشار والوسائط."},{"i":"comp-11","s":31,"h":"7) خلاصة","t":"write","x":"اشرح إزاي الترجمة ممكن تغير معنى نص، بمثال من عندك. . لو نص فيه تعبير ديني أو مثل شعبي محلي، والمترجم بدله بتعبير قريب لثقافة القارئ، المعنى القريب بيفضل، لكن الطبقة الثقافية الأصلية بتضعف. القارئ الجديد يفهم الموقف، بس مش حاسس بالمرجع الأصلي. وده تغيير في المعنى مش في الكلمات بس."},{"i":"comp-12","s":1,"h":"مقدمة","t":"learn","x":"الفرنسية بنت الوضعية، والأمريكية بنت التناص. النهاردة مدرسة تالتة: الصينية، وفكرتها المركزية التغاير. دخلت النقاش بفكرة مالهاش سابقة واضحة عند الاتنين: اختلاف الحضارات نفسه."},{"i":"comp-12","s":3,"h":"1) نقطة البداية","t":"learn","x":"الفرنسية والأمريكية اشتغلوا في الغالب جوه إطار حضارة واحدة: الغربية. فمقروا التغاير اللي بيحصل لما نص يعبر من حضارة لحضارة مختلفة تماما."},{"i":"comp-12","s":4,"h":"1) نقطة البداية","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ كل اللي في الموجة الرابعة مرتاحين لكلمة «نسوية». / نظرية التغاير اتفق عليها كل الباحثين من أول يوم. / «الأنوثة الأبدية» فكرة بتؤكد إن الأنوثة تكوين اجتماعي. / المدرسة الصينية بتقول إن المدرستين الفرنسية والأمريكية مقروا التغاير بين الحضارات المختلفة. . دي نقطة البداية اللي المدرسة الصينية بتبدأ منها."},{"i":"comp-12","s":5,"h":"1) نقطة البداية","t":"learn","x":"ده مش تقليل منهم، ده تحديد حدود: أدواتهم اتعملت لأسئلة معينة، والأسئلة الجديدة محتاجة أداة جديدة."},{"i":"comp-12","s":7,"h":"2) يعني إيه تغاير؟","t":"learn","x":"التغاير مش مجرد اختلاف. هو التغير اللي بيحصل في النص وهو بينتقل بين ثقافات. وأسبابه: اختلاف الثقافة، واختلاف الإيديولوجيا، وعوامل القارئ والمترجم الشخصية."},{"i":"comp-12","s":8,"h":"2) يعني إيه تغاير؟","t":"learn","x":"والتغاير حتمي في عملية التواصل والانتشار. مش عيب لازم يتصلح، هو النتيجة الطبيعية لأي نقل بين ثقافتين."},{"i":"comp-12","s":9,"h":"2) يعني إيه تغاير؟","t":"mc","x":"إيه اللي بيميز التغاير عن مجرد الاختلاف؟ ؟ إنه التغير اللي بيحصل في النص وهو بينتقل بين ثقافات، وليه أسباب / إنه اختلاف في اللغة بس / إنه خطأ في الترجمة لازم يتصحح / إنه اختلاف في رأي النقاد حول النص . التغاير ظاهرة لها أسباب ومكان: النقل بين الثقافات."},{"i":"comp-12","s":11,"h":"3) المشكلة اللي بتعالجها","t":"learn","x":"نظرية التغاير عرضت نفسها كحل لأزمة الأدب المقارن. بدل ما تختار بين الوضعية اللي بتدور على الحقائق، والجمالية اللي بتدور على القيمة، بتحاول تجمع الاتنين."},{"i":"comp-12","s":12,"h":"3) المشكلة اللي بتعالجها","t":"learn","x":"إزاي؟ مركزها الجمالية الأدبية، وبترجع للأصول الثقافية. يعني بتسأل في نفس الوقت: النص ده قيمته إيه كأدب، وإيه الأصول الثقافية اللي جاي منها؟"},{"i":"comp-12","s":14,"h":"4) النموذج","t":"learn","x":"النموذج اللي بتقترحه بيمشي في اتجاهين. من النص للسياق الثقافي، ومن السياق للنص، والعلاقة بينهم هي اللي بتتدرس."},{"i":"comp-12","s":15,"h":"4) النموذج","t":"mc","x":"إزاي نظرية التغاير بتتعامل مع الخلاف بين الوضعية والجمالية؟ ؟ بتحاول تجمع الاتنين: مركزها الجمالية الأدبية وبترجع للأصول الثقافية / بتختار الوضعية وتلغي الجمالية / بتختار الجمالية وتلغي الوضعية / بتقول إن الخلاف ده مش موجود أصلا . الجمع بين القيمة والأصل الثقافي هو جوهر الطرح."},{"i":"comp-12","s":16,"h":"4) النموذج","t":"learn","x":"وبكده بتربط الأدب بالحضارة، مش بس بأدب تاني. وده اللي بيفتح باب دراسة التغاير."},{"i":"comp-12","s":17,"h":"4) النموذج","t":"learn","x":"مثال بيوضح الفكرة. رواية عربية فيها أمثال شعبية ومراجع محلية، لما تتترجم للفرنسية: القارئ الفرنسي هيفهم الحكاية، لكن المراجع المحلية هتتغير أو تختفي. اللي حصل مش خطأ، ده تغاير."},{"i":"comp-12","s":19,"h":"5) نقطة أمانة","t":"learn","x":"لازم نقول حاجة مهمة: ده اتجاه بيتقدم كحل، وفيه ناس شايفين إنه لسه محتاج اختبار. زي أي نظرية جديدة، الحكم عليها بيكون بقدرتها على إنتاج دراسات مقنعة، مش بحماس أصحابها."},{"i":"comp-12","s":20,"h":"5) نقطة أمانة","t":"mc","x":"نموذج التغاير بيمشي في اتجاهين. يعني إيه؟ ؟ من النص للسياق الثقافي، ومن السياق للنص، والعلاقة بينهم هي موضوع الدراسة / من الكاتب للقارئ بس / من اللغة للغة، من غير سياق / من المدرسة الفرنسية للمدرسة الأمريكية بس . الاتجاهين هما اللي بيربطوا الأدب بالحضارة."},{"i":"comp-12","s":21,"h":"5) نقطة أمانة","t":"learn","x":"وممكن كمان تتسأل: هل التغاير بيوصف ظاهرة حقيقية، ولا بيبرر أخطاء النقل والترجمة؟ السؤال ده مطروح في النقاش حوالين النظرية."},{"i":"comp-12","s":23,"h":"6) خلاصة المجال","t":"learn","x":"المجال كله تراكم، مش استبدال. الفرنسية أدت الوضعية ودراسة التأثير، والأمريكية أدت التناص والقيمة الجمالية، والصينية أدت التغاير واختلاف الحضارات."},{"i":"comp-12","s":24,"h":"6) خلاصة المجال","t":"learn","x":"كل مدرسة سألت سؤال، ومحدش لغى التاني. والوضعية لسه طريقة من الطرق، زي ما شفنا في دروس المدرسة الفرنسية."},{"i":"comp-12","s":25,"h":"6) خلاصة المجال","t":"mc","x":"إيه الصورة اللي بيرسمها الدرس لتاريخ المدارس؟ ؟ تراكم: كل مدرسة ضافت سؤال وأداة، ومحدش لغى التاني / استبدال: كل مدرسة شالت اللي قبلها / تراجع: المجال بقى أضعف مع كل مدرسة / تطابق: كل المدارس بتقول نفس الكلام . التراكم هو الفكرة اللي بتختم الدرس."},{"i":"comp-12","s":27,"h":"7) الطريق للدرس الجاي","t":"learn","x":"الدرس الجاي ندخل موضوع جديد خالص: الحركة النسوية وموجاتها. هنشوف إزاي النقد النسوي دخل الأدب المقارن، وبقى أداة قراءة بتفتح أسئلة مالهاش علاقة بالتأثير ولا بالتناص."},{"i":"comp-12","s":28,"h":"7) الطريق للدرس الجاي","t":"recall","x":"إيه اللي نظرية التغاير بتقوله عن المدرستين اللي قبلها؟ . إن الفرنسية والأمريكية اشتغلوا جوه إطار حضارة واحدة غالبا، فمقروا التغاير اللي بيحصل لما نص يعبر بين حضارات مختلفة، وإن التغاير ده محتاج أداة جديدة."},{"i":"comp-12","s":29,"h":"7) الطريق للدرس الجاي","t":"recall","x":"ليه التغاير مش عيب في نظر النظرية؟ . لأن التغاير نتيجة طبيعية لأي نقل بين ثقافتين: اختلاف الثقافة والإيديولوجيا وعوامل القارئ والمترجم بتخلي النص يتغير، والدراسة بتدرس التغير ده بدل ما تتجاهله."},{"i":"comp-12","s":30,"h":"7) الطريق للدرس الجاي","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ «الأنوثة الأبدية» عند بوفوار هي فكرة إن فيه طبيعة أنثوية ثابتة بتتبرر بيها أدوار محددة. / نظرية التغاير اتفق عليها كل الباحثين من أول يوم. / أنهي جملة من دول صحيحة؟ / الكانون بيتغير مع الوقت، وفيه نقاش على اللي بيستبعده. . النظرية جديدة، وفيها نقاش واختبار لسه شغال."},{"i":"comp-12","s":31,"h":"7) الطريق للدرس الجاي","t":"write","x":"اكتب مثال على تغاير نص عربي لما يتترجم، واشرح إيه اللي بيتغير. . لو رواية عربية فيها أمثال شعبية ومراجع دينية، والترجمة بدلت الأمثال بتعبيرات قريبة للقارئ الأجنبي، القارئ بيفهم الموقف، لكن الطعم المحلي بيضعف. اللي بيتغير مش الكلمات بس، ده كمان علاقة النص بثقافته. وده تغاير: مش خطأ، لكن نتيجة حتمية للنقل، والدراسة بتقارن إزاي كل نسخة شكلت النص."},{"i":"comp-13","s":1,"h":"مقدمة","t":"learn","x":"من أول الدرس ده، المجال بيتوسع: من مدارس المقارنة لتاريخ الحركات الفكرية. النسوية حركة دخلت الأدب المقارن وبقت أداة قراءة، وفي نفس الوقت هي تاريخ اجتماعي وسياسي."},{"i":"comp-13","s":3,"h":"1) تعريف واضح قبل أي كلام","t":"learn","x":"النسوية حركة سياسية وثقافية واقتصادية هدفها حقوق متساوية وحماية قانونية للستات. وفي تعريف أوسع: مجموعة حركات وأيديولوجيات بتشترك في هدف واحد: تحديد وإثبات وتحقيق المساواة السياسية والاقتصادية والشخصية والاجتماعية بين الجنسين."},{"i":"comp-13","s":4,"h":"1) تعريف واضح قبل أي كلام","t":"learn","x":"وده معناه كمان مساواة في الفرص التعليمية والمهنية. مش «الستات أحسن من الرجالة»، ومش «الستات بس». المساواة بين الجنسين هي الهدف، والاتنين معنيين بيه."},{"i":"comp-13","s":5,"h":"1) تعريف واضح قبل أي كلام","t":"learn","x":"والنسوية مش رأي واحد. جواها نظريات سياسية واجتماعية وفلسفات بتشتغل على مسألة الفرق بين الجنسين، وبتختلف في تفسيرها وفي الحلول."},{"i":"comp-13","s":6,"h":"1) تعريف واضح قبل أي كلام","t":"mc","x":"إيه الهدف المشترك اللي بتحدده النسوية؟ ؟ المساواة السياسية والاقتصادية والشخصية والاجتماعية بين الجنسين / إن الستات تبقى أعلى من الرجالة في كل حاجة / إن الستات تسيب الشغل وتقعد في البيت / إن الرجالة تاخد حقوق الستات . التعريف مبني على المساواة، مش على تفضيل جنس على جنس."},{"i":"comp-13","s":8,"h":"2) أشهر فهم غلط","t":"learn","x":"حوالين النسوية أفكار مش دقيقة بتتكرر. «النسويات بيكرهوا الرجالة». «بيدافعوا عن الستات بس». «شايفين الستات أرقى من الرجالة»."},{"i":"comp-13","s":9,"h":"2) أشهر فهم غلط","t":"learn","x":"الدرس مش بيطلب منك توافق، بيطلب منك تعرف التعريف بدقة قبل ما تحكم. التعريف العلمي للحركة اتكتب فوق، وهو اللي بنشتغل بيه."},{"i":"comp-13","s":11,"h":"3) المصطلح: امتى اتشاع؟","t":"learn","x":"كلمة «نسوية» و«نسوي» ما انتشرتش بشكل واسع قبل السبعينات. لكنها كانت موجودة في الكلام العام قبل كده، وفيه أمثلة على استخدامها في الأربعينات."},{"i":"comp-13","s":12,"h":"3) المصطلح: امتى اتشاع؟","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ «الأنوثة الأبدية» فكرة بتؤكد إن الأنوثة تكوين اجتماعي. / من أشهر الفهم الغلط عن النسوية إنها حركة هدفها كره الرجالة. / أنهي جملة من دول غلط؟ / الحركة النسوية المنظمة بدأت قبل آخر القرن التسعتاشر بقرون. . ده فهم غلط منتشر، والدرس بيصححه بالتعريف."},{"i":"comp-13","s":14,"h":"4) ليه بنتكلم عن «موجات»؟","t":"learn","x":"أكبر صعوبة في فهم النسوية إن الفكر بتاعها اتغير مع الوقت، وده اللي عمل موجات. والموجة مش فترة زمنية بالضرورة، لكن بتتعرف بأهدافها وأدواتها أكتر من التواريخ."},{"i":"comp-13","s":15,"h":"4) ليه بنتكلم عن «موجات»؟","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ أنهي جملة من دول صحيحة؟ / الخلط بين الموجات النسوية ممكن يخلي الإجابة غلط حتى لو الكلام مكتوب بشكل جيد. / الحركة النسوية المنظمة بدأت قبل آخر القرن التسعتاشر بقرون. / المقارنة موجودة قبل كده، اللي ظهر في القرن التسعتاشر هو المادة والمنهج. . الأفكار قديمة، لكن الحركة المنظمة اتشكلت في آخر القرن التسعتاشر."},{"i":"comp-13","s":16,"h":"4) ليه بنتكلم عن «موجات»؟","t":"learn","x":"فيه تلات موجات معروفة، وكل واحدة مركزها مختلف. الأولى: السياسة. التانية: الثقافة. التالتة: الأكاديميا."},{"i":"comp-13","s":17,"h":"4) ليه بنتكلم عن «موجات»؟","t":"learn","x":"ومهم تعرف إن الموجات بتتقاطع، مش بتخلص واحدة عشان تبدأ التانية. الموجة التانية لسه موجودة وبتشتغل مع التالتة، وفيه باحثين بيعتبروا التانية استمرار للأولى مش قطيعة معاها."},{"i":"comp-13","s":18,"h":"4) ليه بنتكلم عن «موجات»؟","t":"mc","x":"المصطلح انتشر بشكل واسع في السبعينات. لكن إمتى كان موجود في الكلام العام؟ ؟ قبليها بفترة، وفيه أمثلة على استخدامه في الأربعينات / في نفس السنة بالظبط / بعد التسعينات بس / مفيش أي استخدام ليه قبل السبعينات . الانتشار جه في السبعينات، والاستخدام العام سبقه."},{"i":"comp-13","s":19,"h":"4) ليه بنتكلم عن «موجات»؟","t":"learn","x":"وفيه موجة رابعة بتظهر، ولسه مش متفق عليها زي التلاتة. مركزها التكنولوجيا، وده اللي هنشوفه بالتفصيل بعد شوية دروس."},{"i":"comp-13","s":21,"h":"5) الجدات قبل الحركة","t":"learn","x":"فيه أسماء بتتذكر كجذور قديمة، قبل ما تبقى فيه حركة منظمة. منهم سافو في اليونان القديمة، وهيلدجارد في العصور الوسطى، وكريستين دي بيزان."},{"i":"comp-13","s":22,"h":"5) الجدات قبل الحركة","t":"mc","x":"ليه الأسماء القديمة بتتذكر في تاريخ النسوية؟ ؟ لأنها دافعت عن كرامة المرأة وعقلها وإمكاناتها، وهي جذور للحركة / لأنها أسست الحركة المنظمة بنفسها / لأنها كتبت عن السياسة بس / لأنها عاشت في القرن التسعتاشر . الدرس بيفرق بين جذور الفكرة والحركة المنظمة اللي جاءت بعدها."},{"i":"comp-13","s":23,"h":"5) الجدات قبل الحركة","t":"learn","x":"وفي العصر الحديث بدري: أوليمب دي جوج، وماري وولستونكرافت، وجين أوستن. كل الأسماء دي دافعت عن كرامة المرأة وعقلها وإمكاناتها الإنسانية الأساسية. لكن الحركة المنظمة ما اتشكلتش إلا في آخر القرن التسعتاشر."},{"i":"comp-13","s":24,"h":"5) الجدات قبل الحركة","t":"mc","x":"إيه مركز الموجات التلاتة المعروفة بالترتيب؟ ؟ السياسة، وبعدها الثقافة، وبعدها الأكاديميا / التكنولوجيا، وبعدها السياسة، وبعدها الفن / الاقتصاد، وبعدها الدين، وبعدها التعليم / الأكاديميا، وبعدها التكنولوجيا، وبعدها السياسة . الترتيب ده هو اللي بيميز كل موجة عن التانية."},{"i":"comp-13","s":26,"h":"6) ليه الدرس ده في كورس أدب مقارن؟","t":"learn","x":"سؤال منطقي: إحنا في كورس أدب مقارن، ليه حركة اجتماعية؟ لأن النقد النسوي بقى أداة قراءة للنصوص، ولأن الأدب بيتقرأ في سياقه. الحركة غيرت الأسئلة اللي بنسألها للنص."},{"i":"comp-13","s":27,"h":"6) ليه الدرس ده في كورس أدب مقارن؟","t":"learn","x":"الدرس الجاي هنبدأ من البداية التاريخية: إزاي الحركة ظهرت في أوروبا وأمريكا، وإيه اللي عملته الموجة الأولى."},{"i":"comp-13","s":28,"h":"6) ليه الدرس ده في كورس أدب مقارن؟","t":"recall","x":"عرف النسوية في سطرين، من غير ما تستخدم أي فهم غلط شائع. . حركة سياسية وثقافية واقتصادية هدفها حقوق متساوية وحماية قانونية للستات، وبتشمل مجموعة حركات وأيديولوجيات بتشترك في هدف تحقيق المساواة السياسية والاقتصادية والشخصية والاجتماعية بين الجنسين، بما فيها الفرص التعليمية والمهنية."},{"i":"comp-13","s":29,"h":"6) ليه الدرس ده في كورس أدب مقارن؟","t":"recall","x":"ليه بنقسم النسوية لموجات، وعلى أي أساس بتتعرف كل موجة؟ . لأن الفكر النسوي اتغير مع الوقت، ولكل مرحلة أهداف وأدوات مختلفة. والموجة بتتعرف بأهدافها وأدواتها أكتر من التواريخ: الأولى السياسة، والتانية الثقافة، والتالتة الأكاديميا، والرابعة الناشئة التكنولوجيا."},{"i":"comp-13","s":30,"h":"6) ليه الدرس ده في كورس أدب مقارن؟","t":"write","x":"اشرح في فقرة قصيرة ليه دراسة حركة زي النسوية تدخل في كورس أدب مقارن. . لأن الأدب مش بيوجد في فراغ: بيتقرأ في سياقه الاجتماعي والفكري. النقد النسوي أدى أدوات قراءة جديدة للنصوص، وبيسأل أسئلة عن صورة المرأة ودورها والعلاقات بين الجنسين جوه العمل. وكمان الأدب المقارن بيدرس علاقة الأدب بمجالات المعرفة التانية، والحركات الفكرية جزء من المجالات دي."},{"i":"comp-14","s":1,"h":"مقدمة","t":"learn","x":"الدرس اللي فات عرفنا النسوية كفكرة وموجات. النهاردة أول موجة، وإزاي الحركة بدأت في أوروبا وأمريكا. الموجة الأولى مركزها السياسة، وهدفها الأساسي كان حق التصويت."},{"i":"comp-14","s":3,"h":"1) البداية الأوروبية","t":"learn","x":"أفكار التنوير في القرن التمنتاشر عن حقوق الفرد والمساواة خلت ستات تسأل: ليه إحنا مالنا دور محدود؟ مفكرات زي ماري وولستونكرافت في إنجلترا، وأوليمب دي جوج في فرنسا، طالبوا بتعليم الستات ومشاركتهم السياسية."},{"i":"comp-14","s":4,"h":"1) البداية الأوروبية","t":"mc","x":"إيه اللي مهد للحركة في أوروبا في القرن التمنتاشر؟ ؟ أفكار التنوير عن حقوق الفرد والمساواة / قوانين منعت تعليم الستات / الحروب الأوروبية الطويلة / ظهور الطباعة بس . التنوير حط مبدأ الحقوق والمساواة، والستات سألوا ليه مش مطبق عليهن."},{"i":"comp-14","s":5,"h":"1) البداية الأوروبية","t":"learn","x":"والقرن التسعتاشر شاف نشاط منظم على مطالب محددة. حق التصويت، وحق الملكية. وأول مؤتمرات منظمة لحقوق الستات اتعملت في سينيكا فولز في نيويورك سنة 1848، وفي لندن سنة 1851."},{"i":"comp-14","s":6,"h":"1) البداية الأوروبية","t":"learn","x":"وبعدها ظهرت تنظيمات دولية، زي المجلس الدولي للستات اللي اتأسس سنة 1888، وهدفه يوحد الجهود بين البلاد."},{"i":"comp-14","s":8,"h":"2) البداية الأمريكية","t":"learn","x":"في أمريكا، أفكار الثورة الأمريكية عن الحرية والمساواة كان لها نفس الأثر. وكمان حركة إلغاء العبودية كان لها دور كبير، وستات زي سوجورنر تروث وهارييت توبمان بقوا أصوات قوية."},{"i":"comp-14","s":9,"h":"2) البداية الأمريكية","t":"mc","x":"إيه أهم وثيقة طلعت من مؤتمر سينيكا فولز 1848؟ ؟ إعلان المشاعر، وفيه المطالب بحقوق متساوية زي التصويت والملكية / إعلان استقلال أمريكا / قانون حق التصويت للجميع / دستور جديد للبلاد . الوثيقة اللي اتكتبت في المؤتمر هي إعلان المشاعر."},{"i":"comp-14","s":10,"h":"2) البداية الأمريكية","t":"learn","x":"وسينيكا فولز 1848 كانت نقطة التحول في أمريكا. المؤتمر طلع «إعلان المشاعر»، وفيه مظالم الستات ومطالبهن بحقوق متساوية، بما فيها التصويت والملكية."},{"i":"comp-14","s":11,"h":"2) البداية الأمريكية","t":"learn","x":"وبعدها الحركة اتوسعت: حقوق العمال، والفرص التعليمية، والحقوق الإنجابية. وستات سود زيه إيدا ويلز وماري تشيرش تيريل كانوا بيحاربوا العنصرية والتمييز الجنسي في نفس الوقت."},{"i":"comp-14","s":13,"h":"3) تشابه واختلاف","t":"learn","x":"المشترك بين أوروبا وأمريكا: نفس المبادئ الأساسية. المساواة، والعدالة، وحقوق الفرد للستات."},{"i":"comp-14","s":14,"h":"3) تشابه واختلاف","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ «الأنوثة الأبدية» فكرة بتؤكد إن الأنوثة تكوين اجتماعي. / النسوية الأوروبية والأمريكية كان بينهم تبادل أفكار واستراتيجيات، مش مسارين منفصلين. / أنهي جملة من دول غلط؟ / الموجة الأولى كانت نضيفة تماما من أي مواقف عنصرية. . التبادل عبر الأطلنطي جزء من تاريخ الحركة."},{"i":"comp-14","s":15,"h":"3) تشابه واختلاف","t":"learn","x":"والاختلاف في التركيز. النسوية الأوروبية ركزت أكتر على إصلاحات قانونية محددة. والأمريكية أخدت أجندة اجتماعية وثقافية أوسع."},{"i":"comp-14","s":16,"h":"3) تشابه واختلاف","t":"learn","x":"ومع الاختلاف، كان فيه تبادل حقيقي: أفكار واستراتيجيات عبرت الأطلنطي وأثرت في الاتجاهين."},{"i":"comp-14","s":18,"h":"4) الموجة الأولى بشكل محدد","t":"learn","x":"الموجة الأولى هي حركات الستات في القرن التسعتاشر وأول القرن العشرين. ظهرت في بيئة التصنيع الحضري والسياسات الليبرالية والاشتراكية، وهدفها فتح فرص للستات، مع تركيز على حق التصويت."},{"i":"comp-14","s":19,"h":"4) الموجة الأولى بشكل محدد","t":"mc","x":"إيه اللي تركيز الموجة الأولى اتحول ليه مع نهاية القرن التسعتاشر؟ ؟ من الحقوق القانونية والملكية للسلطة السياسية وحق التصويت / من حق التصويت للعمل الأكاديمي / من الحقوق الإنجابية للسياسة الخارجية / من التعليم للفن . البداية قانونية، والنهاية سياسية: التصويت."},{"i":"comp-14","s":20,"h":"4) الموجة الأولى بشكل محدد","t":"learn","x":"في البداية كانت المطالب قانونية: عقود وملكية متساوية. ومعارضة إن الزوج يملك زوجته وأولادها كأنهم مال. ومع نهاية القرن، النشاط اتحول للسلطة السياسية وحق التصويت."},{"i":"comp-14","s":21,"h":"4) الموجة الأولى بشكل محدد","t":"learn","x":"وفي أمريكا، الكفاح ده انتهى بتعديل دستوري سنة 1920 كفل للستات حق التصويت."},{"i":"comp-14","s":22,"h":"4) الموجة الأولى بشكل محدد","t":"mc","x":"إيه اللي كفل حق التصويت للستات في أمريكا؟ ؟ تعديل دستوري سنة 1920 / إعلان المشاعر سنة 1848 / مؤتمر لندن سنة 1851 / قرار المجلس الدولي سنة 1888 . التحقق النهائي كان بتعديل دستوري سنة 1920."},{"i":"comp-14","s":24,"h":"5) نقطة لازم تتقال","t":"learn","x":"تاريخ الموجة الأولى فيه صفحة مش نضيفة، ولازم تتقال بصراحة. جزء من حركة حق التصويت في أمريكا ارتبط بمواقف عنصرية: تنظيم انفصل سنة 1890، وخوف من إن رجالة سود ياخدوا الحق قبل الستات البيض."},{"i":"comp-14","s":25,"h":"5) نقطة لازم تتقال","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ الموجة الأولى كانت نضيفة تماما من أي مواقف عنصرية. / «الأنوثة الأبدية» عند بوفوار هي فكرة إن فيه طبيعة أنثوية ثابتة بتتبرر بيها أدوار محددة. / التعريف نفسه كان محل خلاف، والنقد ده فتح باب الموجة الرابعة. / أنهي جملة من دول صحيحة؟ . فيه مواقف عنصرية موثقة جوه جزء من حركة حق التصويت، والدرس بيسجلها كنقد."},{"i":"comp-14","s":26,"h":"5) نقطة لازم تتقال","t":"learn","x":"والدرس بيسجل ده كنقد، مش كتفصيلة. وعشان كده باحثات سود زيه بيل هوكس قالوا إن الحركة عدت على الفروق العرقية والطبقية."},{"i":"comp-14","s":28,"h":"6) خلاصة","t":"learn","x":"الموجة الأولى بنت الأساس التنظيمي والقانوني. مؤتمرات، ووثائق مطالب، وتنظيمات دولية، وحق تصويت في النهاية. لكنها سيبت أسئلة كبيرة: الثقافة، والجسد، والبيت."},{"i":"comp-14","s":29,"h":"6) خلاصة","t":"learn","x":"الدرس الجاي: الموجة التانية، اللي قالت إن «الشخصي سياسي»."},{"i":"comp-14","s":30,"h":"6) خلاصة","t":"recall","x":"إيه الفرق في التركيز بين النسوية الأوروبية والأمريكية في بداياتها؟ . الاثنين اتشاركوا في مبادئ المساواة والعدالة وحقوق الفرد. الأوروبية ركزت أكتر على إصلاحات قانونية محددة، والأمريكية أخدت أجندة اجتماعية وثقافية أوسع، وكان فيه تبادل بينهم."},{"i":"comp-14","s":31,"h":"6) خلاصة","t":"recall","x":"إيه مطالب الموجة الأولى في بدايتها وإيه اللي جاء في الآخر؟ . البداية: عقود وملكية متساوية، ومعارضة ملكية الزوج لزوجته وأولاده. والنهاية: السلطة السياسية وحق التصويت، اللي اتحقق في أمريكا بتعديل دستوري سنة 1920."},{"i":"comp-14","s":32,"h":"6) خلاصة","t":"write","x":"اكتب فقرة عن ليه مؤتمر سينيكا فولز 1848 مهم. . لأنه أول مؤتمر منظم لحقوق الستات في أمريكا، وجمع رجالة وستات على قضية المساواة، وطلع منه إعلان المشاعر اللي حط المظالم والمطالب في وثيقة واحدة، زي حق التصويت والملكية. والوثيقة دي بقت نموذج لحركات بعد كده، فالمؤتمر نقطة تحول مش مجرد اجتماع."},{"i":"comp-15","s":1,"h":"مقدمة","t":"learn","x":"الموجة الأولى طلبت حق التصويت. الموجة التانية سألت سؤال أكبر: إيه اللي بيحصل جوه البيت؟ مركزها الثقافة، ومقولتها الشهيرة: «الشخصي سياسي»."},{"i":"comp-15","s":3,"h":"1) امتى وإزاي؟","t":"learn","x":"الموجة التانية بترتبط بحركة تحرير الستات من الستينات، وامتدت في الغالب من الستينات للتسعينات. وظهرت في سياق حركات ضد الحرب والحقوق المدنية، وصعود اليسار الجديد، ووعي متزايد لجماعات أقليات في العالم."},{"i":"comp-15","s":4,"h":"1) امتى وإزاي؟","t":"learn","x":"والفرق عن الأولى بيتلخص بسهولة. الموجة الأولى ركزت على حقوق زي التصويت، والتانية على قضايا مساواة تانية، أهمها إنهاء التمييز."},{"i":"comp-15","s":5,"h":"1) امتى وإزاي؟","t":"mc","x":"إيه الفرق الأساسي بين الموجة الأولى والتانية زي ما بيتلخص؟ ؟ الأولى على حقوق زي التصويت، والتانية على قضايا زي إنهاء التمييز / الأولى على الثقافة، والتانية على السياسة / الأولى في أمريكا بس، والتانية في أوروبا بس / الأولى على الأكاديميا، والتانية على التصويت . التصويت مركز الأولى، والتمييز مركز التانية."},{"i":"comp-15","s":7,"h":"2) الشخصي سياسي","t":"learn","x":"المقولة اللي بقت شعار الموجة: «الشخصي سياسي». معناها إن حياة الست الشخصية مش منفصلة عن السياسة: البيت، والجسد، والشغل، كلهم متأثرين بعلاقات قوة."},{"i":"comp-15","s":8,"h":"2) الشخصي سياسي","t":"learn","x":"والفكرة إن الستات يفهموا جوانب من حياتهم الشخصية كأنها مسيسة، وبانعكاس لبنى سلطة ذكورية."},{"i":"comp-15","s":9,"h":"2) الشخصي سياسي","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ شعار «الشخصي سياسي» معناه إن حياة الست الشخصية منفصلة عن السياسة. / العنف في الرواية بيأثر على إحساس الشخصية بنفسها، مش على جسدها بس. / «الأنوثة الأبدية» عند بوفوار هي فكرة إن فيه طبيعة أنثوية ثابتة بتتبرر بيها أدوار محددة. / من الانتقادات الموجهة لكتاب «اللغز الأنثوي» إنه ركز على تجربة ستات الطبقة الوسطى البيض. . الشعار بيقول العكس: الشخصي متشابك مع السياسة وعلاقات القوة."},{"i":"comp-15","s":11,"h":"3) البداية: مسابقة ملكة الجمال","t":"learn","x":"الموجة دي بدأت باحتجاجات على مسابقة ملكة الجمال في أتلانتيك سيتي في 1968 و1969. الاحتجاجات شافت المسابقة عرض للجسد بيحول الست لبضاعة منظر، وبيخدم نظام بيحبسها في البيت أو في شغل بسيط بأجر قليل."},{"i":"comp-15","s":12,"h":"3) البداية: مسابقة ملكة الجمال","t":"learn","x":"ومجموعة نسوية راديكالية عملت مسابقة مضادة. توجت خروف «ملكة جمال»، ورمت في الزبالة حاجات اعتبروها أدوات قهر: حمالات، وكورسيه، وكعب عالي، ومكياج، ورموش مستعارة."},{"i":"comp-15","s":13,"h":"3) البداية: مسابقة ملكة الجمال","t":"mc","x":"إيه اللي الاحتجاجات على مسابقة ملكة الجمال اعترضت عليه؟ ؟ إن المسابقة بتحول الست لبضاعة منظر وتخدم نظام بيحدد دورها / إن المسابقة كانت غالية التذاكر / إن المسابقة مش بتدي جوائز / إن المسابقة كانت في أوروبا . الاعتراض كان على تصوير الست كجسد، وربط ده ببنية القهر."},{"i":"comp-15","s":15,"h":"4) التنظيم والأدوات","t":"learn","x":"لأن الموجة كانت وسط حركات تانية كتير، كانت بتتهمش وتتحسب أقل إلحاحا. فردت بتكوين تنظيمات للستات بس، زي المنظمة الوطنية للستات، ومجموعات «رفع الوعي» اللي بتجمع ستات يتكلموا عن تجاربهم."},{"i":"comp-15","s":16,"h":"4) التنظيم والأدوات","t":"learn","x":"وظهرت منشورات كتير، وكلها كانت بتقول نفس الحاجة: للستات حق إنهم يكون لهم مكان وصوت."},{"i":"comp-15","s":18,"h":"5) النظرية","t":"learn","x":"الموجة التانية كانت نظرية أكتر من الأولى. مبنية على مزج بين الماركسية الجديدة والتحليل النفسي، وربطت قهر الستات بنقد أوسع للنظام الأبوي والرأسمالية."},{"i":"comp-15","s":19,"h":"5) النظرية","t":"learn","x":"وأهم تمييز نظري جابته: الفرق بين الجنس والجندر. الجنس بيولوجي، والجندر بناء اجتماعي بيتغير من ثقافة لثقافة ومن وقت لوقت."},{"i":"comp-15","s":20,"h":"5) النظرية","t":"mc","x":"إيه التمييز النظري المهم اللي جابته الموجة التانية؟ ؟ الفرق بين الجنس البيولوجي والجندر كبناء اجتماعي / الفرق بين الشعر والنثر / الفرق بين الشرق والغرب / الفرق بين القانون والأخلاق . التمييز بين الجنس والجندر هو أهم أداة نظرية جابتها الموجة."},{"i":"comp-15","s":21,"h":"5) النظرية","t":"learn","x":"والموجة دي جذبت ستات من أعراق مختلفة ومن بلاد نامية، وشعارها بقى إن كفاح الستات جزء من كفاح الطبقة."},{"i":"comp-15","s":23,"h":"6) كتابين غيروا الموجة","t":"learn","x":"كتابين أساسيين أثروا في الموجة. «الجنس التاني» لسيمون دي بوفوار، و«اللغز الأنثوي» لبيتي فريدان سنة 1963."},{"i":"comp-15","s":24,"h":"6) كتابين غيروا الموجة","t":"mc","x":"إيه اللي الموجة التانية حققته من نتائج ملموسة؟ ؟ فرص شغل وقوانين ضد التمييز وفرص تعليم ووعي عام ومجال أكاديمي / حق التصويت بس / منعت الستات من الشغل / ألغت كل قوانين العمل . النتائج كانت في الشغل والتعليم والقانون والوعي والمجال الأكاديمي."},{"i":"comp-15","s":25,"h":"6) كتابين غيروا الموجة","t":"learn","x":"فريدان هاجمت فكرة إن الست ملهاش تحقيق إلا في تربية الأولاد والبيت. وقالت إن ده نظام معتقدات زائف بيخلي الست تدور على هويتها في جوزها وأولادها، فتفقد نفسها."},{"i":"comp-15","s":27,"h":"7) نتائج ونقد","t":"learn","x":"الموجة التانية حققت حاجات ملموسة. فرص شغل أكتر، وقوانين ضد التمييز، وفرص تعليم، وحقوق إنجابية، وزيادة وعي عام بحقوق الستات، ومجال أكاديمي كامل."},{"i":"comp-15","s":28,"h":"7) نتائج ونقد","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ الموجة التالتة اتفق كل أصحابها على تعريف واحد لمعنى «الست». / «الأنوثة الأبدية» فكرة بتؤكد إن الأنوثة تكوين اجتماعي. / من الانتقادات الموجهة لكتاب «اللغز الأنثوي» إنه ركز على تجربة ستات الطبقة الوسطى البيض. / أنهي جملة من دول غلط؟ . ده نقد موثق للكتاب، رغم أهميته."},{"i":"comp-15","s":29,"h":"7) نتائج ونقد","t":"learn","x":"وفي نفس الوقت اتعرضت لنقد مهم. فريدان نفسها اتقال عليها إنها بتتكلم عن ستات من الطبقة الوسطى البيض، وإنها صورت الست كضحية سلبية من غير قدرة على التصرف."},{"i":"comp-15","s":30,"h":"7) نتائج ونقد","t":"learn","x":"وبيل هوكس انتقدت الحركة كلها إنها عدت على الفروق العرقية والطبقية، وإنها مفيهاش أصوات كفاية للأقليات."},{"i":"comp-15","s":32,"h":"8) خلاصة","t":"learn","x":"الموجة التانية وسعت الحركة من القانون للثقافة. من حق التصويت للبيت والجسد واللغة. وخلت السؤال عن «التمييز» سؤال مركزي، وسابت للجيل اللي بعده سؤال الهوية والاختلاف."},{"i":"comp-15","s":33,"h":"8) خلاصة","t":"learn","x":"الدرس الجاي هنتكلم بالتفصيل عن كتاب واحد غير كل حاجة: «الجنس التاني»."},{"i":"comp-15","s":34,"h":"8) خلاصة","t":"recall","x":"اشرح شعار «الشخصي سياسي» بمثال. . المعنى إن اللي بيحصل جوه البيت مش مسألة خاصة، ده انعكاس لعلاقات قوة. مثال: توزيع شغل البيت والرعاية على الست وحدها مش اختيار شخصي، ده نتيجة نظام بيحدد دورها، فالسؤال عنه سؤال سياسي."},{"i":"comp-15","s":35,"h":"8) خلاصة","t":"recall","x":"إيه أهم تمييز نظري جابته الموجة التانية، وليه مهم؟ . الفرق بين الجنس البيولوجي والجندر كبناء اجتماعي. وأهميته إنه فصل بين الجسم والتصرفات المتوقعة، فبقى ممكن نقد الأدوار الاجتماعية على إنها مكتسبة مش طبيعية."},{"i":"comp-15","s":36,"h":"8) خلاصة","t":"write","x":"اكتب فقرة تقارن فيها الموجة الأولى والتانية في الهدف والأداة. . الموجة الأولى هدفها حق التصويت والحقوق القانونية، وأداتها المؤتمرات والوثائق والضغط السياسي. الموجة التانية هدفها إنهاء التمييز في الثقافة والمجتمع، وأداتها الاحتجاجات الرمزية ومجموعات رفع الوعي والتنظيمات النسائية والتنظير. الأولى غيرت القانون، والتانية غيرت طريقة الكلام عن البيت والجسد."},{"i":"comp-16","s":1,"h":"مقدمة","t":"learn","x":"الموجة التانية قالت «الشخصي سياسي». الموجة التالتة سألت: شخصي مين؟ كل الستات زي بعض؟ مركزها الأكاديميا، وفكرتها الأساسية: التقاطع."},{"i":"comp-16","s":3,"h":"1) امتى وليه؟","t":"learn","x":"الموجة التالتة بدأت في منتصف التسعينات، وتغذت على الفكر ما بعد الاستعماري وما بعد الحداثي. وجهت كرد على إخفاقات الموجة التانية في التعامل مع التداخل بين أنواع القهر، وكمان كرد على الهجوم المضاد على مكاسب الموجة التانية."},{"i":"comp-16","s":4,"h":"1) امتى وليه؟","t":"learn","x":"وقادتها أجيال اتولدت في الستينات والسبعينات في العالم المتقدم. نشأت في بيئة مشبعة بالإعلام ومتنوعة ثقافيا واقتصاديا، وده شكل أسئلتها."},{"i":"comp-16","s":5,"h":"1) امتى وليه؟","t":"mc","x":"إيه اللي الموجة التالتة كانت رد عليه؟ ؟ إخفاقات الموجة التانية في التداخل بين أنواع القهر، والهجوم المضاد على مكاسبها / نجاح الموجة الأولى في تحقيق حق التصويت / اختفاء الحركة النسوية تماما / قوانين منعت تعليم الستات . الرد كان على الإخفاقات وعلى الهجوم المضاد في نفس الوقت."},{"i":"comp-16","s":7,"h":"2) التقاطع","t":"learn","x":"أهم مفهوم جابته الموجة التالتة: التقاطع. المصطلح اتقدم سنة 1989 على يد عالمة النظرية النقدية للعرق كيمبرلي كرينشو."},{"i":"comp-16","s":8,"h":"2) التقاطع","t":"learn","x":"ويعني إن هوية الست فيها جوانب كتير بتتداخل، وبتضاعف القهر. مش ممكن نفصل نوع قهر عن نوع تاني: الست بتعيشهم مع بعض، مش واحدة واحدة."},{"i":"comp-16","s":9,"h":"2) التقاطع","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ «الأنوثة الأبدية» فكرة بتؤكد إن الأنوثة تكوين اجتماعي. / الموجة التالتة انتقدت الموجة التانية لأنها عممت تجربة ستات الطبقة الوسطى البيض. / الموجة التالتة اتفق كل أصحابها على تعريف واحد لمعنى «الست». / كل اللي في الموجة الرابعة مرتاحين لكلمة «نسوية». . ده نقد مركزي في الموجة التالتة."},{"i":"comp-16","s":10,"h":"2) التقاطع","t":"learn","x":"مثال يوضح الفكرة. فجوة الأجور بتحصل لكل الستات، لكن فيه ستات بتتأثر أكتر بسبب العرق. فالتحليل لازم يشوف الاتنين مع بعض."},{"i":"comp-16","s":12,"h":"3) نقد التعميم","t":"learn","x":"الموجة التالتة انتقدت الموجة التانية على تعريفاتها الجوهرية للأنوثة. وقالت إنها بتبالغ في تجربة ستات الطبقة الوسطى العليا البيض، وتعممها على الكل."},{"i":"comp-16","s":13,"h":"3) نقد التعميم","t":"mc","x":"يعني إيه التقاطع؟ ؟ إن جوانب الهوية بتتداخل وبتضاعف القهر، فمش ممكن نفصل نوع قهر عن نوع تاني / إن كل الستات بتتعرض لنفس القهر بالظبط / إن القهر بيحصل في وقت واحد بس / إن الهوية مسألة شخصية مالهاش علاقة بالمجتمع . الفكرة إن أنواع القهر بتتراكب، مش بتتضاف لوحدها."},{"i":"comp-16","s":14,"h":"3) نقد التعميم","t":"learn","x":"وكمان فككت مفاهيم كانت بتتحسب ثابتة. «الأنوثة العامة»، والجسد، والجندر، والجنسانية، وفكرة إن العلاقة بين رجل وست هي الشكل الطبيعي الوحيد."},{"i":"comp-16","s":16,"h":"4) إعادة تعريف الصورة","t":"learn","x":"الموجة التالتة أعادت استخدام صور كانت الموجات السابقة شايفاها قهر. المكياج، والكعب العالي، والملابس الجريئة. الشعار: ممكن يكون عندك حمالة مرفوعة وعقل في نفس الوقت."},{"i":"comp-16","s":17,"h":"4) إعادة تعريف الصورة","t":"mc","x":"إزاي الموجة التالتة تعاملت مع المكياج والكعب العالي؟ ؟ أعادت استخدامهم على إنهم اختيار حر، مش بالضرورة قهر / منعتهم تماما زي الموجة التانية / اعتبرتهم شرط للنجاح / قالت إنهم مالهومش أي معنى . إعادة الاستخدام كتعبير عن الذات هو موقف الموجة التالتة."},{"i":"comp-16","s":18,"h":"4) إعادة تعريف الصورة","t":"learn","x":"وسمت نفسها «grrrl feminism». يعني الست تحدد جمالها بنفسها كذات، مش كموضوع لرغبة حد تاني. واستخدمت أسلوب المحاكاة الساخرة في إعادة استخدام كلمات كانت بتتقال كإهانة."},{"i":"comp-16","s":19,"h":"4) إعادة تعريف الصورة","t":"learn","x":"وفيه أيقونات ثقافية ظهرت قوية ومسيطرة مش خجولة وسلبية، وده كان متوافق مع احتفاء الموجة بالغموض ورفض تقسيم العالم ل«إحنا وهما»."},{"i":"comp-16","s":21,"h":"5) نقطة خلاف","t":"learn","x":"وفيه نقطة خلاف مهمة اتولدت من الموجة التالتة نفسها. أعمال زي «مونولوجات المهبل» فتحت كلام عن الجسد في الثقافة العامة، لكنها ربطت الأنوثة بالجسد بشكل ممكن يستبعد ستات تانية."},{"i":"comp-16","s":22,"h":"5) نقطة خلاف","t":"learn","x":"والنقد ده، إن تعريف «الست» بشكل بيستبعد ناس، هو اللي فتح الطريق لموجة رابعة بتسأل نفس السؤال من جديد."},{"i":"comp-16","s":23,"h":"5) نقطة خلاف","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ العنف في الرواية بيأثر على إحساس الشخصية بنفسها، مش على جسدها بس. / الموجة الرابعة بتستخدم أدوات التالتة زي التقاطع، بس بتغير الوسيلة للإنترنت والخطاب العام. / أنهي جملة من دول صحيحة؟ / الموجة التالتة اتفق كل أصحابها على تعريف واحد لمعنى «الست». . التعريف نفسه كان محل خلاف، والنقد ده فتح باب الموجة الرابعة."},{"i":"comp-16","s":25,"h":"6) خلاصة","t":"learn","x":"الموجة التالتة غيرت السؤال من «الستات» ل«أنهي ستات». وأدت أدوات زي التقاطع، ونقد التعميم، وإعادة تعريف الصورة. ومكاسبها الأساسية أكاديمية: مجالات دراسات النوع والمرأة بقت مؤسسة في الجامعات."},{"i":"comp-16","s":26,"h":"6) خلاصة","t":"learn","x":"وفيه باحثين شايفين إن الموجات مش منفصلة، لكن بتتعايش: كل موجة بتبني على اللي قبلها وبتعالج حدوده."},{"i":"comp-16","s":27,"h":"6) خلاصة","t":"mc","x":"إيه رأي الباحثين في علاقة الموجات ببعض؟ ؟ بتتعايش: كل موجة بتبني على اللي قبلها وبتعالج حدوده / كل موجة بتلغي اللي قبلها تماما / الموجات تلاتة بالظبط ومفيش رابعة / الموجات حصلت في نفس السنة . التعايش والبناء على السابق هو التصور الأقرب."},{"i":"comp-16","s":28,"h":"6) خلاصة","t":"learn","x":"الدرس الجاي: الموجة الرابعة، اللي مركزها التكنولوجيا."},{"i":"comp-16","s":29,"h":"6) خلاصة","t":"recall","x":"عرف التقاطع، واشرح ليه بيعتبر أهم أداة في الموجة التالتة. . التقاطع إطار بيشوف كل جوانب الهوية اللي بتتداخل وبتضاعف القهر، فمش ممكن نفصل نوع قهر عن نوع تاني. وأهميته إنه خلى التحليل يشوف الفرق بين تجارب الستات على أساس العرق والطبقة، ونقد تعميم الموجة التانية."},{"i":"comp-16","s":30,"h":"6) خلاصة","t":"recall","x":"إيه اللي الموجة التالتة أخذته على الموجة التانية؟ . تعريفاتها الجوهرية للأنوثة اللي بتبالغ في تجربة ستات الطبقة الوسطى العليا البيض، وتعميمها على كل الستات، وإغفال التداخل بين العرق والطبقة والجندر."},{"i":"comp-16","s":31,"h":"6) خلاصة","t":"write","x":"اشرح بمثال إزاي التقاطع بيغير تحليل ظاهرة زي فجوة الأجور. . فجوة الأجور ظاهرة عامة بين الرجالة والستات، لكن التحليل بالتقاطع بيبين إنها مش متساوية: ست من عرق أو طبقة معينة ممكن تواجه فجوة أكبر لتراكب التمييز الجنسي مع التمييز العرقي أو الطبقي. فالتحليل بيسأل: مين اللي بيتأثر أكتر، وليه، وإيه اللي بيتداخل مع إيه. ومن غير التقاطع، الحل هيكون واحد لكل الستات، ومش هيوصل لكل واحدة."},{"i":"comp-17","s":1,"h":"مقدمة","t":"learn","x":"الموجة التالتة دخلت الأكاديميا. الموجة الرابعة طلعت منها تاني للشارع والإنترنت. مركزها التكنولوجيا، ولسه مش متفق عليها زي التلاتة اللي قبلها."},{"i":"comp-17","s":3,"h":"1) موجة ولا امتداد؟","t":"learn","x":"الموجة الرابعة مش بتتصنف دايما كموجة منفصلة، لأن بينها وبين التالتة تشابه كبير. بس فيه فرق واضح في الأدوات: التالتة اشتغلت بالتنظير الأكاديمي، والرابعة بتشتغل بالإعلام والمنصات."},{"i":"comp-17","s":4,"h":"1) موجة ولا امتداد؟","t":"learn","x":"والموجة الرابعة اتبنت على معارضة حاجات محددة. التمييز الجنسي. العنف ضد الستات، والاعتداء الجنسي، وثقافة الاغتصاب. التنمر على الشكل والجسم. التحرش في مكان الشغل."},{"i":"comp-17","s":5,"h":"1) موجة ولا امتداد؟","t":"mc","x":"إيه اللي المواضيع اللي المواجة الرابعة اتبنت على معارضتها؟ ؟ العنف والاعتداء الجنسي والتنمر على الجسم والتحرش في الشغل / حق التصويت والملكية / التنظير الأكاديمي بس / قوانين الضرائب . الرابعة بدأت من قضايا العنف والجسد والشغل."},{"i":"comp-17","s":7,"h":"2) البداية والأداة","t":"learn","x":"البداية بترتبط بمشروع «Everyday Sexism» اللي بدأته لورا بيتس سنة 2012. المشروع كان بيجمع أمثلة حقيقية للتمييز الجنسي من كل حتة في العالم، وخلى التجارب الفردية مادة عامة."},{"i":"comp-17","s":8,"h":"2) البداية والأداة","t":"learn","x":"والفرق الأساسي عن الموجات اللي قبلها: الأولوية للخطاب العام. الموجة دي بتعمل نقد نسوي في الفضاء العام وعلى السوشيال ميديا، مش في المجلات الأكاديمية بس."},{"i":"comp-17","s":9,"h":"2) البداية والأداة","t":"learn","x":"وطلع منها شكل جديد من الاحتجاج: «ثقافة المساءلة». يعني الناس بتسأل وتفضح علني، والهاشتاج بقى أداة تنظيم، زي حملة #MeToo اللي نشرت الوعي بقضايا التحرش والاعتداء."},{"i":"comp-17","s":10,"h":"2) البداية والأداة","t":"mc","x":"إيه أبرز أداة بتميز الموجة الرابعة؟ ؟ الإنترنت والسوشيال ميديا والهاشتاج / المؤتمرات الرسمية والوثائق / مجلات البحث الأكاديمي بس / الخطب في البرلمانات بس . المنصات الرقمية هي الأداة المميزة للموجة الرابعة."},{"i":"comp-17","s":12,"h":"3) إيه اللي رجع للنور؟","t":"learn","x":"مع الموجة الرابعة، feminism رجع للخطاب العام. قضايا كانت مركزية من أول الحركة بقت في الصفحات الأولى ومناقشات السياسيين: الاعتداء الجنسي، والعنف، والأجر غير المتساوي، والتنمر على الشكل، وضغط الجسم المثالي."},{"i":"comp-17","s":13,"h":"3) إيه اللي رجع للنور؟","t":"learn","x":"وكمان ظهر إن مكاسب التمثيل في السياسة والأعمال لسه صغيرة، وده خلى السؤال عن السلطة والتمثيل يرجع تاني."},{"i":"comp-17","s":14,"h":"3) إيه اللي رجع للنور؟","t":"learn","x":"وحركات إيجابية الجسد والتوعية بالاعتداء الجنسي مثال على إن الموجة دي بتوصل للناس عن طريق ناس مش أكاديميين."},{"i":"comp-17","s":16,"h":"4) ليه ظهرت؟","t":"learn","x":"الموجة الرابعة ظهرت لأن جيل جديد شاف التالتة متفائلة زيادة أو مش شايفة حاجات. والجيل ده بيستخدم أدوات التالتة نفسها: التقاطع، والشمول، وقبول الجسد، ودور الإنترنت في كسر التسلسلات."},{"i":"comp-17","s":17,"h":"4) ليه ظهرت؟","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ «الأنوثة الأبدية» فكرة بتؤكد إن الأنوثة تكوين اجتماعي. / كل اللي في الموجة الرابعة مرتاحين لكلمة «نسوية». / أنهي جملة من دول غلط؟ / الموجة الرابعة بتستخدم أدوات التالتة زي التقاطع، بس بتغير الوسيلة للإنترنت والخطاب العام. . ده اللي بيميزها: نفس الأدوات النظرية، ووسيلة جديدة."},{"i":"comp-17","s":18,"h":"4) ليه ظهرت؟","t":"mc","x":"ليه الموجة الرابعة ظهرت زي ما الدرس شرح؟ ؟ لأن جيل جديد شاف التالتة متفائلة زيادة أو مش شايفة مشاكل حقيقية / لأن الموجة التالتة اختفت تماما / لأن الأكاديميا اتقفلت في وش الباحثين / لأن التصويت اتلغى . الشعور إن التالتة كانت متفائلة زيادة هو المحرك الأساسي."},{"i":"comp-17","s":19,"h":"4) ليه ظهرت؟","t":"learn","x":"ومفهومي الامتياز والتقاطع انتشروا أكتر بين النسويين الأصغر سنا. يعني التحليل بقى بيسأل: مين عنده امتياز، ومين بيتأثر أكتر، وإزاي القهر بيتداخل."},{"i":"comp-17","s":21,"h":"5) مشكلة الاسم","t":"learn","x":"فيه مفارقة في الموجة دي: جزء من ناسها مش مرتاح لكلمة «نسوية». لأن الكلمة عندها دلالات قديمة عن التطرف، ولأنها بتوحي بثنائية الجنس وبإنها «للستات بس»."},{"i":"comp-17","s":22,"h":"5) مشكلة الاسم","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ كل اللي في الموجة الرابعة مرتاحين لكلمة «نسوية». / التعريف نفسه كان محل خلاف، والنقد ده فتح باب الموجة الرابعة. / أنهي جملة من دول صحيحة؟ / القارئ اللي يعرف النص القديم بيقرأ طبقة زيادة، لكن النص بيشتغل من غير كده كمان. . جزء منهم مش مرتاح للكلمة بسبب دلالاتها القديمة، لكن الكلمة كسبت في النهاية."},{"i":"comp-17","s":23,"h":"5) مشكلة الاسم","t":"learn","x":"ومع كده الكلمة كسبت: الجيل الجديد شايف إن المجتمع بيتعامل مع الجنس كتصنيف، وإن محتاج كلمة قوية تواجه ده. فالكلمة بقت دعوة للمساواة بين الجنسين، مش للستات بس."},{"i":"comp-17","s":25,"h":"6) خلاصة","t":"learn","x":"الموجة الرابعة رجعت الحركة للشارع، وبأدوات جديدة. هاشتاج، ومساءلة علنية، وتقاطع، وتركيز على العنف والجسد والشغل. ولسه مش واضح شكلها النهائي."},{"i":"comp-17","s":26,"h":"6) خلاصة","t":"learn","x":"وفيه حاجة مهمة في تاريخ الحركة كلها: مفيش «نسوية واحدة»، فيه نسويات كتير، وخلافات وتوترات، وده مش ضعف، ده دليل إن الحركة عايشة."},{"i":"comp-17","s":27,"h":"6) خلاصة","t":"mc","x":"إيه معنى إن «مفيش نسوية واحدة»؟ ؟ فيه نسويات كتير وتوترات بينها، وده دليل إن الحركة عايشة / إن الحركة فشلت ومبقاش ليها وجود / إن كل النسويين متفقين على كل حاجة / إن الحركة بقت مدرسة واحدة بأدوات واحدة . تعدد النسويات والتوترات بينها علامة حياة، مش ضعف."},{"i":"comp-17","s":28,"h":"6) خلاصة","t":"learn","x":"الدرس الجاي: سيمون دي بوفوار، والكتاب اللي غير طريقة الكلام عن المرأة."},{"i":"comp-17","s":29,"h":"6) خلاصة","t":"recall","x":"إيه الفرق الأساسي بين الموجة التالتة والرابعة؟ . التالتة مركزها الأكاديميا والتنظير، والرابعة بترجع الحركة للخطاب العام والإنترنت والسوشيال ميديا. والرابعة بتبني على أدوات التالتة زي التقاطع، لكن وسيلتها المنصات والمساءلة العلنية والهاشتاج."},{"i":"comp-17","s":30,"h":"6) خلاصة","t":"recall","x":"ليه الموجة الرابعة ظهرت، زي ما الدرس شرح؟ . لأن جيل جديد شاف التالتة متفائلة زيادة أو مش شايفة مشاكل حقيقية، ولأن قضايا زي العنف والتحرش والأجر والتمثيل رجعت للواجهة، ولأن مفاهيم الامتياز والتقاطع انتشرت أكتر."},{"i":"comp-17","s":31,"h":"6) خلاصة","t":"write","x":"اكتب فقرة عن إزاي السوشيال ميديا غيرت شكل الحركة، وإيه مخاطر ده. . السوشيال ميديا خلت التجربة الفردية تتحول لقضية عامة بسرعة، والهاشتاج نظم ناس من بلاد مختلفة حوالين قضية واحدة من غير تنظيم مركزي. وده وسع الوصول وسرع التغيير في الكلام العام. لكن فيه مخاطر: المساءلة العلنية ممكن تتحول لحملات بدون تحقيق، والسرعة ممكن تسبق الدليل، والمنصة نفسها بتتحكم في مين يظهر ومين يتخفي. فالأداة قوية، بس محتاجة مسؤولية في الاستخدام."},{"i":"comp-18","s":1,"h":"مقدمة","t":"learn","x":"فيه كتب بتغير موضوع كامل. «الجنس التاني» واحد من الكتب دي. اتنشر سنة 1949، وبقى نص أساسي في تاريخ feminism، ومازال بيتقرأ لحد دلوقتي."},{"i":"comp-18","s":3,"h":"1) مين سيمون دي بوفوار؟","t":"learn","x":"اتولدت في 9 يناير 1908، وماتت في 14 أبريل 1986. عند وفاتها كانت متعرف عليها كشخصية أساسية في النضال لحقوق الستات، وكاتبة كبيرة، وأخدت جايزة أدبية فرنسية مهمة عن روايتها «المندارين» سنة 1954."},{"i":"comp-18","s":4,"h":"1) مين سيمون دي بوفوار؟","t":"learn","x":"وكانت كاتبة غزيرة: روايات، ومقالات فلسفية، ومسرحيات، ومذكرات، ويوميات سفر، ومقالات صحفية. وكانت شريكة لجان بول سارتر طول حياتها، ومحررة في مجلة فكرية مؤثرة."},{"i":"comp-18","s":5,"h":"1) مين سيمون دي بوفوار؟","t":"mc","x":"إيه اللي بوفوار كانت بتعمله غير الكتابة؟ ؟ كانت محررة في مجلة فكرية، وشريكة لسارتر / كانت سياسية في البرلمان / كانت بتشتغل في الترجمة بس / كانت مدرسة فلسفة . التحرير في مجلة فكرية جزء من موقعها في المشهد الفكري."},{"i":"comp-18","s":6,"h":"1) مين سيمون دي بوفوار؟","t":"learn","x":"نقطة دقيقة: في وقت وفاتها مكانتش بتتحسب «فيلسوفة» بمعناها الأكاديمي، لكن بعد كده اتعرفت كمنظرة أساسية في الفكر النسوي."},{"i":"comp-18","s":8,"h":"2) الكتاب: إيه اللي بيعمله؟","t":"learn","x":"«الجنس التاني» مقال راديكالي متعدد التخصصات عن المرأة. بيعمل حاجة محددة: بيفكك الأساطير الثقافية اللي بتبني «الأنوثة»، يعني بيوضح إنها مبنية مش طبيعية."},{"i":"comp-18","s":9,"h":"2) الكتاب: إيه اللي بيعمله؟","t":"learn","x":"وبيحلل حاجة أهم: موقع المرأة التاريخي. المرأة اتحددت ك«الآخر» و«الموضوع»، والرجل هو «الذات». يعني الرجل هو المعيار، والمرأة بتتعرف بالنسبة له."},{"i":"comp-18","s":10,"h":"2) الكتاب: إيه اللي بيعمله؟","t":"mc","x":"إيه اللي بوفوار قصده بإن المرأة «الآخر»؟ ؟ إن الرجل هو الذات والمعيار، والمرأة بتتعرف بالنسبة له / إن المرأة مختلفة بيولوجيا بس / إن المرأة أقوى من الرجل / إن المرأة مالهاش هوية خالص . فكرة الآخر: موقع ثانوي بيتحدد بالنسبة للذات/الرجل."},{"i":"comp-18","s":11,"h":"2) الكتاب: إيه اللي بيعمله؟","t":"learn","x":"وحللت كمان وزن القهر الاجتماعي والمادي اللي اتعرضت له الستات. يعني مش بس أفكار، كمان ظروف مادية واجتماعية بتحدد حياتهم."},{"i":"comp-18","s":13,"h":"3) الوجودية والجملة الشهيرة","t":"learn","x":"بوفوار كانت وجودية، وأخدت مبدأ سارتر: الوجود بيسبق الماهية. يعني الإنسان بيوجد الأول، وبعدين بيصنع نفسه بأفعاله، مش العكس."},{"i":"comp-18","s":14,"h":"3) الوجودية والجملة الشهيرة","t":"mc","x":"إيه معنى جملة «المرء ما بيتولدش امرأة، لكن بيبقى امرأة»؟ ؟ إن الأنوثة بتتحقق في المجتمع، مش حاجة بيولوجية بتتولد معاك / إن الستات بيتغيروا مع العمر بيولوجيا / إن الرجالة بيمروا بنفس التجربة / إن الأنوثة مسألة اختيار فردي بس . الجملة مبنية على الوجودية: الوجود قبل الماهية، فالتكوين اجتماعي."},{"i":"comp-18","s":15,"h":"3) الوجودية والجملة الشهيرة","t":"learn","x":"ومن هنا جت أشهر جملة في الكتاب. «المرء ما بيتولدش امرأة، لكن بيبقى امرأة». يعني الأنوثة مش حاجة بتتولد معاك، هي حاجة بتتحقق في المجتمع."},{"i":"comp-18","s":17,"h":"4) أسطورة «الأنوثة الأبدية»","t":"learn","x":"الكتاب كان نداء عاطفي وعلمي لإلغاء أسطورة «الأنوثة الأبدية». يعني فكرة إن فيه طبيعة أنثوية ثابتة وأبدية، بتتبرر بيها أدوار محددة للست."},{"i":"comp-18","s":18,"h":"4) أسطورة «الأنوثة الأبدية»","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ أنهي جملة من دول غلط؟ / «الأنوثة الأبدية» فكرة بتؤكد إن الأنوثة تكوين اجتماعي. / «الأنوثة الأبدية» عند بوفوار هي فكرة إن فيه طبيعة أنثوية ثابتة بتتبرر بيها أدوار محددة. / أنهي جملة من دول غلط؟ . ده تعريف الأسطورة اللي الكتاب بيطالب بإلغائها."},{"i":"comp-18","s":19,"h":"4) أسطورة «الأنوثة الأبدية»","t":"learn","x":"والكتاب كمان سجل إن حتى ماري وولستونكرافت، وهي من أوائل المدافعات عن حقوق الستات، كانت شايفة الرجل هو المثال اللي الست المفروض تقترب منه."},{"i":"comp-18","s":21,"h":"5) نقطة مهمة: الفاعلية","t":"learn","x":"وفي حاجة بتميز بوفوار عن نظريات أحدث. رغم تحليلها الاجتماعي القوي، فضلت مؤمنة بوجود فاعلية فردية وهوية ممكن يختارها الشخص، وده بيفرقها عن التصورات ما بعد الحداثية للجندر."},{"i":"comp-18","s":22,"h":"5) نقطة مهمة: الفاعلية","t":"mc","x":"إيه اللي بوفوار طالبت بإلغائه في الكتاب؟ ؟ أسطورة «الأنوثة الأبدية» اللي بتتبرر أدوار محددة للست / فكرة التعليم للستات / حق التصويت / الكتابة الأدبية . النداء الأساسي كان ضد أسطورة الطبيعة الأنثوية الثابتة."},{"i":"comp-18","s":23,"h":"5) نقطة مهمة: الفاعلية","t":"learn","x":"يعني عندها الاتنين: المجتمع بيشكل، والإنسان عنده قدرة يختار ويقاوم."},{"i":"comp-18","s":25,"h":"6) ليه الكتاب مهم للكورس","t":"learn","x":"الكتاب ده هو الجسر بين النظرية والقراءة. لأنه أدى أدوات: أسطورة الأنوثة، والمرأة كآخر، والتكوين الاجتماعي. والأدوات دي هي اللي بنقرأ بيها رواية زي «ألف شمس مشرقة» بعد كده."},{"i":"comp-18","s":26,"h":"6) ليه الكتاب مهم للكورس","t":"mc","x":"إيه اللي بيميز بوفوار عن التصورات ما بعد الحداثية للجندر؟ ؟ إنها فضلت مؤمنة بالفاعلية الفردية والهوية المختارة / إنها أنكرت أثر المجتمع تماما / إنها قالت إن الجندر مالهوش أي علاقة بالجسد / إنها رفضت فكرة القهر الاجتماعي . الإيمان بالفاعلية والاختيار هو نقطة الاختلاف."},{"i":"comp-18","s":27,"h":"6) ليه الكتاب مهم للكورس","t":"learn","x":"الدرس الجاي هنبدأ نطبق: قراءة نسوية للرواية، شخصيات وعلاقات وسلطة."},{"i":"comp-18","s":28,"h":"6) ليه الكتاب مهم للكورس","t":"recall","x":"اشرح فكرة «المرأة كآخر» بكلامك. . إن الرجل هو الذات والمعيار اللي بيتعرف بيه، والمرأة بتتعرف بالنسبة له كطرف تاني وموضوع. يعني موقعها مش مستقل، ده موقع ثانوي مبني على المقارنة بالرجل."},{"i":"comp-18","s":29,"h":"6) ليه الكتاب مهم للكورس","t":"recall","x":"إيه معنى «الأنوثة الأبدية»، وليه بوفوار طالبت بإلغائها؟ . إن فيه طبيعة أنثوية ثابتة وأبدية. وبوفوار طالبت بإلغائها لأنها بتستخدم لتبرير أدوار محددة للست، وبتخفي إن الأنوثة تكوين اجتماعي، والكتاب بيقول إن المرء بيبقى امرأة مش بيتولد امرأة."},{"i":"comp-18","s":30,"h":"6) ليه الكتاب مهم للكورس","t":"write","x":"اكتب فقرة تربط فيها بين الوجودية وفكرة «بتكوين» المرأة. . الوجودية بتقول إن الوجود بيسبق الماهية: الإنسان بيوجد الأول وبعدين بيصنع نفسه. وبوفوار طبقت ده على المرأة: مفيش «طبيعة أنثوية» جاهزة، فيه بنت بتتربى في مجتمع بيرسم لها دور، فبتتحقق ك«امرأة» بالتربية والظروف. ومن هنا جملتها الشهيرة، ومعاها إيمانها إن الست تقدر تختار وتقاوم، فالمسألة مش حتمية."},{"i":"comp-19","s":1,"h":"مقدمة","t":"learn","x":"من النظرية للتطبيق. الدرس ده بنقرأ رواية «ألف شمس مشرقة» بعين نسوية. مش بنحكي الحكاية وخلاص: بنسأل إزاي الرواية بتبني حياة ستين، وإيه اللي بتقوله عن السلطة والبيت."},{"i":"comp-19","s":3,"h":"1) البنية","t":"learn","x":"الرواية مقسمة لأربع أجزاء. الجزء الأول: مريم، بنت اتولدت في أفغانستان في الخمسينات. الجزء التاني: ليلى، اتولدت في كابول في آخر السبعينات."},{"i":"comp-19","s":4,"h":"1) البنية","t":"mc","x":"إزاي الرواية مبنية؟ ؟ أربع أجزاء: مريم، وبعدين ليلى، وبعدين تقاطعهما، وبعدين ليلى تاني / جزء واحد بس من منظور واحد / تلات أجزاء كلها عن الرجالة / أجزاء مش مترابطة ومفيش تقاطع . البنية بتقدم كل ست لوحدها، وبعدين تجمعهما."},{"i":"comp-19","s":5,"h":"1) البنية","t":"learn","x":"والجزء التالت هو اللي حياتهم بيتقاطعوا فيه. والجزء الرابع من منظور ليلى. والصراعات العالمية والإقليمية بتجيب فوضى ودمار لحياة الستين وللبلد نفسه."},{"i":"comp-19","s":7,"h":"2) مريم","t":"learn","x":"مريم بنت غير شرعية، وده بيحدد حياتها من أول يوم. عايشة مع أمها نانا في بيت صغير بعيد عن المدينة، وأبوها جليل رجل أعمال ناجح بيزورها مرة في الأسبوع."},{"i":"comp-19","s":8,"h":"2) مريم","t":"mc","x":"إيه اللي أدى لجواز مريم من رشيد؟ ؟ أمها انتحرت، ومرات أبوها رفضوها، فأجبروه يزوجها / هي اختارت رشيد بنفسها / رشيد كان قريب لأمها / أبوها زوجها عشان تعليمها . الرفض بعد موت الأم هو اللي سد الطريق."},{"i":"comp-19","s":9,"h":"2) مريم","t":"learn","x":"مريم كانت عايزة تعيش معاه ومع مراته وأولاده. وفي عيد ميلادها الخمستاشر طلبت منه ياخدها تشوف فيلم، ووعدها، وبعدين ماجاش."},{"i":"comp-19","s":10,"h":"2) مريم","t":"learn","x":"فمشت لحد بيته، وهو مافتحلهاش. باتت في الشارع، ولما رجعت البيت لقت أمها انتحرت. وبعد الجنازة، مرات أبوه رفضوها، فأجبروه يزوجها من رشيد، إسكافي أرمل في كابول."},{"i":"comp-19","s":11,"h":"2) مريم","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ ليلى وافقت تتجوز رشيد بعد ما اتقالها إن طارق مات، وهي كانت حامل. / أنهي جملة من دول غلط؟ / أنهي جملة من دول غلط؟ / «الأنوثة الأبدية» فكرة بتؤكد إن الأنوثة تكوين اجتماعي. . الخبر الكاذب كان المحرك، ومريم ورشيد كانوا اللي عالجوها."},{"i":"comp-19","s":13,"h":"3) ليلى","t":"learn","x":"ليلى بنت ذكية من أسرة محبة، عايشة في نفس الشارع. بس الحرب ضد السوفييت قلبت طفولتها، وأخوها الكبار راحوا الحرب واتقتلوا."},{"i":"comp-19","s":14,"h":"3) ليلى","t":"learn","x":"طارق كان صاحبها المقرب، وبقوا في حب. قبل ما يسافر لباكستان، حصل بينهم لقاء، وبعدها بأيام صاروخ ضرب بيت أهلها وقتلهم وجرحها."},{"i":"comp-19","s":15,"h":"3) ليلى","t":"learn","x":"ورشيد ومريم عالجوها لحد ما قامت. وبعدها جه راجل غريب وأبلغها إن طارق مات، وهي كانت حامل من طارق، فوافقت تتجوز رشيد."},{"i":"comp-19","s":16,"h":"3) ليلى","t":"mc","x":"إيه اللي بيميز الجزء الرابع من الرواية؟ ؟ إنه من منظور ليلى، بعد تقاطع حياتها مع مريم / إنه من منظور رشيد / إنه ملخص للأحداث من غير منظور / إنه عن طفولة مريم في هيرات . الجزء الرابع بيكمل من عين ليلى."},{"i":"comp-19","s":18,"h":"4) التقاطع","t":"learn","x":"في الأول، مريم كانت خايفة ومتضايقة من وجود ليلى. لكن بعد ما ليلى ولدت بنت اسمها عزيزة، الاتنين بقوا حلفاء ضد عنف رشيد ومناوراته."},{"i":"comp-19","s":19,"h":"4) التقاطع","t":"learn","x":"وبعد سنين، طارق رجع. والستين فهموا إن رشيد هو اللي دفع للراجل الغريب عشان يقول إن طارق مات، وده عشان ليلى متجريش."},{"i":"comp-19","s":20,"h":"4) التقاطع","t":"mc","x":"إيه اللي كشفته عودة طارق؟ ؟ إن رشيد دفع لحد عشان يبلغ ليلى بخبر موت كاذب / إن طارق كان متجوز واحدة تانية / إن ليلى كانت عايزة تسيب البيت من الأول / إن مريم كانت عارفة الحقيقة من البداية . العودة كشفت الكذبة اللي بنى عليها رشيد الجواز."},{"i":"comp-19","s":22,"h":"5) النهاية","t":"learn","x":"لما رشيد عرف إن طارق رجع، ضرب ليلى بوحشية. فمريم قتلته بجاروف، وسلمت نفسها للسلطات في اليوم التالي، عشان تفتح طريق لليلى وأولادها يلاقوا أمان بره."},{"i":"comp-19","s":23,"h":"5) النهاية","t":"learn","x":"وليلى سافرت مع طارق، واتجوزوا، وبنوا حياة. وبعد أحداث 2001 وتحسن الأوضاع في كابول، رجعت عشان تساعد في إعادة البناء، واشتغلت مدرسة، وقررت إنها لو جابت بنت هتسميها مريم."},{"i":"comp-19","s":24,"h":"5) النهاية","t":"mc","x":"إيه اللي مريم عملته في النهاية؟ ؟ قتلت رشيد وسلمت نفسها، عشان تفتح طريق لليلى / سابت البيت وسافرت لوحدها / اتجوزت راجل تاني / بلغت عن ليلى للسلطات . تضحية مريم هي اللي فتحت طريق النجاة لليلى."},{"i":"comp-19","s":26,"h":"6) ليه دي رواية تتحلل نسويا؟","t":"learn","x":"الرواية بتحط حياتين ستين في مركز الحكاية. وبتوري إزاي القرارات الكبيرة في البلد بتوصل للبيت: الحرب، والفقر، والقوانين، كلهم بيحددوا مصير الستين."},{"i":"comp-19","s":27,"h":"6) ليه دي رواية تتحلل نسويا؟","t":"learn","x":"وده بالظبط اللي بيتدرسه النقد النسوي: مش بس «الست حلوة ولا وحشة»، لكن إزاي السلطة بتشتغل جوه البيت، ومين بيدفع التمن."},{"i":"comp-19","s":28,"h":"6) ليه دي رواية تتحلل نسويا؟","t":"learn","x":"الدرس الجاي هنفكك العلاقات: نانا وجليل ورشيد، والتضامن بين الستين، والسؤال عن الصوت والسكوت."},{"i":"comp-19","s":29,"h":"6) ليه دي رواية تتحلل نسويا؟","t":"recall","x":"لخص بنية الرواية في سطرين. . أربع أجزاء: الأول عن مريم في الخمسينات، والتاني عن ليلى في آخر السبعينات، والتالت بيتقاطعوا فيه، والرابع من منظور ليلى. والصراعات العالمية والإقليمية بتأثر على حياتهم وعلى البلد."},{"i":"comp-19","s":30,"h":"6) ليه دي رواية تتحلل نسويا؟","t":"recall","x":"إزاي حياة مريم اتغيرت بعد عيد ميلادها الخمستاشر؟ . أبوها وعد ياخدها للسينما وماجاش، فمشت لبيته ومافتحلهاش، وباتت في الشارع، ورجعت لقت أمها انتحرت، وبعد الجنازة مرات أبوها رفضوها فزوجها رشيد في كابول."},{"i":"comp-19","s":31,"h":"6) ليه دي رواية تتحلل نسويا؟","t":"write","x":"اشرح إزاي الرواية بتربط بين السياسة والبيت، بمثال من الحكاية. . الرواية بتبين إن القرارات الكبيرة بتحصل جوه البيت. مثال: الحرب اللي قتلت أخوات ليلى وضربت بيت أهلها هي اللي رمت ليلى في طريق رشيد. والفقر والحرب هما اللي خلوا الجواز بالإجبار ممكن. فالبيت مش منفصل عن البلد، والست هي اللي بتدفع التمن الأول."},{"i":"comp-20","s":1,"h":"مقدمة","t":"learn","x":"الدرس اللي فات عرفنا الحكاية. النهاردة بنفكك العلاقات: مين عنده سلطة، ومين بيدفع التمن، وإزاي الصوت بيتحول لسكوت وبعدين لكلام. وده الشغل الحقيقي للنقد: مش إعادة سرد، لكن تحليل."},{"i":"comp-20","s":3,"h":"1) البنية كأداة","t":"learn","x":"الرواية بتحكى من منظورين: الجزء الأول من عين مريم، والتاني من عين ليلى. وفي الجزء التالت بيتقاطعوا ويتبادلوا، لحد ذروة التوتر. والجزء الرابع بيتحول لزمن الحاضر."},{"i":"comp-20","s":4,"h":"1) البنية كأداة","t":"mc","x":"إيه اللي بيتغير في الجزء الرابع على مستوى السرد؟ ؟ الزمن بيتحول للحاضر / المنظور بيتحول لرشيد / الرواية بترجع للوراء / مفيش تغيير في السرد . التحول للزمن الحاضر علامة أسلوبية في الجزء الرابع."},{"i":"comp-20","s":5,"h":"1) البنية كأداة","t":"learn","x":"والبنية دي بتسمح للرواية إنها تتابع تأثير تاريخ البلد على عشرات السنين، وتبني علاقات معقدة بين الشخصيات."},{"i":"comp-20","s":7,"h":"2) مريم: الشوق والخذلان","t":"learn","x":"مريم بنت غير شرعية، وأبوها غني وأمها فقيرة. حياتها الصعبة بره المدينة خلتها تشتهي الدفء اللي متخيلاه في بيت أبوها."},{"i":"comp-20","s":8,"h":"2) مريم: الشوق والخذلان","t":"learn","x":"وأبوها كان لطيف معاها، لكنه ماعملش أي محاولة يدخلها في أسرته الشرعية. وأمها مكانتش قادرة تسامحه لأنه حملها عار البنت غير الشرعية."},{"i":"comp-20","s":9,"h":"2) مريم: الشوق والخذلان","t":"learn","x":"ونقطة التحول في الحكاية: مريم رفضت رغبة أمها وجريت ورا أبوها. وهو تجاهلها، فأمها انتحرت، وسابتها في إيد أبوها، وهو رتب جوازها من رشيد، اللي بقى مصدر أغلب الصراع في الرواية."},{"i":"comp-20","s":10,"h":"2) مريم: الشوق والخذلان","t":"mc","x":"إيه اللي العنف الأول في الرواية عمله في مريم؟ ؟ خلاها تبدأ تصدق إنها مش مستحقة الحب / خلاها تسيب رشيد فورا / خلاها ترجع لأبوها / خلاها تسامح أمها . العنف مش بس ألم جسدي: غير تصورها عن نفسها."},{"i":"comp-20","s":12,"h":"3) العنف الداخلي","t":"learn","x":"بعد الجواز، رشيد جبر مريم تمضغ حصى عقاب على أرز مش مستوي. والعنف ده هو النقطة اللي مريم بدأت عندها تصدق إنها مش مستحقة إن حد يحبها."},{"i":"comp-20","s":14,"h":"4) ليلى: مسار متوازي","t":"learn","x":"مسار ليلى مبني بالتوازي ومعاكس لمسار مريم. ليلى بتدرس في كابول، وأهلها وأصحابها متوقعين منها تعمل حاجة كبيرة، مش بس تتجوز وتخلف."},{"i":"comp-20","s":15,"h":"4) ليلى: مسار متوازي","t":"learn","x":"ونقطة التحول عندها كمان فيها موت في العائلة. العنف المتزايد في البلد أدى لقتل أخواتها، وده فتح الصراع السياسي في الرواية على مصراعيه."},{"i":"comp-20","s":16,"h":"4) ليلى: مسار متوازي","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ أنهي جملة من دول غلط؟ / العنف في الرواية بيأثر على إحساس الشخصية بنفسها، مش على جسدها بس. / «الأنوثة الأبدية» فكرة بتؤكد إن الأنوثة تكوين اجتماعي. / أنهي جملة من دول غلط؟ . ده التحليل اللي الرواية بتبنيه من أول عقاب."},{"i":"comp-20","s":17,"h":"4) ليلى: مسار متوازي","t":"learn","x":"وكانت عايزة تعيش حياة سعيدة في بلدها، لكن العنف فضل يبعدها: خروجها من المدرسة، وسفر طارق، وبعدها قتل أهلها."},{"i":"comp-20","s":19,"h":"5) التضامن والفاعلية","t":"learn","x":"في الجزء التالت، رشيد هو اللي شال ليلى من تحت الأنقاض وعالجها. ولما ولدت عزيزة، اللي هي بنت طارق، بقى أقسى عليها لأنها بنت مش ولد."},{"i":"comp-20","s":20,"h":"5) التضامن والفاعلية","t":"learn","x":"والستين صلحوا علاقتهم بالاتحاد ضد رشيد، عشان يلاقوا فاعلية خاصة بيهم. وأوضح شكل للمقاومة كان محاولة الهروب بعزيزة لباكستان. لكن اتقبض عليهم ورجعوهم، فحبسهم ومنع عنهم حتى المية، وبعدها جاء حكم طالبان بقوانين صارمة زادت الوضع سوءا."},{"i":"comp-20","s":21,"h":"5) التضامن والفاعلية","t":"mc","x":"إيه اللي خلى رشيد أقسى على ليلى بعد ولادة عزيزة؟ ؟ إن المولودة بنت مش ولد / إن ليلى رفضت الطبخ / إن مريم سافرت / إن طارق رجع في الوقت ده . تفضيله للولد هو اللي زود قسوته."},{"i":"comp-20","s":23,"h":"6) الذروة والتضحية","t":"learn","x":"الذروة بتيجي بعد ما اتكشف إن طارق عايش. رشيد كان رتب إن حد يبلغ ليلى إن طارق مات عشان تبطل تفكر فيه، وبقى غاضب لما خطته انكشفت."},{"i":"comp-20","s":24,"h":"6) الذروة والتضحية","t":"learn","x":"رشيد ضرب الاتنين بوحشية، ولما حاول يخنق ليلى، مريم قتله. ولأول مرة في الحكاية، مريم أخدت قرار بحياتها بفاعلية. والتضحية دي خلت ليلى تهرب مع طارق، لكن التمن إن مريم هتتنفذ فيها العقوبة."},{"i":"comp-20","s":25,"h":"6) الذروة والتضحية","t":"learn","x":"والرواية بتقول حاجة مهمة: من خلال ليلى وعزيزة، مريم لقت الحب اللي اتحرمت منه وهي صغيرة، وتحملها الذنب كان طريقة تكمل بيها حكاية ليلى."},{"i":"comp-20","s":26,"h":"6) الذروة والتضحية","t":"mc","x":"إزاي مريم وليلى حسنوا علاقتهم؟ ؟ اتحدوا ضد رشيد عشان يلاقوا فاعلية خاصة بيهم / بس بالكلام الهادئ معاه / بإن كل واحدة سابت البيت / بإنهم سافروا مع بعض من الأول . الاتحاد ضد العنف هو اللي بنى علاقتهم من جديد."},{"i":"comp-20","s":28,"h":"7) النهاية والربط بالنظرية","t":"learn","x":"الجزء الرابع بيقفل الدايرة. ليلى عاشت حلمها مع طارق، والتمن كان كبير. ومع تحسن الأوضاع رجعت لكابول، واشتغلت مدرسة، وقررت تسمي بنتها مريم."},{"i":"comp-20","s":29,"h":"7) النهاية والربط بالنظرية","t":"mc","x":"إيه معنى تضحية مريم في التحليل؟ ؟ إنها أول مرة تاخد قرار بحياتها، والتضحية خلت حكاية ليلى تكمل / إنها هربت وخلت ليلى تواجه لوحدها / إنها كانت خطة من رشيد / إنها كانت بلا معنى في الرواية . التضحية بتجمع الفاعلية بالحب اللي اتأخر عليها."},{"i":"comp-20","s":30,"h":"7) النهاية والربط بالنظرية","t":"learn","x":"وهنا بيرجع بوفوار. الرواية بتحكي ستات اتحطوا في موقع «الآخر»، وبيحاولوا يبنوا ذاتهم في ظروف قاسية. وده بالظبط اللي النظرية بتسميه التكوين والفاعلية."},{"i":"comp-20","s":31,"h":"7) النهاية والربط بالنظرية","t":"learn","x":"ونقطة أمانة: التحليل النسوي للرواية ممكن يسأل كمان سؤال عن الرواية نفسها: مين اللي بيحكي حكاية الست الأفغانية، ولمين؟ السؤال ده مش تشكيك في الرواية، ده جزء من القراءة النقدية."},{"i":"comp-20","s":32,"h":"7) النهاية والربط بالنظرية","t":"recall","x":"إزاي العنف في الرواية بيشتغل على مستويين؟ . على مستوى الجسد: عقاب زي مضغ الحصى، والضرب، والحبس. وعلى مستوى الذات: مريم بدأت تصدق إنها مش مستحقة الحب، فالعنف بيدخل في تصور الشخصية عن نفسها، مش بيفضل ألم خارجي."},{"i":"comp-20","s":33,"h":"7) النهاية والربط بالنظرية","t":"recall","x":"إيه اللي بيجمع بين مسار مريم ومسار ليلى، وإيه اللي بيفرقهم؟ . اللي بيجمعهم: نقطة تحول فيها موت في العائلة، وضغط اجتماعي بيحدد مستقبلهم، وعنف في البيت. واللي بيفرقهم: مريم نشأت في عزلة وبدون تعليم، وليلى نشأت في مدينة وأسرة محبة وبتعليم وأحلام، لكن الحرب سدت الطريق."},{"i":"comp-20","s":34,"h":"7) النهاية والربط بالنظرية","t":"write","x":"اكتب فقرة تحلل فيها شخصية نانا من منظور نسوي. . نانا شخصية بيصعب الحكم عليها بسرعة. هي قاسية في كلامها، لكن قسوتها جاية من تجربة قهر: حملت من راجل غني، وحملها العار لوحدها، وعاشت معزولة. جملتها إن «صابع الرجل دايما بيلاقي ست» بتلخص تجربتها: إن الغلط بيروح على الست. من منظور نسوي، نانا مش «أم شريرة»، هي نتيجة نظام بيعاقب الست ويحمي الراجل، وقسوتها على بنتها شكل من نقل الألم اللي عاشته."},{"i":"comp-21","s":1,"h":"مقدمة","t":"learn","x":"الكورس ده بنى مصطلحاته طبقة فوق طبقة. الدرس ده بيجمعهم في مكان واحد، وكل مصطلح بموقعه في القصة. الهدف مش حفظ تعريفات، الهدف إنك تعرف تستخدم المصطلح في مكانه الصح."},{"i":"comp-21","s":3,"h":"1) مصطلحات المجال","t":"learn","x":"الأدب المقارن: دراسة الأدب خارج حدود بلد واحد، ودراسة علاقته بمجالات المعرفة التانية. التعريف العملي اللي بنى عليه الكورس جه من Henry Remak سنة 1961."},{"i":"comp-21","s":4,"h":"1) مصطلحات المجال","t":"learn","x":"الأدب العالمي: مش مجموع الآداب القومية، لكن انتشار الأعمال خارج بلدها وقراءتها كأدب. ودامروش حط شرطين: إن العمل يتقرأ كأدب، وإنه يتداول بره لغته وثقافته."},{"i":"comp-21","s":5,"h":"1) مصطلحات المجال","t":"mc","x":"إيه شرطا دامروش للأدب العالمي؟ ؟ إن العمل يتقرأ كأدب، وإنه يتداول بره لغته وثقافته / إن العمل يبقى مكتوب بالإنجليزية / إن العمل يبقى قديم / إن العمل يبقى مترجم من العربية . الشرطين: القراءة كأدب + التداول خارج اللغة والثقافة."},{"i":"comp-21","s":7,"h":"2) مصطلحات المدرسة الفرنسية","t":"learn","x":"الوضعية: المعرفة من الحقائق والظواهر وعلاقاتها. والتأثير: أثر نص في نص، ودراسته بتدور على الأصل والدليل."},{"i":"comp-21","s":8,"h":"2) مصطلحات المدرسة الفرنسية","t":"learn","x":"المصدر: النص اللي منه جه الأثر. والناقل: الوسيط اللي بينقل. والاستقبال: إزاي النص اتقرأ واتقبل في ثقافة جديدة، ودرجة تأثيره ومدته."},{"i":"comp-21","s":9,"h":"2) مصطلحات المدرسة الفرنسية","t":"learn","x":"وفان تيجيم قسم المجال سنة 1931 لتلاتة: أدب قومي، وأدب مقارن، وأدب عام."},{"i":"comp-21","s":10,"h":"2) مصطلحات المدرسة الفرنسية","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ أنهي جملة من دول غلط؟ / «الأنوثة الأبدية» فكرة بتؤكد إن الأنوثة تكوين اجتماعي. / أنهي جملة من دول غلط؟ / «الناقل» في المدرسة الفرنسية هو الوسيط اللي بينقل النص، زي الترجمة أو المجلة. . ده تعريفه في نموذج فان تيجيم."},{"i":"comp-21","s":12,"h":"3) مصطلحات المدرسة الأمريكية","t":"learn","x":"التناص: حوار النصوص، مش خط تأثير واحد. والنقد الجديد ركز على النص نفسه، والبنيوية على الأنماط، وما بعد البنيوية على تعدد المعنى ودور القارئ."},{"i":"comp-21","s":14,"h":"4) مصطلحات النسوية","t":"learn","x":"الموجات: السياسة، فالثقافة، فالأكاديميا، والرابعة التكنولوجيا. وكل موجة بتتعرف بأهدافها وأدواتها، مش بالتواريخ بس."},{"i":"comp-21","s":15,"h":"4) مصطلحات النسوية","t":"learn","x":"النظام الأبوي: بنية سلطة بتمنح الرجل موقع أعلى. والجندر: البناء الاجتماعي للأدوار، مقابل الجنس البيولوجي."},{"i":"comp-21","s":16,"h":"4) مصطلحات النسوية","t":"mc","x":"إيه الفرق بين التأثير والتناص؟ ؟ التأثير أثر في اتجاه واحد، والتناص حوار مفتوح بين النصوص / التأثير للمسرح والتناص للشعر / التأثير فرنسي والتناص إنجليزي / الاتنين نفس الحاجة . الاتجاه هو الفرق الجوهري."},{"i":"comp-21","s":17,"h":"4) مصطلحات النسوية","t":"learn","x":"التقاطع: تراكب جوانب الهوية وتضاعف القهر. والامتياز: مزايا غير مستحقة بتيجي من موقع الشخص."},{"i":"comp-21","s":19,"h":"5) مصطلحات بوفوار","t":"learn","x":"المرأة ك«آخر»: موقع ثانوي بيتعرف بالنسبة للرجل. و«الأنوثة الأبدية»: أسطورة إن فيه طبيعة أنثوية ثابتة بتتبرر أدوار."},{"i":"comp-21","s":20,"h":"5) مصطلحات بوفوار","t":"learn","x":"والفاعلية: قدرة الشخص ياخد قرار بحياته. ودي الكلمة اللي بتربط النظرية بالرواية: مريم وصلت للفاعلية في الذروة."},{"i":"comp-21","s":21,"h":"5) مصطلحات بوفوار","t":"mc","x":"إيه اللي بيميز المدرسة الصينية عن الفرنسية والأمريكية؟ ؟ إنها بتشتغل على التغاير بين حضارات مختلفة، مش جوه حضارة واحدة / إنها بتدرس الشعر بس / إنها رفضت فكرة التأثير تماما / إنها أنكرت وجود الأدب المقارن . مركزها اختلاف الحضارات، وده اللي بيميزها."},{"i":"comp-21","s":23,"h":"6) إزاي تستخدم المصطلح","t":"learn","x":"المصطلح مش زينة في الكلام. لو قلت «تناص» لازم تقدر تقول إيه الحوار بين النصين. ولو قلت «تقاطع» لازم تقدر تقول إيه الجوانب اللي بتتراكب."},{"i":"comp-21","s":24,"h":"6) إزاي تستخدم المصطلح","t":"learn","x":"ولو قلت «وضعية» لازم تقدر تقول إيه الدليل الواقعي اللي البحث بيدور عليه. من غير كده، المصطلح بيبقى كلمة كبيرة بلا معنى."},{"i":"comp-21","s":25,"h":"6) إزاي تستخدم المصطلح","t":"learn","x":"الدرس الجاي: مراجعة شاملة وأسئلة على شكل امتحان، وإزاي تبني إجابة قوية."},{"i":"comp-21","s":26,"h":"6) إزاي تستخدم المصطلح","t":"mc","x":"إيه الفرق بين الجنس والجندر؟ ؟ الجنس بيولوجي، والجندر بناء اجتماعي بيتغير بين الثقافات / الجنس بناء اجتماعي، والجندر بيولوجي / الاتنين بيولوجي / الاتنين بناء اجتماعي . التمييز الأساسي: بيولوجي مقابل اجتماعي."},{"i":"comp-21","s":27,"h":"6) إزاي تستخدم المصطلح","t":"recall","x":"اختصر الكورس كله في خمس مصطلحات أساسية، وحدد مكان كل واحد. . الأدب المقارن (المجال والتعريف)، والتأثير والمصدر (المدرسة الفرنسية)، والتناص (المدرسة الأمريكية)، والتغاير (المدرسة الصينية)، والتقاطع والجندر والفاعلية (النسوية وبوفوار). كل مصطلح بيخص مرحلة أو أداة في الكورس."},{"i":"comp-21","s":28,"h":"6) إزاي تستخدم المصطلح","t":"recall","x":"إيه الفرق بين المصدر والناقل؟ . المصدر هو النص اللي منه جه الأثر، والناقل هو الوسيط اللي بينقل الأثر من ثقافة لتانية، زي ترجمة أو مجلة أو رحالة. دراسة المصدر بتدور على الأصل، ودراسة النقل بتدور على الوسيلة."},{"i":"comp-21","s":29,"h":"6) إزاي تستخدم المصطلح","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ أنهي جملة من دول صحيحة؟ / بالعكس: الأدب العالمي ظاهرة، والأدب المقارن منهج. / الأفكار قديمة، لكن الحركة المنظمة اتشكلت في آخر القرن التسعتاشر. / «الأنوثة الأبدية» فكرة بتؤكد إن الأنوثة تكوين اجتماعي. . بالعكس: الأسطورة بتقول إنها طبيعة ثابتة، وبوفوار طالبت بإلغائها."},{"i":"comp-21","s":30,"h":"6) إزاي تستخدم المصطلح","t":"write","x":"اشرح إزاي مصطلح «الفاعلية» بيربط بين بوفوار والرواية. . بوفوار آمنت إن المجتمع بيشكل المرأة، لكن الإنسان عنده قدرة يختار ويقاوم، ودي الفاعلية. وفي الرواية، مريم عاشت حياتها بقرارات غيرها: أبوها زوجها، ورشيد حبسها، والعنف خلاها تصدق إنها مش مستحقة الحب. في الذروة، أول مرة تاخد قرار بحياتها لما تقتل رشيد وتسلم نفسها عشان ليلى. فالفاعلية هنا مش كلمة نظرية، هي لحظة في الحكاية."},{"i":"comp-22","s":1,"h":"مقدمة","t":"learn","x":"آخر درس في الكورس. مش درس جديد، ده درس عن إزاي تستخدم اللي اتعلمته. الفرق بين طالب بيحفظ وطالب بيفهم إن الأول بيعرف التعريف، والتاني بيعرف يستخدمه."},{"i":"comp-22","s":3,"h":"1) خريطة الكورس","t":"learn","x":"الكورس مشي في ست وحدات. 1) المجال وتعريفه. 2) نشأته والمدرسة الفرنسية. 3) المدرسة الأمريكية والترجمة. 4) المدرسة الصينية والتغاير. 5) النسوية وموجاتها. 6) بوفوار وقراءة الرواية."},{"i":"comp-22","s":4,"h":"1) خريطة الكورس","t":"learn","x":"وكل وحدة بتبني على اللي قبلها: من «إيه هو المجال» ل«إزاي أقرأ نص بعين نظرية»."},{"i":"comp-22","s":6,"h":"2) تلات أنواع أسئلة","t":"learn","x":"أسئلة التعريف: عرف المصطلح، واذكر مصدره، وادي مثال. مثال: الأدب المقارن، تعريف ريماك 1961، ومثال على دراسة تقارن أدبين."},{"i":"comp-22","s":7,"h":"2) تلات أنواع أسئلة","t":"learn","x":"أسئلة المقارنة: اعرض الطرفين، وحدد محور الاختلاف. مش كفاية تقول «الاتنين مختلفين»، لازم تقول مختلفين في إيه: المنهج؟ الهدف؟ الأداة؟"},{"i":"comp-22","s":8,"h":"2) تلات أنواع أسئلة","t":"mc","x":"إيه أفضل طريقة تراجع بيها مصطلح مش واضح؟ ؟ ترجع للدرس اللي شرحه في الكورس / تدور عليه في أي قاموس / تسيبه وتكمل / تحفظ تعريفه من غير فهم . المصطلح مرتبط بسياقه في الكورس."},{"i":"comp-22","s":9,"h":"2) تلات أنواع أسئلة","t":"learn","x":"أسئلة التطبيق: خد النظرية وطبقها على نص، واستشهد من النص. وده أصعب نوع، لأنه بيكشف هل فهمت النظرية ولا حفظتها."},{"i":"comp-22","s":10,"h":"2) تلات أنواع أسئلة","t":"mc","x":"إيه اللي بيميز سؤال التطبيق؟ ؟ إنك تستخدم النظرية على نص وتستشهد من النص / إنك تعرف المصطلح بس / إنك تسرد أحداث النص / إنك تذكر أسماء الباحثين . التطبيق = نظرية + دليل من النص."},{"i":"comp-22","s":12,"h":"3) أخطاء بتتكرر","t":"learn","x":"أشهر غلط: سرد الأحداث بدل التحليل. لو السؤال بيسأل عن السلطة في الرواية، مش مطلوب تحكي الحكاية، مطلوب تقول إزاي السلطة بتشتغل ومين بيدفع التمن."},{"i":"comp-22","s":13,"h":"3) أخطاء بتتكرر","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ الخلط بين الموجات النسوية ممكن يخلي الإجابة غلط حتى لو الكلام مكتوب بشكل جيد. / المقارنة موجودة قبل كده، اللي ظهر في القرن التسعتاشر هو المادة والمنهج. / القارئ اللي يعرف النص القديم بيقرأ طبقة زيادة، لكن النص بيشتغل من غير كده كمان. / في سؤال المقارنة يكفي تقول إن الطرفين مختلفين من غير ما تحدد محور الاختلاف. . المطلوب تحديد محور الاختلاف: المنهج أو الهدف أو الأداة."},{"i":"comp-22","s":14,"h":"3) أخطاء بتتكرر","t":"learn","x":"تاني غلط: خلط التأثير بالتناص. التأثير بيدور على أصل ودليل في اتجاه، والتناص بيدور على حوار مفتوح."},{"i":"comp-22","s":15,"h":"3) أخطاء بتتكرر","t":"learn","x":"تالت غلط: اختزال النسوية في «كره الرجالة»، أو خلط الموجات ببعضها. كل موجة لها هدف وأداة، والخلط بيدي إجابة غلط حتى لو الكلام حلو."},{"i":"comp-22","s":16,"h":"3) أخطاء بتتكرر","t":"mc","x":"إيه الغلط الأشهر في إجابات الأسئلة الأدبية؟ ؟ سرد الأحداث بدل تحليلها / استخدام مصطلحات / ذكر سنة النشر / الاستشهاد من النص . السرد مش تحليل، وده أشهر خطأ."},{"i":"comp-22","s":18,"h":"4) إزاي تبني فقرة تحليل","t":"learn","x":"الفقرة القوية فيها تلات حاجات. فكرة واضحة في أول سطر. دليل من النص أو من النظرية. شرح للرابط بين الفكرة والدليل."},{"i":"comp-22","s":19,"h":"4) إزاي تبني فقرة تحليل","t":"learn","x":"مثال: «رشيد بيمارس سلطة على مستوى البيت، وده بيبان في منعه للمية بعد محاولة الهروب». الفكرة موجودة، والدليل موجود، والرابط واضح."},{"i":"comp-22","s":21,"h":"5) خطة المراجعة","t":"learn","x":"ابدأ بالمصطلحات، وبعدها المقارنات، وبعدها التطبيقات. واختبر نفسك بسؤال من كل وحدة، وحاول تجاوب بصوت عالي قبل ما تشوف الإجابة."},{"i":"comp-22","s":22,"h":"5) خطة المراجعة","t":"learn","x":"ولو لقيت مصطلح مش فاهمه، ارجع للدرس اللي شرحه، مش للقاموس. لأن المصطلح في الكورس ده معناه مرتبط بسياقه، وممكن يبقى له معنى مختلف في مجال تاني."},{"i":"comp-22","s":23,"h":"5) خطة المراجعة","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ أنهي جملة من دول غلط؟ / الخلط بين الموجات النسوية ممكن يخلي الإجابة غلط حتى لو الكلام مكتوب بشكل جيد. / أنهي جملة من دول غلط؟ / أنهي جملة من دول غلط؟ . كل موجة لها هدف وأداة، والخلط بيفسد التحليل."},{"i":"comp-22","s":25,"h":"6) ختام","t":"learn","x":"الكورس ده بنى عندك تلات قدرات. إنك تعرف المجال ومدارسه، وإنك تقرأ نص بعين نظرية، وإنك تسأل سؤال نقدي وتدور على دليل."},{"i":"comp-22","s":26,"h":"6) ختام","t":"learn","x":"والقدرات دي مش بتخص مادة واحدة، هي طريقة تفكير تنفع مع أي نص تقراه بعد كده."},{"i":"comp-22","s":27,"h":"6) ختام","t":"mc","x":"إيه اللي الكورس بيدربه عندك في النهاية؟ ؟ إنك تعرف المجال ومدارسه، وتقرأ نص بعين نظرية، وتسأل سؤال نقدي بدليل / إنك تحفظ تواريخ بس / إنك تسرد حكايات الروايات / إنك تجمع أسماء باحثين . القدرات التلاتة دي هي حصيلة الكورس."},{"i":"comp-22","s":28,"h":"6) ختام","t":"recall","x":"اذكر تلات أنواع أسئلة في الكورس، وإيه المطلوب في كل نوع. . التعريف: المصطلح ومصدره ومثال. المقارنة: الطرفين ومحور الاختلاف. التطبيق: نظرية مطبقة على نص مع دليل من النص."},{"i":"comp-22","s":29,"h":"6) ختام","t":"recall","x":"إيه الفرق بين سرد الحكاية وتحليلها؟ . السرد بيقول إيه اللي حصل بالترتيب، والتحليل بيسأل ليه وإزاي: إيه علاقات السلطة، ومين بيدفع التمن، وإيه الدليل على الكلام ده من النص."},{"i":"comp-22","s":30,"h":"6) ختام","t":"write","x":"جاوب على سؤال تطبيقي: إزاي تقرأ مشهد من الرواية بعين بوفوار؟ . أختار مشهد مضغ الحصى. بوفوار بتقول إن المرأة بتتحط في موقع الآخر والموضوع، وإن الأنوثة تكوين اجتماعي. في المشهد، رشيد بيعاقب مريم على أرز مش مستوي بعقاب مهين، ومريم بتقبل العقاب وتبدأ تصدق إنها مش مستحقة الحب. التحليل: العقاب مش مجرد رد فعل على طبخ، ده إعادة تأكيد لموقعها كموضوع في البيت، والنتيجة إنها بتستبطن الصورة اللي بيفرضها عليها. والدليل إن الرواية بتربط العنف ده بتصورها عن نفسها بعد كده."}]};